{
  "status": "formalized",
  "smt2": "(set-logic QF_LRA)\n; is_measurement_period_end: true iff the observation date is the end of a Measurement Period.\n; any_lender_has_commitment: true iff any Lender has any Commitment under the agreement at this observation.\n; any_loan_or_obligation_unpaid: true iff any Loan or other Obligation remains unpaid or unsatisfied, excluding contingent indemnification obligations for which no claim has been made.\n; any_uncollateralized_letter_of_credit_outstanding: true iff any Letter of Credit remains outstanding, excluding Letters of Credit that have been Cash Collateralized.\n; consolidated_interest_coverage_ratio: Consolidated Interest Coverage Ratio as of the end of the Measurement Period, as a plain number (3.50:1.00 is 3.5).\n; consolidated_leverage_ratio: Consolidated Leverage Ratio as of the end of the Measurement Period, as a plain number (2.00:1.00 is 2.0).\n(define-fun covenant_holds ((is_measurement_period_end Bool) (any_lender_has_commitment Bool) (any_loan_or_obligation_unpaid Bool) (any_uncollateralized_letter_of_credit_outstanding Bool) (consolidated_interest_coverage_ratio Real) (consolidated_leverage_ratio Real)) Bool\n  (=> (and is_measurement_period_end\n           (or any_lender_has_commitment\n               any_loan_or_obligation_unpaid\n               any_uncollateralized_letter_of_credit_outstanding))\n      (and (>= consolidated_interest_coverage_ratio 3.5)\n           (<= consolidated_leverage_ratio 2.0))))",
  "symbols": [
    {
      "name": "is_measurement_period_end",
      "meaning": "True iff the observation date is the end of a Measurement Period, the date as of which the ratios are tested.",
      "source_quote": "as of the end of any Measurement Period"
    },
    {
      "name": "any_lender_has_commitment",
      "meaning": "True iff any Lender has any Commitment under the agreement at this observation.",
      "source_quote": "any Lender shall have any Commitment hereunder"
    },
    {
      "name": "any_loan_or_obligation_unpaid",
      "meaning": "True iff any Loan or other Obligation remains unpaid or unsatisfied, excluding contingent indemnification obligations for which no claim has been made.",
      "source_quote": "any Loan or other Obligation (other than contingent indemnification obligations for which no claim has been made) hereunder shall remain unpaid or unsatisfied"
    },
    {
      "name": "any_uncollateralized_letter_of_credit_outstanding",
      "meaning": "True iff any Letter of Credit remains outstanding, excluding Letters of Credit that have been Cash Collateralized.",
      "source_quote": "any Letter of Credit shall remain outstanding (other than Letters of Credit which have been Cash Collateralized)"
    },
    {
      "name": "consolidated_interest_coverage_ratio",
      "meaning": "Consolidated Interest Coverage Ratio as of the end of the Measurement Period, as a plain number (3.50:1.00 is 3.5). Atomic because its definition is not supplied.",
      "source_quote": "Consolidated Interest Coverage Ratio"
    },
    {
      "name": "consolidated_leverage_ratio",
      "meaning": "Consolidated Leverage Ratio as of the end of the Measurement Period, as a plain number (2.00:1.00 is 2.0). Atomic because its definition is not supplied.",
      "source_quote": "Consolidated Leverage Ratio"
    }
  ],
  "notes": "The covenant is a negative covenant. Not permitting the Interest Coverage Ratio to be less than 3.50:1.00 means the ratio must be >= 3.5. Not permitting the Leverage Ratio to be greater than 2.00:1.00 means the ratio must be <= 2.0. The two tests are conjoined and apply at the end of a Measurement Period. The covenant applies only while at least one of the three 'so long as' conditions holds, so they are kept as separate Booleans and combined with OR. The source's 'less 3.50:1.00' is read as 'less than'. The ratios are atomic inputs because their definitions are not supplied."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_LRA)\n; total_net_leverage_ratio: Total Net Leverage Ratio of the Borrower as of the last day of the Test Period being observed, expressed as a ratio X in X to 1.00 (atomic input; definition not supplied).\n; test_period_ends_in_period_1: True iff the observed Test Period ends during July 1, 2017 - December 31, 2017 (inclusive).\n; test_period_ends_in_period_2: True iff the observed Test Period ends during January 1, 2018 - June 30, 2018 (inclusive).\n; test_period_ends_in_period_3: True iff the observed Test Period ends during July 1, 2018 - December 31, 2018 (inclusive).\n; test_period_ends_in_period_4: True iff the observed Test Period ends on or after January 1, 2019.\n(define-fun covenant_holds ((total_net_leverage_ratio Real) (test_period_ends_in_period_1 Bool) (test_period_ends_in_period_2 Bool) (test_period_ends_in_period_3 Bool) (test_period_ends_in_period_4 Bool)) Bool\n  (and\n    (=> test_period_ends_in_period_1 (<= total_net_leverage_ratio 2.5))\n    (=> test_period_ends_in_period_2 (<= total_net_leverage_ratio 2.25))\n    (=> test_period_ends_in_period_3 (<= total_net_leverage_ratio 2.0))\n    (=> test_period_ends_in_period_4 (<= total_net_leverage_ratio 1.75))))",
  "symbols": [
    {
      "name": "total_net_leverage_ratio",
      "meaning": "Total Net Leverage Ratio of the Borrower as of the last day of the Test Period being observed, expressed as X in X to 1.00 (atomic input; definition not supplied).",
      "source_quote": "Total Net Leverage Ratio as of the last day of any Test Period"
    },
    {
      "name": "test_period_ends_in_period_1",
      "meaning": "True iff the observed Test Period ends during July 1, 2017 - December 31, 2017 (inclusive).",
      "source_quote": "July 1, 2017 - December 31, 2017 2.50 to 1.00"
    },
    {
      "name": "test_period_ends_in_period_2",
      "meaning": "True iff the observed Test Period ends during January 1, 2018 - June 30, 2018 (inclusive).",
      "source_quote": "January 1, 2018 - June 30, 2018 2.25 to 1.00"
    },
    {
      "name": "test_period_ends_in_period_3",
      "meaning": "True iff the observed Test Period ends during July 1, 2018 - December 31, 2018 (inclusive).",
      "source_quote": "July 1, 2018 - December 31, 2018 2.00 to 1.00"
    },
    {
      "name": "test_period_ends_in_period_4",
      "meaning": "True iff the observed Test Period ends on or after January 1, 2019.",
      "source_quote": "January 1, 2019 and thereafter 1.75 to 1.00"
    }
  ],
  "notes": "Pointwise translation: each observation is a Test Period end date. The ratio must not exceed (be <=) the maximum for the period in which that Test Period ends, so the bounds are non-strict: 2.50, 2.25, 2.00 and 1.75. Each period flag guards its own bound with an implication, so a flag that is false leaves the others unaffected. The calendar flags are supplied by the evaluator and should be mutually exclusive. The Article VI preamble (the covenant lasts until commitments terminate and obligations are paid) is a duration condition on the covenant, not an observation-level input, so it is not encoded. The ratio's arithmetic definition is not supplied, so it stays atomic."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n(define-fun covenant_holds (\n  (consolidated_total_liabilities Real) ; Consolidated Total Liabilities of Borrower and its consolidated Subsidiaries at the observation date (numerator of the ratio)\n  (consolidated_tangible_net_worth Real) ; Consolidated Tangible Net Worth of Borrower and its consolidated Subsidiaries at the observation date (denominator of the ratio)\n  (is_fiscal_quarter_end Bool) ; true iff the observation date is the end of a fiscal quarter\n  (in_period_a Bool) ; true iff the observation date is within December 31, 1996 until December 30, 1997\n  (in_period_b Bool) ; true iff the observation date is within December 31, 1997 through December 30, 1998\n  (in_period_c Bool) ; true iff the observation date is on or after December 31, 1998\n  ) Bool\n  (and\n    (=> (and is_fiscal_quarter_end in_period_a)\n        (<= (/ consolidated_total_liabilities consolidated_tangible_net_worth) 1.25))\n    (=> (and is_fiscal_quarter_end in_period_b)\n        (<= (/ consolidated_total_liabilities consolidated_tangible_net_worth) 1.0))\n    (=> (and is_fiscal_quarter_end in_period_c)\n        (<= (/ consolidated_total_liabilities consolidated_tangible_net_worth) 0.75))))",
  "symbols": [
    {
      "name": "consolidated_total_liabilities",
      "meaning": "Consolidated Total Liabilities of Borrower and its consolidated Subsidiaries at the observation date (numerator of the ratio)",
      "source_quote": "Consolidated Total Liabilities"
    },
    {
      "name": "consolidated_tangible_net_worth",
      "meaning": "Consolidated Tangible Net Worth of Borrower and its consolidated Subsidiaries at the observation date (denominator of the ratio)",
      "source_quote": "Consolidated Tangible Net Worth"
    },
    {
      "name": "is_fiscal_quarter_end",
      "meaning": "True iff the observation date is the end of a fiscal quarter",
      "source_quote": "as at the end of any fiscal quarter"
    },
    {
      "name": "in_period_a",
      "meaning": "True iff the observation date is within December 31, 1996 until December 30, 1997",
      "source_quote": "As at December 31, 1996 until December 30, 1997"
    },
    {
      "name": "in_period_b",
      "meaning": "True iff the observation date is within December 31, 1997 through December 30, 1998",
      "source_quote": "from December 31, 1997 through December 30, 1998"
    },
    {
      "name": "in_period_c",
      "meaning": "True iff the observation date is on or after December 31, 1998",
      "source_quote": "from December 31, 1998 and at any time of the determination thereof thereafter"
    }
  ],
  "notes": "The ratio is computed as Consolidated Total Liabilities divided by Consolidated Tangible Net Worth. A zero denominator is left to the evaluator to report as unresolved, and no sign assumptions are made. 'Not more than' is encoded as <=. Thresholds are 1.25:1.0, 1.0:1.0 and .75:1.0 for the three periods. The lead-in 'as at the end of any fiscal quarter' is applied to all three periods, including period (c), so the 'at any time of the determination thereof thereafter' wording is read as determination at quarter-ends. Period flags are evaluator-supplied and are not enforced to be mutually exclusive. The logic is QF_NRA because the ratio divides one variable by another."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n(define-fun covenant_holds (\n  (is_fiscal_quarter_end Bool) ; True iff the observation is the last day / end of a fiscal quarter of the Borrower (applicability of 6.10(a) and 6.10(b))\n  (indebtedness_principal Real) ; Aggregate principal amount of Indebtedness of the Borrower and its Restricted Subsidiaries as of the test day, excluding Indebtedness of the type in clause (i)(D) of the definition of Indebtedness\n  (cash_investments Real) ; Aggregate amount of Cash Investments as of the test day, subtracted from the Indebtedness amount\n  (annualized_combined_case_revenues Real) ; Annualized Combined Case Revenues for the fiscal quarter; the covenant denominator is this value times two\n  (dedicated_customers Real) ; Number of Dedicated Customers at the end of the fiscal quarter\n  (is_period_mar_31_1998 Bool) ; True iff the fiscal quarter ends on March 31, 1998 (minimum $17,000,000)\n  (is_period_jun_30_1998 Bool) ; True iff the fiscal quarter ends on June 30, 1998 (minimum $20,000,000)\n  (is_period_sep_30_1998 Bool) ; True iff the fiscal quarter ends on September 30, 1998 (minimum $22,000,000)\n  (is_period_dec_31_1998 Bool) ; True iff the fiscal quarter ends on December 31, 1998 (minimum $26,000,000)\n  (is_period_mar_30_1999 Bool) ; True iff the fiscal quarter ends on March 30, 1999, as dated in the source (minimum $29,000,000)\n  (is_period_jun_30_1999 Bool) ; True iff the fiscal quarter ends on June 30, 1999 (minimum $32,000,000)\n  (is_period_sep_30_1999_or_later Bool) ; True iff the fiscal quarter ends on September 30, 1999 or any later date (minimum $36,000,000)\n  (combined_case_revenues Real) ; Combined Case Revenues for the fiscal quarter, in dollars\n  (excluded_fees Real) ; Aggregate amount of Excluded Fees for the fiscal quarter, in dollars, subtracted from Combined Case Revenues\n) Bool\n  (and\n    ; 6.10(a): (Indebtedness - Cash Investments) / (Annualized Combined Case Revenues * 2) must not be greater than 2.35\n    (=> is_fiscal_quarter_end\n        (<= (/ (- indebtedness_principal cash_investments)\n               (* 2.0 annualized_combined_case_revenues))\n            2.35))\n    ; 6.10(b): Dedicated Customers must not be less than 7,000\n    (=> is_fiscal_quarter_end (>= dedicated_customers 7000.0))\n    ; 6.10(c): Combined Case Revenues minus Excluded Fees must not be less than the scheduled amount\n    (=> is_period_mar_31_1998 (>= (- combined_case_revenues excluded_fees) 17000000.0))\n    (=> is_period_jun_30_1998 (>= (- combined_case_revenues excluded_fees) 20000000.0))\n    (=> is_period_sep_30_1998 (>= (- combined_case_revenues excluded_fees) 22000000.0))\n    (=> is_period_dec_31_1998 (>= (- combined_case_revenues excluded_fees) 26000000.0))\n    (=> is_period_mar_30_1999 (>= (- combined_case_revenues excluded_fees) 29000000.0))\n    (=> is_period_jun_30_1999 (>= (- combined_case_revenues excluded_fees) 32000000.0))\n    (=> is_period_sep_30_1999_or_later (>= (- combined_case_revenues excluded_fees) 36000000.0))\n  )\n)",
  "symbols": [
    {
      "name": "is_fiscal_quarter_end",
      "meaning": "True iff the observation is the last day / end of a fiscal quarter of the Borrower (applicability of 6.10(a) and 6.10(b))",
      "source_quote": "at the last day of any fiscal quarter"
    },
    {
      "name": "indebtedness_principal",
      "meaning": "Aggregate principal amount of Indebtedness of the Borrower and its Restricted Subsidiaries as of the test day, excluding Indebtedness of the type in clause (i)(D) of the definition of Indebtedness",
      "source_quote": "aggregate principal amount of Indebtedness of the Borrower and its Restricted Subsidiaries"
    },
    {
      "name": "cash_investments",
      "meaning": "Aggregate amount of Cash Investments as of the test day, subtracted from the Indebtedness amount",
      "source_quote": "the aggregate amount of Cash Investments as of such day"
    },
    {
      "name": "annualized_combined_case_revenues",
      "meaning": "Annualized Combined Case Revenues for the fiscal quarter; the covenant denominator is this value times two",
      "source_quote": "Annualized Combined Case Revenues for such fiscal quarter times two"
    },
    {
      "name": "dedicated_customers",
      "meaning": "Number of Dedicated Customers at the end of the fiscal quarter",
      "source_quote": "the number of Dedicated Customers"
    },
    {
      "name": "is_period_mar_31_1998",
      "meaning": "True iff the fiscal quarter ends on March 31, 1998 (minimum $17,000,000)",
      "source_quote": "March 31, 1998 $17,000,000"
    },
    {
      "name": "is_period_jun_30_1998",
      "meaning": "True iff the fiscal quarter ends on June 30, 1998 (minimum $20,000,000)",
      "source_quote": "June 30, 1998 $20,000,000"
    },
    {
      "name": "is_period_sep_30_1998",
      "meaning": "True iff the fiscal quarter ends on September 30, 1998 (minimum $22,000,000)",
      "source_quote": "September 30, 1998 $22,000,000"
    },
    {
      "name": "is_period_dec_31_1998",
      "meaning": "True iff the fiscal quarter ends on December 31, 1998 (minimum $26,000,000)",
      "source_quote": "December 31, 1998 $26,000,000"
    },
    {
      "name": "is_period_mar_30_1999",
      "meaning": "True iff the fiscal quarter ends on March 30, 1999, as dated in the source (minimum $29,000,000)",
      "source_quote": "March 30, 1999 $29,000,000"
    },
    {
      "name": "is_period_jun_30_1999",
      "meaning": "True iff the fiscal quarter ends on June 30, 1999 (minimum $32,000,000)",
      "source_quote": "June 30, 1999 $32,000,000"
    },
    {
      "name": "is_period_sep_30_1999_or_later",
      "meaning": "True iff the fiscal quarter ends on September 30, 1999 or any later date (minimum $36,000,000)",
      "source_quote": "September 30, 1999 and thereafter $36,000,000"
    },
    {
      "name": "combined_case_revenues",
      "meaning": "Combined Case Revenues for the fiscal quarter, in dollars",
      "source_quote": "Combined Case Revenues for any fiscal quarter ending on the respective dates set forth below"
    },
    {
      "name": "excluded_fees",
      "meaning": "Aggregate amount of Excluded Fees for the fiscal quarter, in dollars, subtracted from Combined Case Revenues",
      "source_quote": "the aggregate amount of Excluded Fees for such quarter"
    }
  ],
  "notes": "Each prohibition (\"will not permit ... to be greater than 2.35 to 1\" / \"less than\") is encoded as its complement: ratio <= 2.35, customers >= 7000, and (Combined Case Revenues - Excluded Fees) >= scheduled amount. The 6.10(a) denominator is encoded literally as Annualized Combined Case Revenues times two, as written. Division is left to the evaluator's unresolved-on-zero policy, so no denominator-positivity assumption is made. The same quarter-end flag is used for 6.10(a) and 6.10(b) because both apply at the end of any fiscal quarter. The March 30, 1999 date is kept as written in the source. Each 6.10(c) row is guarded by its own calendar flag. The introductory 'Until the Commitments have expired...' clause is treated as the duration of the covenant, so it is not encoded as a separate input."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n; any_note_unpaid: True iff at this observation any Note remains unpaid.\n; any_bank_commitment: True iff at this observation any Bank has any Commitment under the Agreement.\n; consolidated_debt: Consolidated Debt of the Borrower at the observation time.\n; ctnw_before_exclusions: Consolidated Tangible Net Worth at the observation time before deducting the Section 7.02 exclusions (Investments in Joint Ventures and in non-Guarantor Subsidiaries).\n; investments_in_joint_ventures: Investments of the Borrower and Guarantors in Joint Ventures, to be excluded from Consolidated Tangible Net Worth.\n; investments_in_non_guarantor_subsidiaries: Investments of the Borrower and Guarantors in Subsidiaries that are not Guarantors, to be excluded from Consolidated Tangible Net Worth.\n; interest_coverage_ratio: The Borrower's Interest Coverage Ratio at the observation time, as a multiple of 1.0 (e.g. 2.5 means 2.5 to 1.0).\n(define-fun covenant_holds (\n    (any_note_unpaid Bool)\n    (any_bank_commitment Bool)\n    (consolidated_debt Real)\n    (ctnw_before_exclusions Real)\n    (investments_in_joint_ventures Real)\n    (investments_in_non_guarantor_subsidiaries Real)\n    (interest_coverage_ratio Real)) Bool\n  (=> (or any_note_unpaid any_bank_commitment)\n      (<= (/ consolidated_debt\n             (- ctnw_before_exclusions\n                investments_in_joint_ventures\n                investments_in_non_guarantor_subsidiaries))\n          (ite (>= interest_coverage_ratio 2.5) 2.25 2.0))))",
  "symbols": [
    {
      "name": "any_note_unpaid",
      "meaning": "True iff at the observation time any Note remains unpaid (covenant-applicability condition).",
      "source_quote": "any Note shall remain unpaid"
    },
    {
      "name": "any_bank_commitment",
      "meaning": "True iff at the observation time any Bank has any Commitment under the Agreement (covenant-applicability condition).",
      "source_quote": "any Bank shall have any Commitment under this Agreement"
    },
    {
      "name": "consolidated_debt",
      "meaning": "Consolidated Debt at the observation time (numerator of the leverage ratio).",
      "source_quote": "Consolidated Debt"
    },
    {
      "name": "ctnw_before_exclusions",
      "meaning": "Consolidated Tangible Net Worth at the observation time before deducting the Section 7.02 exclusions for Investments in Joint Ventures and in non-Guarantor Subsidiaries.",
      "source_quote": "Consolidated Tangible Net Worth"
    },
    {
      "name": "investments_in_joint_ventures",
      "meaning": "Investments of the Borrower and Guarantors in Joint Ventures, deducted from Consolidated Tangible Net Worth for Section 7.02.",
      "source_quote": "Investments in Joint Ventures"
    },
    {
      "name": "investments_in_non_guarantor_subsidiaries",
      "meaning": "Investments of the Borrower and Guarantors in Subsidiaries that are not Guarantors, deducted from Consolidated Tangible Net Worth for Section 7.02.",
      "source_quote": "in Subsidiaries that are not Guarantors"
    },
    {
      "name": "interest_coverage_ratio",
      "meaning": "The Borrower's Interest Coverage Ratio at the observation time, as a multiple of 1.0. A value of at least 2.5 selects the 2.25 maximum; otherwise the 2.0 maximum applies.",
      "source_quote": "Interest Coverage Ratio of at least 2.5 to 1.0"
    }
  ],
  "notes": "Applicability is the Article VII lead-in: any Note unpaid OR any Bank Commitment. The leverage ratio is Consolidated Debt divided by Consolidated Tangible Net Worth, where net worth is the pre-exclusion figure less the two stated investment exclusions. The maximum is 2.25 if the Interest Coverage Ratio is >= 2.5 (non-strict), otherwise 2.0, and the ratio test is non-strict (<=). A zero net worth denominator is left for the evaluator to report as unresolved, and no sign or positivity assumption is made. QF_NRA is used because the divisor is a variable expression."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_LRA)\n; secured_leverage_ratio: Secured Leverage Ratio of Parent for the Test Period being observed, as an atomic ratio (e.g. 3.00 means 3.00:1.00).\n; interest_coverage_ratio: Interest Coverage Ratio of Parent for the Test Period being observed, as an atomic ratio (e.g. 3.50 means 3.50:1.00).\n; test_period_ends_on_or_after_2015_09_30: true iff the observed Test Period ends on or after September 30, 2015, the first Test Period to which Section 7.10(a) and (b) apply.\n; holiday_written_notice_given: true iff Parent gave written notice to the Administrative Agent electing the Secured Leverage Holiday for the Relevant Acquisition relevant to this observation.\n; holiday_acquisition_consideration_usd: aggregate consideration, in US dollars, paid by Parent and its Restricted Subsidiaries for the Permitted Acquisition relevant to this observation.\n; holiday_acquisition_is_permitted_acquisition: true iff the acquisition relevant to this observation is a Permitted Acquisition.\n; holiday_use_count: number of Secured Leverage Holidays elected between the Closing Date and the Maturity Date, counting the holiday relevant to this observation. If no holiday is relevant, supply 0.\n; test_period_in_holiday_350_stage: true iff the observed Test Period is the current period for testing a Relevant Acquisition, or one of the next two Test Periods following the closing date of that acquisition.\n; test_period_in_holiday_325_stage: true iff the observed Test Period is one of the next two succeeding Test Periods (the third and fourth after the closing date) after the 3.50 stage of that acquisition.\n(define-fun covenant_holds (\n    (secured_leverage_ratio Real)\n    (interest_coverage_ratio Real)\n    (test_period_ends_on_or_after_2015_09_30 Bool)\n    (holiday_written_notice_given Bool)\n    (holiday_acquisition_consideration_usd Real)\n    (holiday_acquisition_is_permitted_acquisition Bool)\n    (holiday_use_count Real)\n    (test_period_in_holiday_350_stage Bool)\n    (test_period_in_holiday_325_stage Bool)) Bool\n  (let ((holiday_valid (and holiday_written_notice_given\n                            holiday_acquisition_is_permitted_acquisition\n                            (> holiday_acquisition_consideration_usd 250000000.0)\n                            (<= holiday_use_count 2.0))))\n    (let ((max_secured_leverage\n           (ite (and holiday_valid test_period_in_holiday_350_stage) 3.5\n                (ite (and holiday_valid test_period_in_holiday_325_stage) 3.25 3.0))))\n      (=> test_period_ends_on_or_after_2015_09_30\n          (and (<= secured_leverage_ratio max_secured_leverage)\n               (>= interest_coverage_ratio 3.5))))))",
  "symbols": [
    {
      "name": "secured_leverage_ratio",
      "meaning": "Secured Leverage Ratio of Parent for the Test Period being observed, as an atomic ratio (3.00 means 3.00:1.00).",
      "source_quote": "Maximum Secured Leverage Ratio"
    },
    {
      "name": "interest_coverage_ratio",
      "meaning": "Interest Coverage Ratio of Parent for the Test Period being observed, as an atomic ratio (3.50 means 3.50:1.00).",
      "source_quote": "Minimum Interest Coverage Ratio"
    },
    {
      "name": "test_period_ends_on_or_after_2015_09_30",
      "meaning": "True iff the observed Test Period ends on or after September 30, 2015, the first Test Period to which the financial covenants apply.",
      "source_quote": "commencing with the Test Period ending September 30, 2015"
    },
    {
      "name": "holiday_written_notice_given",
      "meaning": "True iff Parent gave written notice to the Administrative Agent electing the Secured Leverage Holiday for the Relevant Acquisition relevant to this observation.",
      "source_quote": "upon written notice to the Administrative Agent"
    },
    {
      "name": "holiday_acquisition_consideration_usd",
      "meaning": "Aggregate consideration in US dollars paid by Parent and its Restricted Subsidiaries for the Permitted Acquisition relevant to this observation.",
      "source_quote": "the payment of aggregate consideration by Parent and its Restricted Subsidiaries in excess of $250,000,000"
    },
    {
      "name": "holiday_acquisition_is_permitted_acquisition",
      "meaning": "True iff the acquisition relevant to this observation is a Permitted Acquisition.",
      "source_quote": "solely in connection with any Permitted Acquisition"
    },
    {
      "name": "holiday_use_count",
      "meaning": "Number of Secured Leverage Holidays elected between the Closing Date and the Maturity Date, counting the one relevant to this observation. Supply 0 if no holiday is relevant.",
      "source_quote": "up to two times during the period commencing on the Closing Date and ending on the Maturity Date"
    },
    {
      "name": "test_period_in_holiday_350_stage",
      "meaning": "True iff the observed Test Period is the current period for testing the Relevant Acquisition, or one of the next two Test Periods following its closing date.",
      "source_quote": "3.50 to 1.00 for the next two Test Periods following the closing date of such Material Acquisition"
    },
    {
      "name": "test_period_in_holiday_325_stage",
      "meaning": "True iff the observed Test Period is one of the next two succeeding Test Periods after the 3.50 stage of the Relevant Acquisition.",
      "source_quote": "stepping down to 3.25 to 1.00 for the next two succeeding Test Periods"
    }
  ],
