livered_within_90_days Bool)\n  (annual_officer_certificate_delivered_simultaneously Bool)\n  (accountants_statement_delivered_simultaneously Bool)\n  (is_end_of_first_three_fiscal_quarters Bool)\n  (days_since_quarter_end Real)\n  (quarterly_statements_delivered_within_45_days Bool)\n  (quarterly_officer_certificate_delivered_simultaneously Bool)\n  (officer_knows_default_and_default_continuing Bool)\n  (days_since_officer_knowledge_of_default Real)\n  (default_certificate_delivered_within_5_days Bool)) Bool\n  (and\n    (=> (> days_since_fiscal_year_end 90)\n        (and annual_statements_delivered_within_90_days\n             annual_officer_certificate_delivered_simultaneously\n             accountants_statement_delivered_simultaneously))\n    (=> (and is_end_of_first_three_fiscal_quarters (> days_since_quarter_end 45))\n        (and quarterly_statements_delivered_within_45_days\n             quarterly_officer_certificate_delivered_simultaneously))\n    (=> (and officer_knows_default_and_default_continuing\n             (> days_since_officer_knowledge_of_default 5))\n        default_certificate_delivered_within_5_days)))",
