{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n; total_debt: Total Debt of the Company on the observation date, in the same currency units as the other inputs.\n; securitization_financing: Securitization Financing on the observation date, in the same currency units.\n; consolidated_ebitda: Consolidated EBITDA for the four fiscal quarters most recently ended on or prior to the observation date.\n; is_prior_to_dec_31_2006: true iff the observation date is at any time prior to December 31, 2006. False means the date is on or after December 31, 2006.\n(define-fun covenant_holds ((total_debt Real) (securitization_financing Real) (consolidated_ebitda Real) (is_prior_to_dec_31_2006 Bool)) Bool\n  (<= (/ (+ total_debt securitization_financing) consolidated_ebitda)\n      (ite is_prior_to_dec_31_2006 3.25 3.0)))",
  "symbols": [
    {
      "name": "total_debt",
      "meaning": "Total Debt of the Company on the observation date, in the same currency units as the other financial inputs.",
      "source_quote": "the sum of Total Debt plus Securitization Financing, in each case on such date"
    },
    {
      "name": "securitization_financing",
      "meaning": "Securitization Financing on the observation date, in the same currency units as the other financial inputs.",
      "source_quote": "the sum of Total Debt plus Securitization Financing, in each case on such date"
    },
    {
      "name": "consolidated_ebitda",
      "meaning": "Consolidated EBITDA for the four fiscal quarters most recently ended on or prior to the observation date.",
      "source_quote": "Consolidated EBITDA for the four fiscal quarters most recently ended on or prior to such date"
    },
    {
      "name": "is_prior_to_dec_31_2006",
      "meaning": "True iff the observation date is prior to December 31, 2006, so the 3.25:1 maximum applies. False means the date is on or after December 31, 2006, so the 3.0:1 maximum applies.",
      "source_quote": "at any time prior to December 31, 2006"
    }
  ],
  "notes": "The covenant requires (Total Debt + Securitization Financing) / Consolidated EBITDA to be not greater than the applicable maximum. The maximum is 3.25 before December 31, 2006 and 3.0 on or after that date. The boundary is non-strict because the ratio may not be 'greater than' the threshold. The two time periods are complementary, so one Boolean flag selects the threshold via ite. The ratio keeps its stated arithmetic definition, and division by zero is left to the evaluator to report as unresolved. QF_NRA is used because the division is by a variable. The elided text ('* * *') is not covered."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_LRA)\n; commitments_in_effect: true iff the Commitments remain in effect at the observation time.\n; loan_or_amount_owing: true iff any Loan or other amount is owing to any Lender or the Administrative Agent hereunder at the observation time.\n; is_fiscal_quarter_end_on_or_after_2003_03_29: true iff the observation is the end of a fiscal quarter of the Borrower that ends on or after the fiscal quarter ending on March 29, 2003.\n; consolidated_interest_coverage_ratio: Consolidated Interest Coverage Ratio of the Borrower for the four consecutive fiscal quarters ending on the observed fiscal quarter, as a ratio X:1.00 expressed as the number X.\n; consolidated_total_debt_to_total_capitalization_ratio: Consolidated Total Debt to Consolidated Total Capitalization Ratio at the end of the observed fiscal quarter, as a ratio X:1.00 expressed as the number X.\n(define-fun covenant_holds ((commitments_in_effect Bool) (loan_or_amount_owing Bool) (is_fiscal_quarter_end_on_or_after_2003_03_29 Bool) (consolidated_interest_coverage_ratio Real) (consolidated_total_debt_to_total_capitalization_ratio Real)) Bool\n  (=> (and (or commitments_in_effect loan_or_amount_owing)\n           is_fiscal_quarter_end_on_or_after_2003_03_29)\n      (and (not (< consolidated_interest_coverage_ratio 3.75))\n           (not (> consolidated_total_debt_to_total_capitalization_ratio 0.5)))))",
  "symbols": [
    {
      "name": "commitments_in_effect",
      "meaning": "True iff the Commitments remain in effect at the observation time.",
      "source_quote": "so long as the Commitments remain in effect or any Loan or other amount is owing to any Lender or the Administrative Agent hereunder"
    },
    {
      "name": "loan_or_amount_owing",
      "meaning": "True iff any Loan or other amount is owing to any Lender or the Administrative Agent hereunder at the observation time.",
      "source_quote": "so long as the Commitments remain in effect or any Loan or other amount is owing to any Lender or the Administrative Agent hereunder"
    },
    {
      "name": "is_fiscal_quarter_end_on_or_after_2003_03_29",
      "meaning": "True iff the observation is the end of a fiscal quarter of the Borrower that ends on or after the fiscal quarter ending on March 29, 2003.",
      "source_quote": "ending on or after the fiscal quarter ending on March 29, 2003"
    },
    {
      "name": "consolidated_interest_coverage_ratio",
      "meaning": "Consolidated Interest Coverage Ratio for the four consecutive fiscal quarters ending on the observed fiscal quarter, as the number X in X:1.00. The ratio is atomic because its definition is not supplied.",
      "source_quote": "Consolidated Interest Coverage Ratio for any period of four consecutive fiscal quarters"
    },
    {
      "name": "consolidated_total_debt_to_total_capitalization_ratio",
      "meaning": "Consolidated Total Debt to Consolidated Total Capitalization Ratio at the end of the observed fiscal quarter, as the number X in X:1.00. The ratio is atomic because its definition is not supplied.",
      "source_quote": "Consolidated Total Debt to Consolidated Total Capitalization Ratio at the end of any fiscal quarter"
    }
  ],
  "notes": "Both tests apply at fiscal quarter ends on or after the March 29, 2003 quarter, while the Commitments are in effect or amounts are owing (OR). The covenant forbids permitting an interest coverage ratio below 3.75:1.00, so compliance requires a ratio of at least 3.75. It also forbids a debt-to-capitalization ratio above 0.50:1.00, so compliance requires a ratio of at most 0.50. The two ratios are atomic inputs because their definitions are not supplied. The covenant also binds the Borrower's Subsidiaries, but the tests are on consolidated ratios, so no extra input is needed."
