{
  "status": "formalized",
  "smt2": "(set-logic QF_LRA)\n; obligations_outstanding: True when any Loan or other Obligation remains unpaid or unsatisfied, excluding (x) contingent indemnification obligations as to which no claim has been asserted and (y) obligations and liabilities under Secured Cash Management Agreements and Secured Hedge Agreements not yet due and payable.\n; is_fiscal_quarter_end: True when the observation date is the end of a fiscal quarter of the Borrower.\n; quarter_ends_prior_to_2015_01_31: True when the fiscal quarter ends prior to January 31, 2015. False means it ends on or after January 31, 2015. Only used when is_fiscal_quarter_end is true.\n; consolidated_leverage_ratio: Consolidated Leverage Ratio as of the end of the fiscal quarter, as a plain ratio (3.50 to 1.00 is 3.5).\n; consolidated_interest_coverage_ratio: Consolidated Interest Coverage Ratio as of the end of the fiscal quarter, as a plain ratio (3.00 to 1.00 is 3.0).\n(define-fun covenant_holds ((obligations_outstanding Bool) (is_fiscal_quarter_end Bool) (quarter_ends_prior_to_2015_01_31 Bool) (consolidated_leverage_ratio Real) (consolidated_interest_coverage_ratio Real)) Bool\n  (=> (and obligations_outstanding is_fiscal_quarter_end)\n      (and (ite quarter_ends_prior_to_2015_01_31\n                (<= consolidated_leverage_ratio 3.5)\n                (<= consolidated_leverage_ratio 3.0))\n           (>= consolidated_interest_coverage_ratio 3.0))))",
  "symbols": [
    {
      "name": "obligations_outstanding",
      "meaning": "True when any Loan or other Obligation remains unpaid or unsatisfied, excluding contingent indemnification obligations with no asserted claim and obligations under Secured Cash Management Agreements and Secured Hedge Agreements not yet due and payable.",
      "source_quote": "So long as any Loan or other Obligation hereunder shall remain unpaid or unsatisfied (other than (x) contingent indemnification obligations as to which no claim has been asserted and (y) obligations and liabilities under Secured Cash Management Agreements and Secured Hedge Agreements not yet due and payable)"
    },
    {
      "name": "is_fiscal_quarter_end",
      "meaning": "True when the observation date is the end of a fiscal quarter of the Borrower.",
      "source_quote": "as of the end of any fiscal quarter of the Borrower"
    },
    {
      "name": "quarter_ends_prior_to_2015_01_31",
      "meaning": "True when the fiscal quarter ends prior to January 31, 2015. False means it ends on or after January 31, 2015.",
      "source_quote": "(i) ending prior to January 31, 2015 to be greater than 3.50 to 1.00 and (ii) ending on or after January 31, 2015 to be greater than 3.00 to 1.00"
    },
    {
      "name": "consolidated_leverage_ratio",
      "meaning": "Consolidated Leverage Ratio as of the end of the fiscal quarter, as a plain ratio (3.50 to 1.00 is 3.5).",
      "source_quote": "Permit the Consolidated Leverage Ratio as of the end of any fiscal quarter of the Borrower"
    },
    {
