{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n; is_fiscal_quarter_end: true iff the observation date is the last day of a Fiscal Quarter.\n; funded_debt: Funded Debt of the Borrower as of the last day of the twelve month period ending on the observation date.\n; rent_expense: Rent Expense of the Borrower for the twelve month period ending on the observation date.\n; ebitdar: EBITDAR of the Borrower for the twelve month period ending on the observation date.\n(define-fun covenant_holds ((is_fiscal_quarter_end Bool) (funded_debt Real) (rent_expense Real) (ebitdar Real)) Bool\n  (=> is_fiscal_quarter_end\n      (<= (/ (+ funded_debt (* rent_expense 6.0)) ebitdar) 4.0)))",
  "symbols": [
    {
      "name": "is_fiscal_quarter_end",
      "meaning": "True iff the observation date is the last day of a Fiscal Quarter, so the twelve month period ending on that date is tested.",
      "source_quote": "As of the last day of each Fiscal Quarter"
    },
    {
      "name": "funded_debt",
      "meaning": "Funded Debt of the Borrower as of the last day of the twelve month period ending on the observation date.",
      "source_quote": "Funded Debt as of the last day of such period"
    },
    {
      "name": "rent_expense",
      "meaning": "Rent Expense of the Borrower for the twelve month period ending on the observation date. The formula multiplies it by six.",
      "source_quote": "Rent Expense for such period times (2) six"
    },
    {
      "name": "ebitdar",
      "meaning": "EBITDAR of the Borrower for the twelve month period ending on the observation date. It is the denominator of the Leverage Ratio.",
      "source_quote": "EBITDAR for such period"
    }
  ],
  "notes": "The Leverage Ratio is (Funded Debt + 6 * Rent Expense) / EBITDAR, and the covenant forbids it from being greater than 4.0, so the test is <= 4.0. The check applies only on the last day of a Fiscal Quarter. Division by a variable makes the formula nonlinear, so the logic is QF_NRA. No sign assumption on EBITDAR is made, because multiplying through by it would require one. A zero EBITDAR is left to the evaluator to report as unresolved."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n; advance_unpaid: true iff at this observation time any Advance remains unpaid.\n; commitment_outstanding: true iff at this observation time any Lender has any Commitment under the agreement.\n; consolidated_debt: Consolidated Debt of the Borrower at this observation time, in currency units.\n; shareholders_equity: the Borrower's shareholders' equity at this observation time, in the same currency units.\n(define-fun covenant_holds ((advance_unpaid Bool) (commitment_outstanding Bool) (consolidated_debt Real) (shareholders_equity Real)) Bool\n  (=> (or advance_unpaid commitment_outstanding)\n      (<= (/ consolidated_debt (+ consolidated_debt shareholders_equity)) 0.6)))",
  "symbols": [
    {
      "name": "advance_unpaid",
      "meaning": "True iff at this observation time any Advance remains unpaid.",
      "source_quote": "any Advance shall remain unpaid"
    },
    {
      "name": "commitment_outstanding",
      "meaning": "True iff at this observation time any Lender has any Commitment under the agreement.",
      "source_quote": "any Lender shall have any Commitment hereunder"
    },
    {
      "name": "consolidated_debt",
      "meaning": "Consolidated Debt of the Borrower at this observation time, in currency units.",
      "source_quote": "Consolidated Debt to the sum of Consolidated Debt plus shareholders' equity"
    },
    {
      "name": "shareholders_equity",
      "meaning": "The Borrower's shareholders' equity at this observation time, in the same currency units as consolidated_debt.",
      "source_quote": "Consolidated Debt plus shareholders' equity"
    }
  ],
  "notes": "The covenant applies while any Advance is unpaid OR any Commitment remains, so the two applicability flags are joined with or. The requirement is Consolidated Debt / (Consolidated Debt + shareholders' equity) <= 0.60, where 'not greater than' makes the bound non-strict. The ratio is written with a division by a non-constant, so the logic is QF_NRA. A zero denominator is left to the evaluator to report as unresolved. No positivity assumptions are made, and the ratio is not cross-multiplied, because that would change the behavior for a zero or negative denominator. The pointwise temporal convention covers 'so long as'. The 'Consolidated Debt' definition is not supplied, so the debt figure is an atomic input."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n; term_obligation_outstanding: true iff, at this observation time, any Term Loan or Term Note is outstanding.\n; consolidated_funded_debt: Consolidated Funded Debt of the Loan Parties at this observation time (numerator of the ratio, in currency units).\n; consolidated_tangible_net_worth: Consolidated Tangible Net Worth at this observation time (denominator of the ratio, in the same currency units).\n(define-fun covenant_holds ((term_obligation_outstanding Bool) (consolidated_funded_debt Real) (consolidated_tangible_net_worth Real)) Bool\n  (=> term_obligation_outstanding\n      (<= (/ consolidated_funded_debt consolidated_tangible_net_worth) 3.5)))",
  "symbols": [
    {
      "name": "term_obligation_outstanding",
      "meaning": "True iff, at this observation time, any Term Loan or Term Note is outstanding, so the covenant applies.",
      "source_quote": "so long as any Term Loan or Term Note is outstanding"
    },
