  "smt2": "(set-logic QF_LRA)\n; is_test_period: true iff the observation is a period of four consecutive fiscal quarters of Holdings (for the leverage test, measured as at its last day) within the covenant's coverage, i.e. beginning March 31, 2009 or later.\n; period_ends_on_or_prior_2010_12_31: true iff the four-fiscal-quarter period ending at this observation ends on or prior to December 31, 2010; false if it ends after December 31, 2010.\n; consolidated_leverage_ratio: Consolidated Leverage Ratio of Holdings as at the last day of the four-fiscal-quarter period, expressed as a number X meaning X to 1.00.\n; consolidated_interest_coverage_ratio: Consolidated Interest Coverage Ratio for the four-fiscal-quarter period, expressed as a number X meaning X to 1.00.\n; consolidated_fixed_charge_coverage_ratio: Consolidated Fixed Charge Coverage Ratio for the four-fiscal-quarter period, expressed as a number X meaning X to 1.00.\n(define-fun covenant_holds ((is_test_period Bool) (period_ends_on_or_prior_2010_12_31 Bool) (consolidated_leverage_ratio Real) (consolidated_interest_coverage_ratio Real) (consolidated_fixed_charge_coverage_ratio Real)) Bool\n  (and\n    ;; 8.1(a): leverage must not exceed 3.00 to 1.00\n    (=> is_test_period (<= consolidated_leverage_ratio 3.0))\n    ;; 8.1(b): interest coverage must not be less than 3.00 to 1.00\n    (=> is_test_period (>= consolidated_interest_coverage_ratio 3.0))\n    ;; 8.1(c): fixed charge coverage must not be less than 1.00 (ending on or before 2010-12-31) or 1.05 (ending after)\n    (=> is_test_period\n        (ite period_ends_on_or_prior_2010_12_31\n             (>= consolidated_fixed_charge_coverage_ratio 1.0)\n             (>= consolidated_fixed_charge_coverage_ratio 1.05)))))",
  "symbols": [
    {
      "name": "is_test_period",
      "meaning": "True iff the observation is a period of four consecutive fiscal quarters of Holdings beginning March 31, 2009 or later (for the leverage test, measured as at its last day).",
      "source_quote": "any period of four consecutive fiscal quarters of Holdings beginning March 31, 2009"
    },
    {
      "name": "period_ends_on_or_prior_2010_12_31",
      "meaning": "True iff the four-fiscal-quarter period ends on or prior to December 31, 2010; false if it ends after December 31, 2010.",
      "source_quote": "for any such period ending on or prior to December 31, 2010"
    },
    {
      "name": "consolidated_leverage_ratio",
      "meaning": "Consolidated Leverage Ratio as at the last day of the four-fiscal-quarter period, as a number X meaning X to 1.00.",
      "source_quote": "Consolidated Leverage Ratio"
    },
    {
      "name": "consolidated_interest_coverage_ratio",
      "meaning": "Consolidated Interest Coverage Ratio for the four-fiscal-quarter period, as a number X meaning X to 1.00.",
      "source_quote": "Consolidated Interest Coverage Ratio"
    },
    {
      "name": "consolidated_fixed_charge_coverage_ratio",
      "meaning": "Consolidated Fixed Charge Coverage Ratio for the four-fiscal-quarter period, as a number X meaning X to 1.00.",
      "source_quote": "Consolidated Fixed Charge Coverage Ratio"
    }
  ],
  "notes": "The three ratios are atomic Real inputs because their definitions are not supplied. The leverage test is 'shall not exceed 3.00', so it uses <=. The interest coverage test is 'shall not be less than 3.00', so it uses >=. The fixed charge test uses a threshold of 1.00 for periods ending on or before 2010-12-31 and 1.05 for periods ending after. A single applicability flag covers all three tests because they share the same period description. The surrounding 'so long as the Commitments remain in effect' clause is not modelled as a separate input."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n; is_covenant_quarter_end: true iff the observation date is the last day of a fiscal quarter, i.e. January 31, April 30, July 31 or October 31.\n; is_on_or_after_2003_07_31: true iff the observation date is on or after July 31, 2003.\n; is_addback_quarter: true iff the fiscal quarter ends on July 31, 2003, October 31, 2003, January 31, 2004 or April 30, 2004.\n; ebitdar_ttm: EBITDAR (USD) for the most recently ended four fiscal quarters, before any prepayment-fee addback.\n; prepayment_fees_paid: prepayment fees and deferred charges (USD) paid on the Existing Indebtedness, available for the addback.\n; fixed_charges_ttm: Fixed Charges (USD) for the most recently ended four fiscal quarters.\n(define-fun covenant_holds ((is_covenant_quarter_end Bool) (is_on_or_after_2003_07_31 Bool) (is_addback_quarter Bool) (ebitdar_ttm Real) (prepayment_fees_paid Real) (fixed_charges_ttm Real)) Bool\n  (=> (and is_covenant_quarter_end is_on_or_after_2003_07_31)\n      (>= (/ (+ ebitdar_ttm\n                (ite is_addback_quarter\n                     (ite (<= prepayment_fees_paid 1000000.0) prepayment_fees_paid 1000000.0)\n                     0.0))\n             fixed_charges_ttm)\n          2.0)))",
  "symbols": [
    {
      "name": "is_covenant_quarter_end",
      "meaning": "True iff the observation date is the last day of a fiscal quarter, i.e. January 31, April 30, July 31 or October 31.",
      "source_quote": "calculated as of the last day of each such fiscal quarter"
    },
    {
      "name": "is_on_or_after_2003_07_31",
      "meaning": "True iff the observation date is on or after July 31, 2003, when the covenant tests begin.",
      "source_quote": "beginning with July 31, 2003"
    },
    {
      "name": "is_addback_quarter",
      "meaning": "True iff the fiscal quarter ends on July 31, 2003, October 31, 2003, January 31, 2004 or April 30, 2004, so the prepayment-fee addback is allowed.",
      "source_quote": "for the fiscal quarters ending July 31, 2003, October 31, 2003, January 31, 2004 and April 30, 2004"
    },
    {
      "name": "ebitdar_ttm",
      "meaning": "EBITDAR in USD for the most recently ended four fiscal quarters, before any prepayment-fee addback.",
      "source_quote": "EBITDAR"
    },
    {
      "name": "prepayment_fees_paid",
      "meaning": "Prepayment fees and deferred charges in USD paid on the Existing Indebtedness. The formula caps the addback at $1,000,000 and allows it only in the listed quarters.",
      "source_quote": "up to $1,000,000 in prepayment fees and deferred charges paid on the Existing Indebtedness"
    },
    {
      "name": "fixed_charges_ttm",
      "meaning": "Fixed Charges in USD for the most recently ended four fiscal quarters.",
      "source_quote": "Fixed Charges for the most recent ended four fiscal quarters"
    }
  ],
  "notes": "The covenant applies only at fiscal quarter-end dates on or after July 31, 2003. The numerator is EBITDAR plus min(prepayment_fees_paid, 1,000,000) in the four listed quarters, and plus 0 otherwise. The ratio is computed by division and must be at least 2.00:1.00, so the comparison is non-strict. A zero Fixed Charges value is left to the evaluator to report as unresolved. QF_NRA is used because the divisor is a variable. The 'up to $1,000,000' cap is read as a cap on the addback amount."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_LRA)\n; covenant_in_effect: True when the observation time is on or after the Effective Date and the Section 8 covenant period is still running. That means the Agreement is in effect, and it is not yet true that the Total Commitment has been terminated, no Notes remain outstanding, and the Loans, interest, Fees and all other Obligations are paid in full.\n; interest_coverage_ratio: The Borrower's Interest Coverage Ratio for the Test Period being tested at this observation, as a ratio X in X:1. It is supplied atomically because no formula is given.\n; before_first_anniversary: True when the observation time is prior to the first anniversary of the Initial Borrowing Date. False when it is on or after that anniversary (the 'thereafter' case).\n(define-fun covenant_holds ((covenant_in_effect Bool) (interest_coverage_ratio Real) (before_first_anniversary Bool)) Bool\n  (=> covenant_in_effect\n      (ite before_first_anniversary\n           (>= interest_coverage_ratio 2.25)\n           (>= interest_coverage_ratio 2.5))))",
  "symbols": [
    {
      "name": "covenant_in_effect",
      "meaning": "True when the observation time is on or after the Effective Date and the covenant period is still running. The Agreement is in effect, and it is not yet true that the Total Commitment has been terminated, no Notes remain outstanding, and the Loans, interest, Fees and all other Obligations are paid in full.",
      "source_quote": "for so long as this Agreement is in effect and until such time as the Total Commitment has been terminated, no Notes remain outstanding and the Loans, together with interest, Fees and all other Obligations incurred hereunder are paid in full"
    },
    {
      "name": "interest_coverage_ratio",
      "meaning": "The Borrower's Interest Coverage Ratio for the Test Period being tested at this observation, expressed as X in X:1. It is an atomic input because no arithmetic definition is supplied.",
      "source_quote": "Interest Coverage Ratio"
    },
    {
      "name": "before_first_anniversary",
      "meaning": "True when the observation time is prior to the first anniversary of the Initial Borrowing Date, so the 2.25:1 minimum applies. False when it is on or after that anniversary, so the 2.5:1 minimum applies.",
      "source_quote": "at any time prior to the first anniversary of the Initial Borrowing Date"
    }
  ],
  "notes": "The covenant forbids an Interest Coverage Ratio less than the threshold, so compliance is ratio >= threshold (non-strict). The threshold is 2.25 before the first anniversary of the Initial Borrowing Date and 2.5 thereafter. The two periods are complementary, so one Boolean selects between them with ite. The covenant period is a separate Boolean guard, so the formula is vacuously true outside it. The ratio is an atomic input, so no division is performed in the formula. If the Initial Borrowing Date has not yet occurred, the evaluator must choose the before_first_anniversary value; the source does not say."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_LRA)\n; fccr: Consolidated Fixed Charge Coverage Ratio calculated on the last day of the fiscal quarter being observed, as a plain ratio (for example 1.25 means 1.25:1.0).\n; is_sep_30_1997_quarter_end: true iff the observation is the last day of the fiscal quarter ending September 30, 1997.\n; is_dec_31_1997_quarter_end: true iff the observation is the last day of the fiscal quarter ending December 31, 1997.\n; is_mar_31_1998_or_later_quarter_end: true iff the observation is the last day of the fiscal quarter ending March 31, 1998 or of any fiscal quarter ending thereafter.\n(define-fun covenant_holds ((fccr Real) (is_sep_30_1997_quarter_end Bool) (is_dec_31_1997_quarter_end Bool) (is_mar_31_1998_or_later_quarter_end Bool)) Bool\n  (and\n    (=> is_sep_30_1997_quarter_end (>= fccr 0.80))\n    (=> is_dec_31_1997_quarter_end (>= fccr 1.10))\n    (=> is_mar_31_1998_or_later_quarter_end (>= fccr 1.25))))",
  "symbols": [
    {
      "name": "fccr",
      "meaning": "Consolidated Fixed Charge Coverage Ratio calculated on the last day of the fiscal quarter being observed, expressed as a plain ratio (1.25 means 1.25:1.0). Its internal definition is not supplied, so it is an atomic input.",
      "source_quote": "Maintain a Consolidated Fixed Charge Coverage Ratio, calculated on the last day of each fiscal quarter"
    },
    {
      "name": "is_sep_30_1997_quarter_end",
      "meaning": "True iff the observation is the last day of the fiscal quarter ending September 30, 1997, where the required minimum ratio is 0.80:1.0.",
      "source_quote": "September 30, 1997 0.80:1.0"
    },
    {
      "name": "is_dec_31_1997_quarter_end",
      "meaning": "True iff the observation is the last day of the fiscal quarter ending December 31, 1997, where the required minimum ratio is 1.10:1.0.",
      "source_quote": "December 31, 1997 1.10:1.0"
    },
    {
      "name": "is_mar_31_1998_or_later_quarter_end",
      "meaning": "True iff the observation is the last day of the fiscal quarter ending March 31, 1998 or of any fiscal quarter ending thereafter, where the required minimum ratio is 1.25:1.0.",
      "source_quote": "March 31, 1998 and each fiscal quarter end occurring thereafter 1.25:1.0"
    }
  ],
  "notes": "'Not less than' is encoded as >=. Each date flag gates its own threshold, so the covenant does not apply at observations where all three flags are false. The flags are mutually exclusive by calendar and are supplied by the evaluator. The introductory conditions (Obligations unpaid or Commitment outstanding, absent Required Lenders' consent) are not encoded as inputs. The pointwise convention treats the covenant as in force at each supplied observation."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_LRA)\n; leverage_ratio: Leverage Ratio of Parent as of the observation date (to 1.00), as defined in the credit agreement.\n; is_fiscal_quarter_end: true iff the observation date is the last day of a fiscal quarter of Parent.\n; qualifying_acquisition_consummated: true iff a Material Acquisition involving cash consideration of at least US$100,000,000 has been consummated, and the observation date falls in the relevant election window of that acquisition.\n; written_election_made: true iff Parent gave the written election to the Administrative Agent for that Material Acquisition.\n; prior_election_made: true iff Parent had previously made such an election for an earlier Material Acquisition.\n; two_quarters_no_increase_since_prior: true iff at least two consecutive full fiscal quarters have ended since the prior election date with no increase in effect.\n; two_quarters_ratio_within_350_since_prior: true iff the Leverage Ratio on the last day of at least two consecutive full fiscal quarters ended since the prior election date did not exceed 3.50 to 1.00.\n; in_4_00_window: true iff the observation date is the last day of the fiscal quarter in which the Material Acquisition was consummated, or of the first or second full fiscal quarter ending after its consummation.\n; in_3_75_window: true iff the observation date is the last day of the third or fourth full fiscal quarter ending after the Material Acquisition's consummation.\n(define-fun covenant_holds ((leverage_ratio Real)\n                            (is_fiscal_quarter_end Bool)\n                            (qualifying_acquisition_consummated Bool)\n                            (written_election_made Bool)\n                            (prior_election_made Bool)\n                            (two_quarters_no_increase_since_prior Bool)\n                            (two_quarters_ratio_within_350_since_prior Bool)\n                            (in_4_00_window Bool)\n                            (in_3_75_window Bool)) Bool\n  (let ((election_effective\n         (and qualifying_acquisition_consummated\n              written_election_made\n              (or (not prior_election_made)\n                  two_quarters_no_increase_since_prior\n                  two_quarters_ratio_within_350_since_prior))))\n    (=> is_fiscal_quarter_end\n        (<= leverage_ratio\n            (ite (and election_effective in_4_00_window) 4.00\n                 (ite (and election_effective in_3_75_window) 3.75\n                      3.50))))))",
  "symbols": [
    {
      "name": "leverage_ratio",
      "meaning": "Parent's Leverage Ratio as of the observation date, expressed as X in X to 1.00.",
      "source_quote": "the Leverage Ratio as of the last day of any fiscal quarter to exceed 3.50 to 1.00"
    },
    {
      "name": "is_fiscal_quarter_end",
      "meaning": "True iff the observation date is the last day of a fiscal quarter of Parent.",
      "source_quote": "the Leverage Ratio as of the last day of any fiscal quarter to exceed 3.50 to 1.00"
    },
    {
      "name": "qualifying_acquisition_consummated",
      "meaning": "True iff a Material Acquisition involving cash consideration of at least US$100,000,000 has been consummated, to which the observation's election window refers.",
      "source_quote": "any Material Acquisition that involves payment of cash consideration of at least US$100,000,000"
    },
    {
      "name": "written_election_made",
      "meaning": "True iff Parent made the written election to the Administrative Agent for that Material Acquisition.",
      "source_quote": "the written election of Parent to the Administrative Agent"
    },
    {
      "name": "prior_election_made",
      "meaning": "True iff Parent had previously made such an election for an earlier Material Acquisition.",
      "source_quote": "if Parent has theretofore made such an election"
    },
    {
      "name": "two_quarters_no_increase_since_prior",
      "meaning": "True iff at least two consecutive full fiscal quarters of Parent have ended since the prior election date without an increase in effect.",
      "source_quote": "at least two consecutive full fiscal quarters of Parent shall have ended since the date of such prior election without an increase being in effect"
    },
    {
      "name": "two_quarters_ratio_within_350_since_prior",
      "meaning": "True iff the Leverage Ratio on the last day of at least two consecutive full fiscal quarters ended since the prior election date did not exceed 3.50 to 1.00.",
      "source_quote": "the Leverage Ratio as of the last day of at least two consecutive full fiscal quarters ended since the date of such prior election did not exceed 3.50 to 1.00"
    },
    {
      "name": "in_4_00_window",
      "meaning": "True iff the observation date is the last day of the fiscal quarter in which the Material Acquisition was consummated, or of the first or second full fiscal quarter ending after its consummation.",
      "source_quote": "the last day of the fiscal quarter of Parent during which such Material Acquisition is consummated and the last day of the first and second full fiscal quarters of Parent ending after the date of the consummation of such Material Acquisition"
    },
    {
      "name": "in_3_75_window",
      "meaning": "True iff the observation date is the last day of the third or fourth full fiscal quarter ending after the Material Acquisition's consummation.",
      "source_quote": "the last day of the third and fourth full fiscal quarters of Parent ending after the date of the consummation of such Material Acquisition"
    }
  ],
  "notes": "Pointwise at each observation: only fiscal quarter-ends are tested. The maximum is 3.50 by default, 4.00 in the 4.00 window, and 3.75 in the 3.75 window, but only if an effective election exists. An election is effective only if the acquisition qualifies, a written election was made, and either no prior election exists or one of the two re-election conditions (i)/(ii) holds. The 4.00 window takes precedence if both window flags are true. The bound is non-strict (<=) because the covenant forbids exceeding the maximum. No division is involved."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n; is_fiscal_year_end: true iff the observation date is the end of a fiscal year of the Company.\n; net_income_after_taxes: Consolidated net income of the Company after taxes for the fiscal year ending at the observation date.\n; depreciation_and_amortization: Consolidated depreciation and amortization of the Company for the same fiscal year.\n; current_maturities_long_term_debt: Consolidated current maturities of the Company's long term Indebtedness as of the observation date (the denominator).\n(define-fun covenant_holds ((is_fiscal_year_end Bool) (net_income_after_taxes Real) (depreciation_and_amortization Real) (current_maturities_long_term_debt Real)) Bool\n  (=> is_fiscal_year_end\n      (>= (/ (+ net_income_after_taxes depreciation_and_amortization) current_maturities_long_term_debt) 1.5)))",
  "symbols": [
    {
      "name": "is_fiscal_year_end",
      "meaning": "True iff the observation date is the end of a fiscal year of the Company.",
      "source_quote": "as of the end of any fiscal year of the Company"
    },
    {
      "name": "net_income_after_taxes",
      "meaning": "Consolidated net income of the Company after taxes for the fiscal year ending at the observation date (numerator component (a)).",
      "source_quote": "net income of the Company after taxes"
    },
    {
      "name": "depreciation_and_amortization",
      "meaning": "Consolidated depreciation and amortization of the Company for the same fiscal year, added to net income after taxes (numerator component (a)).",
      "source_quote": "depreciation and amortization"
    },
    {
      "name": "current_maturities_long_term_debt",
      "meaning": "Consolidated current maturities of the Company's long term Indebtedness as of the observation date (denominator (b)).",
      "source_quote": "current maturities of the Company's long term Indebtedness"
    }
  ],
  "notes": "The covenant prohibits permitting the ratio to be less than 1.5 to 1.0 at fiscal year end, so compliance means ratio >= 1.5 when is_fiscal_year_end is true. Otherwise the covenant is vacuously satisfied at that observation. The ratio is (net income after taxes + D&A) / current maturities, kept as a division so that a zero denominator is reported as unresolved by the evaluator, with no positivity assumption. QF_NRA is used because the division has a variable denominator. The 'Consolidated basis' requirement is reflected in the input meanings. The prior written consent of the Bank exception is not modeled, since no consent input is needed for the numerical test."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n; is_last_day_of_fiscal_quarter: true iff the observation date is the last day of a fiscal quarter of the Company.\n; company_non_performing_assets: Non-Performing Assets of the Company on a consolidated basis with its Subsidiaries, as of the observation date.\n; company_shareholders_equity: shareholders' equity of the Company on a consolidated basis, as of the observation date.\n; company_loan_loss_reserves: loan loss reserves established by the Company on a consolidated basis under the applicable regulatory accounting principles, as of the observation date.\n; has_banking_subsidiary_observation: true iff this observation also carries the figures of one Banking Subsidiary (consolidated with its subsidiaries) to be tested; the evaluator supplies one observation per Banking Subsidiary.\n; bank_non_performing_assets: Non-Performing Assets of that Banking Subsidiary on a consolidated basis with its subsidiaries, as of the observation date.\n; bank_core_capital: core capital of that Banking Subsidiary, as of the observation date.\n; bank_loan_loss_reserves: loan loss reserves established by that Banking Subsidiary on a consolidated basis under the applicable regulatory accounting principles, as of the observation date.\n(define-fun covenant_holds (\n  (is_last_day_of_fiscal_quarter Bool)\n  (company_non_performing_assets Real)\n  (company_shareholders_equity Real)\n  (company_loan_loss_reserves Real)\n  (has_banking_subsidiary_observation Bool)\n  (bank_non_performing_assets Real)\n  (bank_core_capital Real)\n  (bank_loan_loss_reserves Real)) Bool\n  (=> is_last_day_of_fiscal_quarter\n      (and\n        (<= (/ company_non_performing_assets (+ company_shareholders_equity company_loan_loss_reserves)) 0.25)\n        (=> has_banking_subsidiary_observation\n            (<= (/ bank_non_performing_assets (+ bank_core_capital bank_loan_loss_reserves)) 0.25)))))",
  "symbols": [
    {
      "name": "is_last_day_of_fiscal_quarter",
      "meaning": "True iff the observation date is the last day of a fiscal quarter, the date as of which the ratio must be maintained.",
      "source_quote": "as of the last day of each fiscal quarter"
    },
    {
      "name": "company_non_performing_assets",
      "meaning": "Non-Performing Assets of the Company on a consolidated basis with its Subsidiaries, as of the observation date.",
      "source_quote": "Non-Performing Assets of the Company or such Banking Subsidiary on a consolidated basis"
    },
    {
      "name": "company_shareholders_equity",
      "meaning": "Shareholders' equity of the Company on a consolidated basis, as of the observation date.",
      "source_quote": "shareholders' equity for the Company"
    },
    {
      "name": "company_loan_loss_reserves",
      "meaning": "Loan loss reserves established by the Company on a consolidated basis in accordance with applicable regulatory accounting principles, as of the observation date.",
      "source_quote": "loan loss reserves established by the Company or such Banking Subsidiary"
    },
    {
      "name": "has_banking_subsidiary_observation",
      "meaning": "True iff this observation carries the figures of a Banking Subsidiary to be tested. The evaluator supplies one observation per Banking Subsidiary.",
      "source_quote": "shall cause each Banking Subsidiary to maintain"
    },
    {
      "name": "bank_non_performing_assets",
      "meaning": "Non-Performing Assets of the Banking Subsidiary on a consolidated basis with its subsidiaries, as of the observation date.",
      "source_quote": "Non-Performing Assets of the Company or such Banking Subsidiary on a consolidated basis"
    },
    {
      "name": "bank_core_capital",
      "meaning": "Core capital of the Banking Subsidiary, as of the observation date.",
      "source_quote": "core capital for such Banking Subsidiary"
    },
    {
      "name": "bank_loan_loss_reserves",
      "meaning": "Loan loss reserves established by the Banking Subsidiary on a consolidated basis in accordance with applicable regulatory accounting principles, as of the observation date.",
      "source_quote": "loan loss reserves established by the Company or such Banking Subsidiary"
    }
  ],
  "notes": "The covenant is tested only on the last day of a fiscal quarter. It requires (NPA / (equity-or-core-capital + loan loss reserves)) <= 0.25 (0.25 to 1.0) for the Company, and the same for each Banking Subsidiary. The Banking Subsidiary test is applied only when a Banking Subsidiary observation is supplied. Division is kept literal, so a zero denominator is reported as unresolved by the evaluator, and no positivity assumption is made. QF_NRA is used because the denominator is a variable. The lead-in clause about the period of the covenant and written waivers is not modeled, because no waiver or credit-availability inputs are needed for the ratio test, and the evaluator supplies observations only within that period."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n; is_fiscal_quarter_end: true iff the observation date is the last day of a fiscal quarter of MascoTech\n; in_initial_period: true iff the fiscal quarter ending on the observation date ends during the period from the quarter ending March 31, 1998 through the quarter ending June 30, 2000, inclusive\n; in_later_period: true iff the fiscal quarter ending on the observation date ends after June 30, 2000 and on or before the Termination Date\n; ebitda: MascoTech EBITDA for the four fiscal quarter period ending on the observation date\n; capex_eight_quarters: MascoTech Capital Expenditures during the eight fiscal quarter period ending on the observation date (50 percent is applied in the formula)\n; interest_charges: Interest Charges for the four fiscal quarter period ending on the observation date\n; sched_amort_term_loans: scheduled amortization payments of the principal portion of the Term Loans in the four fiscal quarter period ending on the observation date, excluding the installment due January 31, 2002\n; sched_amort_other_debt: scheduled amortization payments of the principal portion of all other Debt of MascoTech and its Consolidated Subsidiaries with an original maturity in excess of one year, for the four fiscal quarter period ending on the observation date\n; cash_taxes_paid: cash taxes paid by MascoTech and its Consolidated Subsidiaries in the four fiscal quarter period ending on the observation date, excluding cash taxes with respect to gains not included in EBITDA\n(define-fun covenant_holds ((is_fiscal_quarter_end Bool) (in_initial_period Bool) (in_later_period Bool) (ebitda Real) (capex_eight_quarters Real) (interest_charges Real) (sched_amort_term_loans Real) (sched_amort_other_debt Real) (cash_taxes_paid Real)) Bool\n  (and\n    (=> (and is_fiscal_quarter_end in_initial_period)\n        (>= (/ (- ebitda (* 0.5 capex_eight_quarters))\n               (+ interest_charges sched_amort_term_loans sched_amort_other_debt cash_taxes_paid))\n            1.10))\n    (=> (and is_fiscal_quarter_end in_later_period)\n        (>= (/ (- ebitda (* 0.5 capex_eight_quarters))\n               (+ interest_charges sched_amort_term_loans sched_amort_other_debt cash_taxes_paid))\n            1.15))))",
  "symbols": [
    {
      "name": "is_fiscal_quarter_end",
      "meaning": "True iff the observation date is the last day of a fiscal quarter of MascoTech.",
