    {
      "name": "consolidated_ebitda_ltm",
      "meaning": "Consolidated EBITDA of the Borrower for the period of four consecutive Fiscal Quarters ending on the observation date.",
      "source_quote": "Consolidated EBITDA of the Borrower for the period of four consecutive Fiscal Quarters ending on such date"
