}

{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n; is_fiscal_quarter_end: true iff the observation date is the last day of a fiscal quarter of the Parent.\n; total_indebtedness: Total Indebtedness as of the last day of the fiscal quarter of the Parent.\n; consolidated_ebitda_ltm: Consolidated EBITDA for the period of four consecutive fiscal quarters of the Parent then ended.\n; capex_not_financed_with_7_2c_indebtedness: expenditures during the four-quarter period for the purchase or other acquisition of fixed or capital assets that are not made with Indebtedness described in Section 7.2(c).\n; consolidated_interest_expense: Consolidated Interest Expense for the four-quarter period.\n; financing_lease_principal_installments: all principal installments due during the four-quarter period with respect to Financing Leases.\n(define-fun covenant_holds ((is_fiscal_quarter_end Bool)\n                            (total_indebtedness Real)\n                            (consolidated_ebitda_ltm Real)\n                            (capex_not_financed_with_7_2c_indebtedness Real)\n                            (consolidated_interest_expense Real)\n                            (financing_lease_principal_installments Real)) Bool\n  (=> is_fiscal_quarter_end\n      (and\n        ; 7.1(a): Leverage Ratio must not be greater than 3.00 to 1.00\n        (<= (/ total_indebtedness consolidated_ebitda_ltm) 3.0)\n        ; 7.1(b): Fixed Charge Coverage Ratio must not be less than 2.00 to 1.00\n        (>= (/ (- consolidated_ebitda_ltm capex_not_financed_with_7_2c_indebtedness)\n               (+ consolidated_interest_expense financing_lease_principal_installments))\n            2.0))))",
  "symbols": [
    {
      "name": "is_fiscal_quarter_end",
      "meaning": "True iff the observation date is the last day of a fiscal quarter of the Parent.",
      "source_quote": "last day of any fiscal quarter of the Parent"
    },
    {
      "name": "total_indebtedness",
      "meaning": "Total Indebtedness as of the last day of the fiscal quarter of the Parent (numerator of the Leverage Ratio).",
      "source_quote": "Total Indebtedness as of the last day of any fiscal quarter of the Parent"
    },
    {
      "name": "consolidated_ebitda_ltm",
      "meaning": "Consolidated EBITDA for the period of four consecutive fiscal quarters of the Parent then ended. Used in both the Leverage Ratio denominator and the Fixed Charge Coverage Ratio numerator.",
      "source_quote": "Consolidated EBITDA for the period of four consecutive fiscal quarters of the Parent then ended"
    },
    {
      "name": "capex_not_financed_with_7_2c_indebtedness",
      "meaning": "Expenditures during the four-quarter period for the purchase or other acquisition of fixed or capital assets that are not made with Indebtedness described in Section 7.2(c). It is subtracted from Consolidated EBITDA in the Fixed Charge Coverage Ratio numerator.",
      "source_quote": "expenditures during such period in respect of the purchase or other acquisition of fixed or capital assets that are not made with Indebtedness described in Section 7.2(c)"
    },
    {
      "name": "consolidated_interest_expense",
      "meaning": "Consolidated Interest Expense for the four-quarter period. It is part of the Fixed Charge Coverage Ratio denominator.",
      "source_quote": "Consolidated Interest Expense for such period"
    },
    {
      "name": "financing_lease_principal_installments",
      "meaning": "All principal installments due during the four-quarter period with respect to Financing Leases. It is added to Consolidated Interest Expense in the Fixed Charge Coverage Ratio denominator.",
      "source_quote": "all principal installments due during such period with respect to Financing Leases"
    }
  ],
  "notes": "Both tests in Section 7.1 apply only as of the last day of a fiscal quarter, so the body is guarded by is_fiscal_quarter_end. (a) prohibits a Leverage Ratio greater than 3.00, so compliance is ratio <= 3.0. (b) prohibits a Fixed Charge Coverage Ratio less than 2.00, so compliance is ratio >= 2.0. The ratios are kept as real divisions, so a zero denominator is left to the evaluator to report as unresolved. QF_NRA is used because the divisors are variables. The Section 7.2(c) definition is not supplied, so the exclusion is captured by the capex input's meaning. The Parent/Borrower and Subsidiary 'shall not permit' framing and the term of the covenant (while commitments, letters of credit or amounts owing remain outstanding) are not modelled. The evaluator supplies observations in that period."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_LRA)\n; is_listed_quarter_end: Bool, true iff the observation date is the last day of a calendar quarter (Mar 31, Jun 30, Sep 30 or Dec 31) and so can be a date listed in the Section 7.12 tables.\n; obs_year: Real, calendar year of the observation date (for example 1999).\n; obs_month: Real, calendar month number of the observation date (3, 6, 9 or 12 on listed dates).\n; indebtedness_excl_revolving: Real, Indebtedness of the Borrower and its Subsidiaries on the test date, excluding the portion that constitutes Revolving Loans.\n; avg_revolving_in_indebtedness: Real, average amount of Revolving Loans (the portion of Indebtedness) outstanding during the Test Period ending on the test date, with Test Period clause (ii) computed from the Closing Date.\n; senior_indebtedness_excl_revolving: Real, Senior Indebtedness of the Borrower and its Subsidiaries on the test date, excluding the portion that constitutes Revolving Loans.\n; avg_revolving_in_senior: Real, average amount of Revolving Loans (the portion of Senior Indebtedness) outstanding during the Test Period ending on the test date.\n; consolidated_ebitda: Real, Consolidated EBITDA of the Borrower for the Test Period ending on the test date.\n(define-fun covenant_holds ((is_listed_quarter_end Bool) (obs_year Real) (obs_month Real) (indebtedness_excl_revolving Real) (avg_revolving_in_indebtedness Real) (senior_indebtedness_excl_revolving Real) (avg_revolving_in_senior Real) (consolidated_ebitda Real)) Bool\n  (=> (and is_listed_quarter_end (>= obs_year 1998) (<= obs_year 2004))\n      (and\n        ; 7.12(a) Total Leverage Ratio maximum by test date\n        (<= (/ (+ indebtedness_excl_revolving avg_revolving_in_indebtedness) consolidated_ebitda)\n            (ite (= obs_year 1998) 4.25\n            (ite (= obs_year 1999) (ite (<= obs_month 6) 4.25 4.0)\n            (ite (= obs_year 2000) 3.75\n            (ite (= obs_year 2001) 3.5 3.0)))))\n        ; 7.12(b) Senior Leverage Ratio maximum by test date\n        (<= (/ (+ senior_indebtedness_excl_revolving avg_revolving_in_senior) consolidated_ebitda)\n            (ite (= obs_year 1998) 3.5\n            (ite (= obs_year 1999) (ite (= obs_month 12) 3.25 3.5)\n            (ite (= obs_year 2000) (ite (= obs_month 12) 3.0 3.25)\n            (ite (= obs_year 2001) (ite (= obs_month 12) 2.5 3.0) 2.5)))))))\n)",
  "symbols": [
    {
      "name": "is_listed_quarter_end",
      "meaning": "True iff the observation date is the last day of a calendar quarter (Mar 31, Jun 30, Sep 30 or Dec 31) and so can be one of the dates listed in the Section 7.12 tables.",
