    },
    {
      "name": "consolidated_interest_expense_four_quarters",
      "meaning": "Consolidated Interest Expense for the same four fiscal quarters (currency units); denominator of the ratio.",
      "source_quote": "Consolidated Interest Expense for such four fiscal quarters"
    },
    {
      "name": "is_fiscal_quarter_end",
      "meaning": "True iff the observation date is the end of a fiscal quarter.",
      "source_quote": "as of the end of each fiscal quarter"
    },
    {
      "name": "any_advance_unpaid",
      "meaning": "True iff any Advance remains unpaid at the observation time.",
      "source_quote": "any Advance shall remain unpaid"
