  "smt2": "(set-logic QF_NRA)\n; incurs_additional_debt: true iff at this observation the Gaming Enterprise Borrower incurs, or permits the incurrence of, additional Debt.\n; lender_written_consent: true iff Lender has given written consent to this additional Debt.\n; uncured_default_exists: true iff an uncured Default exists at this observation.\n; debt_is_unsecured: true iff the additional Debt is unsecured.\n; debt_due_in_less_than_six_months: true iff the additional unsecured Debt is due in less than six months.\n; aggregate_short_term_unsecured_debt: Real, dollars; aggregate of all unsecured Debt due in less than six months of the Gaming Enterprise Borrower outstanding at this time, including the additional Debt.\n; tangible_net_worth: Real, dollars; Tangible Net Worth of the Gaming Enterprise Borrower at this observation.\n; ebitda_prior_12_months: Real, dollars; EBITDA of the Gaming Enterprise Borrower for the 12 calendar months immediately preceding the incurrence of the additional Debt.\n; max_debt_service_incl_additional: Real, dollars; maximum Debt Service on all Debt of the Gaming Enterprise Borrower including the additional Debt, over the current fiscal year and all future fiscal years.\n; proceeds_used_solely_to_refund_long_debt: true iff the proceeds of the additional unsecured Debt are used solely to refund existing outstanding Debt of a maturity in excess of one year.\n; has_lower_annual_debt_service_than_refinanced: true iff the additional Debt has a lower annual Debt Service than the Debt refinanced.\n(define-fun covenant_holds (\n  (incurs_additional_debt Bool)\n  (lender_written_consent Bool)\n  (uncured_default_exists Bool)\n  (debt_is_unsecured Bool)\n  (debt_due_in_less_than_six_months Bool)\n  (aggregate_short_term_unsecured_debt Real)\n  (tangible_net_worth Real)\n  (ebitda_prior_12_months Real)\n  (max_debt_service_incl_additional Real)\n  (proceeds_used_solely_to_refund_long_debt Bool)\n  (has_lower_annual_debt_service_than_refinanced Bool)) Bool\n  (=> incurs_additional_debt\n      (or\n        ; (a) written consent of Lender\n        lender_written_consent\n        ; (b) short-term unsecured Debt, no uncured Default, aggregate cap\n        (and (not uncured_default_exists)\n             debt_is_unsecured\n             debt_due_in_less_than_six_months\n             (<= aggregate_short_term_unsecured_debt\n                 (ite (>= 50000.0 (* 0.02 tangible_net_worth))\n                      50000.0\n                      (* 0.02 tangible_net_worth))))\n        ; (c) unsecured Debt, no uncured Default, EBITDA / Debt Service not below 1.35\n        (and (not uncured_default_exists)\n             debt_is_unsecured\n             (>= (/ ebitda_prior_12_months max_debt_service_incl_additional) 1.35))\n        ; (d) unsecured refunding Debt with lower annual Debt Service\n        (and debt_is_unsecured\n             proceeds_used_solely_to_refund_long_debt\n             has_lower_annual_debt_service_than_refinanced))))",
