{
  "status": "formalized",
  "smt2": "(set-logic QF_LRA)\n; is_fiscal_quarter_end: true iff this observation is as of the end of a fiscal quarter of the Company.\n; consolidated_net_debt_to_ebitda_ratio: Consolidated Net Debt to EBITDA Ratio as of the end of the fiscal quarter (atomic; definition not supplied).\n; acquisition_event_occurred_in_quarter: true iff an Acquisition Event occurred during this fiscal quarter.\n; consecutive_quarters_above_3_25: number of consecutive fiscal quarters, counting this one and going back, in which the Consolidated Net Debt to EBITDA Ratio exceeded 3.25:1.0.\n; consolidated_interest_coverage_ratio: Consolidated Interest Coverage Ratio as of the end of the fiscal quarter (atomic; definition not supplied).\n(define-fun covenant_holds ((is_fiscal_quarter_end Bool)\n                            (consolidated_net_debt_to_ebitda_ratio Real)\n                            (acquisition_event_occurred_in_quarter Bool)\n                            (consecutive_quarters_above_3_25 Real)\n                            (consolidated_interest_coverage_ratio Real)) Bool\n  (=> is_fiscal_quarter_end\n      (and\n        ; 8.09(a): ratio must not exceed 3.25, unless the acquisition exception applies\n        (or (<= consolidated_net_debt_to_ebitda_ratio 3.25)\n            (and acquisition_event_occurred_in_quarter\n                 (<= consolidated_net_debt_to_ebitda_ratio 3.5)\n                 (<= consecutive_quarters_above_3_25 4.0)))\n        ; 8.09(b): interest coverage must not be less than 3.0\n        (>= consolidated_interest_coverage_ratio 3.0))))",
