ateral_report Real)\n) Bool\n  (and\n    ; 7.1.1: annual financials due within 90 days after fiscal year end\n    (=> (> days_since_fiscal_year_end 90) annual_financials_delivered)\n    ; 7.1.2: monthly financials due within 30 days after fiscal month end\n    (=> (> days_since_fiscal_month_end 30) monthly_financials_delivered)\n    ; 7.1.5: agings and inventory listings due within 15 days after month end\n    (=> (> days_since_month_end 15) agings_inventory_delivered)\n    ; 7.1.8: Exhibit E statement due within 30 days after month end\n    (=> (> days_since_month_end 30) officer_statement_delivered)\n    ; 7.1.4: Collateral-Obligation Ratio report at least weekly\n    (<= days_since_last_collateral_report 7)\n  )\n)",
