{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n; is_fiscal_quarter_end: true iff the observation date is the end of a fiscal quarter of the Company.\n; closing_date_has_occurred: true iff the observation date is on or after the Closing Date.\n; amount_unpaid_under_notes_or_agreement: true iff any amount remains unpaid under the Notes or under this Agreement at the observation date.\n; commitment_termination_date_not_reached: true iff the Commitment Termination Date has not yet occurred at the observation date.\n; net_income_before_taxes: consolidated net income before income taxes for the four fiscal quarters ending on the observation date.\n; interest_expense: consolidated interest expense for the four fiscal quarters ending on the observation date.\n; rental_expense: consolidated rental expense for the four fiscal quarters ending on the observation date, including rent on capitalized leases.\n; depreciation_amortization: depreciation and amortization for the four fiscal quarters ending on the observation date.\n; current_maturities_ltd: current maturities of long-term debt as shown on the consolidated balance sheet as of the observation date.\n; capitalized_lease_rent: rent on capitalized leases within consolidated rental expense for the four fiscal quarters ending on the observation date. It is excluded from the denominator.\n; dividends_paid: dividends paid during the four fiscal quarters ending on the observation date.\n(define-fun covenant_holds ((is_fiscal_quarter_end Bool)\n                            (closing_date_has_occurred Bool)\n                            (amount_unpaid_under_notes_or_agreement Bool)\n                            (commitment_termination_date_not_reached Bool)\n                            (net_income_before_taxes Real)\n                            (interest_expense Real)\n                            (rental_expense Real)\n                            (depreciation_amortization Real)\n                            (current_maturities_ltd Real)\n                            (capitalized_lease_rent Real)\n                            (dividends_paid Real)) Bool\n  (=> (and is_fiscal_quarter_end\n           closing_date_has_occurred\n           amount_unpaid_under_notes_or_agreement\n           commitment_termination_date_not_reached)\n      (>= (/ (+ net_income_before_taxes interest_expense rental_expense depreciation_amortization)\n             (+ current_maturities_ltd\n                interest_expense\n                (- rental_expense capitalized_lease_rent)\n                dividends_paid))\n          1.5)))",
