{
  "status": "formalized",
  "smt2": "(set-logic QF_LRA)\n(define-fun covenant_holds (\n  (is_parent_fiscal_quarter_end Bool) ; true iff the observation is as of the end of a fiscal quarter of the Parent\n  (ratings_threshold_achieved Bool) ; true iff, as of the end of the current or any earlier fiscal quarter of the Parent, the Corporate Ratings from the Ratings Agencies were each BBB+ or higher and Baa1 or higher, respectively\n  (consolidated_interest_coverage_ratio Real) ; Consolidated Interest Coverage Ratio as of the end of the fiscal quarter, as a number (3.00 to 1.00 = 3.0)\n  (consolidated_leverage_ratio Real) ; Consolidated Leverage Ratio as of the end of the fiscal quarter, as a number (3.00 to 1.00 = 3.0)\n  (lev_tier1_period Bool) ; true iff the fiscal quarter ends after the Closing Date but prior to the earlier of the Acquisition Facility Letter of Credit Issuance Date and the Initial Acquisition Facility Loan Funding Date\n  (lev_tier2_period Bool) ; true iff the fiscal quarter ends after the Acquisition Facility Letter of Credit Issuance Date (if any) but prior to the Initial Acquisition Facility Loan Funding Date\n  (lev_tier3_period Bool) ; true iff the fiscal quarter ends after the Initial Acquisition Facility Loan Funding Date but on or prior to the earlier of the Consolidated Leverage Ratio Stepdown Date and September 30, 2007\n  (lev_tier4_period Bool) ; true iff the fiscal quarter ends on or after October 1, 2007 but on or prior to the earlier of the Consolidated Leverage Ratio Stepdown Date and September 30, 2008\n  (funded_debt_to_total_cap_ratio Real) ; Consolidated Funded Indebtedness to Total Capitalization Ratio at the observation time, as a number (0.50 to 1.00 = 0.5)\n  ) Bool\n  (let ((part_a (and is_parent_fiscal_quarter_end (not ratings_threshold_achieved)))\n        (no_tier (and (not lev_tier1_period) (not lev_tier2_period) (not lev_tier3_period) (not lev_tier4_period))))\n    (and\n      ; 7.10(a)(i): ratio must not be less than 3.00\n      (=> part_a (>= consolidated_interest_coverage_ratio 3.0))\n      ; 7.10(a)(ii)(1)-(5): leverage must not be greater than the applicable cap\n      (=> (and part_a lev_tier1_period) (<= consolidated_leverage_ratio 3.0))\n      (=> (and part_a lev_tier2_period) (<= consolidated_leverage_ratio 4.5))\n      (=> (and part_a lev_tier3_period) (<= consolidated_leverage_ratio 4.0))\n      (=> (and part_a lev_tier4_period) (<= consolidated_leverage_ratio 3.5))\n      (=> (and part_a no_tier) (<= consolidated_leverage_ratio 3.0))\n      ; 7.10(b): at any time once the ratings threshold has been achieved\n      (=> ratings_threshold_achieved (<= funded_debt_to_total_cap_ratio 0.5)))))",
