{
  "status": "formalized",
  "smt2": "(set-logic QF_LRA)\n; is_fiscal_quarter_end: True iff the observation date is the end of a fiscal quarter of the Company.\n; any_advance_unpaid: True iff at the observation time any Advance remains unpaid.\n; any_lender_has_commitment: True iff at the observation time any Lender has any Commitment under the agreement.\n; interest_coverage_ratio: The Company's Interest Coverage Ratio at the observation (as defined in the agreement; atomic input), expressed as X in X:1.0.\n(define-fun covenant_holds ((is_fiscal_quarter_end Bool) (any_advance_unpaid Bool) (any_lender_has_commitment Bool) (interest_coverage_ratio Real)) Bool\n  (=> (and is_fiscal_quarter_end (or any_advance_unpaid any_lender_has_commitment))\n      (>= interest_coverage_ratio 3.5)))",
  "symbols": [
    {
      "name": "is_fiscal_quarter_end",
      "meaning": "True iff the observation date is the end of a fiscal quarter of the Company.",
      "source_quote": "at the end of each of its fiscal quarters"
    },
    {
      "name": "any_advance_unpaid",
      "meaning": "True iff at the observation time any Advance remains unpaid.",
      "source_quote": "So long as any Advance shall remain unpaid or any Lender shall have any Commitment hereunder"
    },
    {
      "name": "any_lender_has_commitment",
      "meaning": "True iff at the observation time any Lender has any Commitment under the agreement.",
      "source_quote": "So long as any Advance shall remain unpaid or any Lender shall have any Commitment hereunder"
    },
    {
      "name": "interest_coverage_ratio",
      "meaning": "The Company's Interest Coverage Ratio at the observation, as defined in the agreement (atomic input), expressed as X in X:1.0.",
      "source_quote": "an Interest Coverage Ratio of at least 3.5:1.0"
    }
  ],
  "notes": "The covenant applies only when the observation is a fiscal quarter end and either an Advance is unpaid or a Lender has a Commitment (an OR). When it applies, 'at least 3.5:1.0' is encoded as a non-strict >= 3.5. The Interest Coverage Ratio definition was not supplied, so it is kept as an atomic Real input. No division is performed in the formula."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n; is_fiscal_year_end: true exactly when the observation is at the end of a fiscal year of the Borrowers.\n; operating_cash_flow: Operating Cash Flow, in currency units, as of the fiscal-year-end observation.\n; debt_service_requirements: Debt Service Requirements, in the same currency units, as of the fiscal-year-end observation.\n(define-fun covenant_holds ((is_fiscal_year_end Bool) (operating_cash_flow Real) (debt_service_requirements Real)) Bool\n  (=> is_fiscal_year_end\n      (>= (/ operating_cash_flow debt_service_requirements) 1.5)))",
  "symbols": [
    {
      "name": "is_fiscal_year_end",
      "meaning": "True exactly when the observation is at the end of a fiscal year of the Borrowers.",
      "source_quote": "at the end of any fiscal year"
    },
    {
      "name": "operating_cash_flow",
      "meaning": "Operating Cash Flow, in currency units, as of the fiscal-year-end observation (numerator of the ratio).",
      "source_quote": "ratio of Operating Cash Flow to Debt Service Requirements"
    },
    {
      "name": "debt_service_requirements",
      "meaning": "Debt Service Requirements, in the same currency units, as of the fiscal-year-end observation (denominator of the ratio).",
      "source_quote": "Debt Service Requirements"
    }
  ],
  "notes": "The covenant prohibits permitting the ratio to be less than 1.5 to 1.0, so compliance requires ratio >= 1.5 (non-strict). The check applies only at fiscal year end. The ratio is computed as Operating Cash Flow divided by Debt Service Requirements. A zero denominator is left to the evaluator to report as unresolved. The lender-consent exception and the 'individually or in the aggregate' wording are not modeled as inputs. Operating Cash Flow and Debt Service Requirements are atomic inputs because their definitions are not supplied. QF_NRA is used because the division is by a variable."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_LRA)\n; rbc_requirements_promulgated: true iff, at this observation time, the NAIC or an Applicable Insurance Regulatory Authority has promulgated risk-based capital ratio requirements or guidelines (the trigger event in Section 5.08).\n; all_material_insurance_subsidiaries_comply: true iff, at this observation time, every Material Insurance Subsidiary complies with the minimum risk-based capital requirements or guidelines applicable to it, as established by the NAIC or the relevant Applicable Insurance Regulatory Authority.\n(define-fun covenant_holds ((rbc_requirements_promulgated Bool) (all_material_insurance_subsidiaries_comply Bool)) Bool\n  (=> rbc_requirements_promulgated all_material_insurance_subsidiaries_comply))",
  "symbols": [
    {
      "name": "rbc_requirements_promulgated",
      "meaning": "True iff, at this observation time, the NAIC or any Applicable Insurance Regulatory Authority has promulgated risk-based capital ratio requirements or guidelines (the trigger event in Section 5.08).",
      "source_quote": "In the event that the NAIC or any Applicable Insurance Regulatory Authority shall at any time promulgate any risk-based capital ratio requirements or guidelines"
    },
    {
      "name": "all_material_insurance_subsidiaries_comply",
      "meaning": "True iff, at this observation time, every Material Insurance Subsidiary complies with the minimum risk-based capital requirements or guidelines applicable to it, as established by the NAIC or the relevant Applicable Insurance Regulatory Authority.",
      "source_quote": "the Borrower shall cause each Material Insurance Subsidiary to comply with the minimum requirements or guidelines applicable to it as established by the NAIC or such Applicable Insurance Regulatory Authority"
