{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n; total_liabilities: Borrower's total liabilities as of the observation date, the numerator of the \"total liabilities-to-Tangible Net Worth ratio\".\n; tangible_net_worth: Borrower's Tangible Net Worth as of the observation date, the denominator of the ratio.\n; is_quarterly_end_date: true iff the observation date is a Quarterly End Date.\n; lender_has_commitment: true iff Lender has any commitment to lend to Borrower hereunder at the observation time.\n; loan_and_obligations_paid_and_discharged: true iff the Loan and all other indebtedness hereunder have been paid in full and all of Borrower's obligations hereunder have been fully discharged at the observation time.\n; lender_prior_written_consent: true iff Borrower received Lender's prior written consent to exceeding the 0.5 to 1 ratio.\n(define-fun covenant_holds ((total_liabilities Real) (tangible_net_worth Real) (is_quarterly_end_date Bool) (lender_has_commitment Bool) (loan_and_obligations_paid_and_discharged Bool) (lender_prior_written_consent Bool)) Bool\n  (=> (and lender_has_commitment\n           (not loan_and_obligations_paid_and_discharged)\n           is_quarterly_end_date\n           (not lender_prior_written_consent))\n      (<= (/ total_liabilities tangible_net_worth) 0.5)))",
  "symbols": [
    {
      "name": "total_liabilities",
      "meaning": "Borrower's total liabilities as of the observation date, the numerator of the leverage ratio.",
      "source_quote": "total liabilities-to-Tangible Net Worth ratio"
    },
    {
      "name": "tangible_net_worth",
      "meaning": "Borrower's Tangible Net Worth as of the observation date, the denominator of the leverage ratio.",
      "source_quote": "total liabilities-to-Tangible Net Worth ratio"
    },
