{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n; any_bank_has_commitment: true iff at this observation time any Bank has any Commitment under the agreement.\n; any_note_amount_unpaid: true iff at this observation time any amount payable under any Note remains unpaid.\n; consolidated_current_assets: Franklin Electric's Consolidated Current Assets at this observation time.\n; consolidated_current_liabilities: Franklin Electric's Consolidated Current Liabilities at this observation time.\n(define-fun covenant_holds ((any_bank_has_commitment Bool) (any_note_amount_unpaid Bool) (consolidated_current_assets Real) (consolidated_current_liabilities Real)) Bool\n  (=> (or any_bank_has_commitment any_note_amount_unpaid)\n      (>= (* 100.0 (/ consolidated_current_assets consolidated_current_liabilities)) 140.0)))",
  "symbols": [
    {
