    {
      "name": "is_quarter_beginning_on_or_after_2001_12_30",
      "meaning": "True iff the fiscal quarter ending at this observation began on or after December 30, 2001.",
      "source_quote": "As of the end of each fiscal quarter beginning December 30,2001"
    },
    {
      "name": "bank_otherwise_agrees",
      "meaning": "True iff the Bank has otherwise agreed (waived or modified) the Section 9.4 requirement for this observation.",
