{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n; is_fiscal_quarter_end: true exactly when the observation date is the last day of a fiscal quarter of Borrower.\n; ore_and_repossessed_assets: consolidated Subsidiary Bank other real estate owned and repossessed assets, in currency units.\n; non_accrual_loans: consolidated Subsidiary Bank non-accrual loans, in currency units.\n; past_due_90_accruing_loans_excl_tdr: consolidated Subsidiary Bank loans with any payment 90 or more days past due that continue to accrue interest, in currency units, excluding troubled debt restructurings that continue to accrue interest.\n; capital_stock: consolidated Subsidiary Bank capital stock, in currency units.\n; surplus: consolidated Subsidiary Bank surplus, in currency units.\n; undivided_profits: consolidated Subsidiary Bank undivided profits, in currency units.\n; allowance_for_loan_losses: consolidated Subsidiary Bank Allowance for Loan Losses (as defined in Section 7.4), in currency units.\n; capital_qualified_notes_debentures: consolidated Subsidiary Bank capital qualified notes and debentures, in currency units, counting only the portion that qualifies as capital under the primary federal regulator's rules, regulations and guidance.\n; intangibles: consolidated Subsidiary Bank total intangibles, in currency units, subtracted in Tangible Primary Capital.\n(define-fun covenant_holds (\n  (is_fiscal_quarter_end Bool)\n  (ore_and_repossessed_assets Real)\n  (non_accrual_loans Real)\n  (past_due_90_accruing_loans_excl_tdr Real)\n  (capital_stock Real)\n  (surplus Real)\n  (undivided_profits Real)\n  (allowance_for_loan_losses Real)\n  (capital_qualified_notes_debentures Real)\n  (intangibles Real)) Bool\n  (=> is_fiscal_quarter_end\n      (<= (/ (+ ore_and_repossessed_assets non_accrual_loans past_due_90_accruing_loans_excl_tdr)\n             (- (+ capital_stock surplus undivided_profits allowance_for_loan_losses capital_qualified_notes_debentures) intangibles))\n          0.13)))",
