      "meaning": "True iff the observation time is on or after the date of this Agreement.",
      "source_quote": "From the date of this Agreement and thereafter"
    },
    {
      "name": "credit_facility_expired_or_terminated",
      "meaning": "True iff the Credit Facility has expired or been terminated at the observation time.",
      "source_quote": "until the expiration or termination of the Credit Facility"
    },
    {
      "name": "notes_and_other_liabilities_paid_in_full",
      "meaning": "True iff the Notes and other liabilities of the Company under the Agreement have been paid in full at the observation time.",
      "source_quote": "until the Notes and other liabilities of the Company hereunder are paid in full"
    },
    {
      "name": "ebitda_to_fixed_charge_ratio",
