  "smt2": "(set-logic QF_NRA)\n; is_month_end: true iff the observation date is the last day of a calendar month.\n; is_quarter_end: true iff the observation date is the last day of a calendar quarter.\n; is_on_or_after_2009_12_31: true iff the month or quarter ending on the observation date ends on or after December 31, 2009.\n; delinquent_contract_balance_remaining: aggregate Contract Balance Remaining for all Delinquent Leases in the Managed Portfolio, as determined on the observation date.\n; total_contract_balance_remaining: aggregate Contract Balance Remaining for all Leases in the Managed Portfolio, as determined on the observation date.\n; defaulted_net_investment_12m: aggregate GAAP net investment for all Managed Portfolio Leases that were Defaulted Leases (under clause (a) or (c) of the definition) as of the observation date or became Defaulted Leases (under clause (b)) during the twelve-month period then ended.\n; average_monthly_net_investment_12m: average monthly aggregate GAAP net investment for all Leases in the Managed Portfolio during the twelve-month period ended on the observation date.\n; static_pool_loss_ratio_recent: Static Pool Loss Ratio for the Managed Portfolio for Leases originated or acquired during the twelve-month period ending on the last day of the calendar quarter, as a fraction (0.025 = 2.5%).\n; static_pool_loss_ratio_13_24: Static Pool Loss Ratio for the Managed Portfolio for Leases originated or acquired during the thirteenth through twenty-fourth month period preceding the last day of the calendar quarter, as a fraction.\n; static_pool_loss_ratio_older: Static Pool Loss Ratio for the Managed Portfolio for Leases originated or acquired prior to the thirteenth-through-twenty-fourth month period (i.e. older than 24 months before quarter end), as a fraction.\n(define-fun covenant_holds (\n    (is_month_end Bool)\n    (is_quarter_end Bool)\n    (is_on_or_after_2009_12_31 Bool)\n    (delinquent_contract_balance_remaining Real)\n    (total_contract_balance_remaining Real)\n    (defaulted_net_investment_12m Real)\n    (average_monthly_net_investment_12m Real)\n    (static_pool_loss_ratio_recent Real)\n    (static_pool_loss_ratio_13_24 Real)\n    (static_pool_loss_ratio_older Real)) Bool\n  (and\n    ; 7.19(a): delinquency ratio must not exceed 3.5% on last day of any calendar month\n    (=> is_month_end\n        (<= (/ delinquent_contract_balance_remaining total_contract_balance_remaining) 0.035))\n    ; 7.19(b): default/charge-off ratio must not exceed 7.0% on month-ends on or after 12/31/2009\n    (=> (and is_month_end is_on_or_after_2009_12_31)\n        (<= (/ defaulted_net_investment_12m average_monthly_net_investment_12m) 0.07))\n    ; 7.19(c): static pool loss ratio caps by origination cohort at quarter-ends on or after 12/31/2009\n    (=> (and is_quarter_end is_on_or_after_2009_12_31)\n        (and (<= static_pool_loss_ratio_recent 0.025)\n             (<= static_pool_loss_ratio_13_24 0.0525)\n             (<= static_pool_loss_ratio_older 0.07)))))",
