{
  "status": "formalized",
  "smt2": "(set-logic QF_LRA)\n; obligations_unpaid: true when any part of the Obligations remains unpaid at the observation time.\n; waived_in_writing: true when Lender has waived this Section 5.07 covenant in writing as of the observation time.\n; bad_debt_ratio: the Bad Debt Ratio at the observation time, as a decimal fraction (0.01 = 1%). It is an atomic input because the source gives no arithmetic definition.\n(define-fun covenant_holds ((obligations_unpaid Bool) (waived_in_writing Bool) (bad_debt_ratio Real)) Bool\n  (=> (and obligations_unpaid (not waived_in_writing))\n      (>= bad_debt_ratio 0.01)))",
  "symbols": [
    {
      "name": "obligations_unpaid",
      "meaning": "True when any part of the Obligations remains unpaid at the observation time.",
      "source_quote": "While any part of the Obligations remains unpaid"
    },
    {
      "name": "waived_in_writing",
      "meaning": "True when Lender has waived this covenant in writing as of the observation time.",
      "source_quote": "unless waived in writing by Lender"
    },
    {
      "name": "bad_debt_ratio",
      "meaning": "The Bad Debt Ratio at the observation time, as a decimal fraction (0.01 = 1%). It is an atomic input because no definition is supplied.",
      "source_quote": "Bad Debt Ratio"
    }
  ],
  "notes": "The covenant forbids the Bad Debt Ratio from being less than 1% at any time, so compliance at an observation requires ratio >= 0.01 (non-strict). The covenant applies only while the Obligations are unpaid and no written waiver is in effect, so the body is an implication on those two conditions. The 'at any time' language is handled pointwise: the evaluator checks every supplied observation. No division is performed, because the Bad Debt Ratio is an atomic input."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_LRA)\n; fixed_charge_coverage_ratio: Fixed Charge Coverage Ratio of the Company for the trailing twelve month period ending on the observation date (a fiscal month end), as a ratio (1.1 means 1.1 to 1.0).\n; liquidity: Liquidity in US dollars at the observation time.\n; is_fiscal_month_end: true iff the observation date is the last day of a fiscal month of the Company.\n; fccr_testing_commenced: true iff the observation date is on or after the fiscal month end immediately prior to the date on which Liquidity is less than $80,000,000.\n(define-fun covenant_holds ((fixed_charge_coverage_ratio Real) (liquidity Real) (is_fiscal_month_end Bool) (fccr_testing_commenced Bool)) Bool\n  (and\n    ; 6.12(a): FCCR must not be less than 1.1 to 1.0 on tested fiscal month ends once testing has commenced\n    (=> (and fccr_testing_commenced is_fiscal_month_end) (>= fixed_charge_coverage_ratio 1.1))\n    ; 6.12(b): Liquidity must be not less than $50,000,000 at all times\n    (>= liquidity 50000000.0)))",
  "symbols": [
    {
      "name": "fixed_charge_coverage_ratio",
      "meaning": "Fixed Charge Coverage Ratio of the Company for the trailing twelve month period ending on the observation date (a fiscal month end), as a ratio (1.1 means 1.1 to 1.0).",
      "source_quote": "the Fixed Charge Coverage Ratio, determined for any trailing twelve month period ending on the last day of each fiscal month of the Company"
    },
    {
      "name": "liquidity",
      "meaning": "Liquidity in US dollars at the observation time.",
      "source_quote": "Liquidity of not less than $50,000,000"
    },
    {
      "name": "is_fiscal_month_end",
      "meaning": "True iff the observation date is the last day of a fiscal month of the Company.",
      "source_quote": "the last day of each fiscal month of the Company"
