    },
    {
      "name": "consolidated_leverage_ratio",
      "meaning": "Consolidated Leverage Ratio as of the observation date, expressed as a ratio to 1.0 (atomic input).",
      "source_quote": "the Consolidated Leverage Ratio will not exceed 3.5 to 1.0"
    },
    {
      "name": "investment_grade_date_occurred",
      "meaning": "True iff the observation date is on or after the Investment Grade Date, after which Section 7.11(b) ceases to apply.",
      "source_quote": "From and after the Investment Grade Date, this Section 7.11(b) shall cease to apply"
    },
    {
      "name": "consolidated_funded_debt",
      "meaning": "Consolidated Funded Debt at the observation date.",
      "source_quote": "Consolidated Funded Debt shall not at any time exceed"
    },
    {
      "name": "consolidated_ebitda_midstream_ltm",
      "meaning": "Consolidated EBITDA-Midstream for the four fiscal quarters ending on the observation date, or ending on the last day of the most recently ended fiscal quarter if the date is not a quarter end.",
      "source_quote": "Consolidated EBITDA-Midstream during the four fiscal quarters ending on such date"
