{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n; is_fiscal_quarter_end: true exactly when the observation date is a fiscal quarter end of the Borrower.\n; net_income: net income of the Borrower and its consolidated Subsidiaries for the period of four consecutive fiscal quarters ending on or most recently ended prior to the observation day.\n; income_taxes: income taxes of the Borrower and its consolidated Subsidiaries for that same four-quarter period.\n; noncash_provisions_writeoffs: non-cash provisions for, or actual write-offs of, assets (without duplication in respect of any prior period), for the Borrower and its consolidated Subsidiaries over that same four-quarter period.\n; interest_accrued: all interest in respect of Indebtedness (including the interest component of payments on Capital Lease Obligations) accrued or capitalized during that same four-quarter period, whether or not actually paid.\n; net_hedging_interest_payable: net amount payable under interest-related Hedging Agreements during that same four-quarter period (negative if a net amount is receivable), whether or not actually paid or received.\n; lease_interest_factor: estimate of the portion of minimum rents under operating leases representing the interest factor, for that same four-quarter period.\n; Fixed Charges = interest_accrued + net_hedging_interest_payable + lease_interest_factor.\n; Cash Flow = net_income + income_taxes + noncash_provisions_writeoffs + Fixed Charges.\n; Covenant: at a fiscal quarter end, Fixed Charge Coverage Ratio (Cash Flow / Fixed Charges) must not be less than 1.30.\n(define-fun covenant_holds ((is_fiscal_quarter_end Bool) (net_income Real) (income_taxes Real) (noncash_provisions_writeoffs Real) (interest_accrued Real) (net_hedging_interest_payable Real) (lease_interest_factor Real)) Bool\n  (=> is_fiscal_quarter_end\n      (>= (/ (+ net_income income_taxes noncash_provisions_writeoffs\n                (+ interest_accrued net_hedging_interest_payable lease_interest_factor))\n             (+ interest_accrued net_hedging_interest_payable lease_interest_factor))\n          1.30)))",
  "symbols": [
    {
      "name": "is_fiscal_quarter_end",
      "meaning": "True exactly when the observation date is a fiscal quarter end of the Borrower.",
      "source_quote": "as at any fiscal quarter end"
    },
    {
      "name": "net_income",
      "meaning": "Net income of the Borrower and its consolidated Subsidiaries for the four consecutive fiscal quarters ending on or most recently ended prior to the observation day.",
      "source_quote": "net income"
    },
    {
      "name": "income_taxes",
      "meaning": "Income taxes of the Borrower and its consolidated Subsidiaries for the same four-quarter period.",
      "source_quote": "income taxes"
    },
    {
      "name": "noncash_provisions_writeoffs",
      "meaning": "Non-cash provisions for, or actual write-offs of, assets (without duplication in respect of any prior period) for the same four-quarter period, consolidated.",
      "source_quote": "non-cash provisions for, or actual write-offs of, assets"
    },
    {
      "name": "interest_accrued",
      "meaning": "All interest in respect of Indebtedness (including the interest component of Capital Lease Obligation payments) accrued or capitalized during the same four-quarter period, whether or not paid.",
      "source_quote": "all interest in respect of Indebtedness (including the interest component of any payments in respect of Capital Lease Obligations) accrued or capitalized during such period"
    },
    {
      "name": "net_hedging_interest_payable",
      "meaning": "Net amount payable under interest-related Hedging Agreements during the same four-quarter period; negative when a net amount is receivable.",
