{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n; adjusted_consolidated_debt: Adjusted Consolidated Debt, numerator of the leverage ratio, as of the Test Period last ended at the observation time.\n; adjusted_operating_income: Adjusted Operating Income for the Test Period last ended at the observation time, denominator of the leverage ratio.\n; in_period_initial_to_1995: true iff the observation time is on or after the Initial Borrowing Date and on or before December 31, 1995.\n; in_period_1996: true iff the observation time is from January 1, 1996 to and including December 31, 1996.\n; in_period_1997: true iff the observation time is from January 1, 1997 to and including December 31, 1997.\n; in_period_thereafter: true iff the observation time is after December 31, 1997.\n(define-fun covenant_holds ((adjusted_consolidated_debt Real) (adjusted_operating_income Real) (in_period_initial_to_1995 Bool) (in_period_1996 Bool) (in_period_1997 Bool) (in_period_thereafter Bool)) Bool\n  (and\n    (=> in_period_initial_to_1995 (<= (/ adjusted_consolidated_debt adjusted_operating_income) 2.6))\n    (=> in_period_1996 (<= (/ adjusted_consolidated_debt adjusted_operating_income) 2.45))\n    (=> in_period_1997 (<= (/ adjusted_consolidated_debt adjusted_operating_income) 2.25))\n    (=> in_period_thereafter (<= (/ adjusted_consolidated_debt adjusted_operating_income) 2.0))))",
  "symbols": [
    {
      "name": "adjusted_consolidated_debt",
      "meaning": "Adjusted Consolidated Debt, the numerator of the leverage ratio, as measured for the Test Period last ended at the observation time.",
      "source_quote": "Adjusted Consolidated Debt"
    },
    {
      "name": "adjusted_operating_income",
      "meaning": "Adjusted Operating Income for the Test Period last ended at the observation time, the denominator of the leverage ratio.",
      "source_quote": "Adjusted Operating Income for the Test Period last ended"
    },
    {
      "name": "in_period_initial_to_1995",
      "meaning": "True iff the observation time is on or after the Initial Borrowing Date and on or before December 31, 1995 (maximum ratio 2.60:1).",
      "source_quote": "Initial Borrowing Date"
    },
    {
      "name": "in_period_1996",
      "meaning": "True iff the observation time is from January 1, 1996 to and including December 31, 1996 (maximum ratio 2.45:1).",
      "source_quote": "January 1, 1996"
    },
    {
      "name": "in_period_1997",
      "meaning": "True iff the observation time is from January 1, 1997 to and including December 31, 1997 (maximum ratio 2.25:1).",
      "source_quote": "January 1, 1997"
    },
    {
      "name": "in_period_thereafter",
      "meaning": "True iff the observation time is after December 31, 1997 (maximum ratio 2.0:1).",
      "source_quote": "Thereafter 2.0:1"
    }
  ],
  "notes": "The covenant is a pointwise maximum leverage ratio, where 'not ... more than' becomes <=. The ratio is Adjusted Consolidated Debt divided by Adjusted Operating Income, and the threshold depends on the period. QF_NRA is used because the division is by a variable. A zero denominator is reported as unresolved by the evaluator, per policy. Period flags are decomposed into separate calendar inputs, and each applies its own threshold. Definitions of Adjusted Consolidated Debt, Adjusted Operating Income, Test Period and Initial Borrowing Date were not supplied, so the first two stay atomic Real inputs and the last is used only in the period flags."
}

{
