  "smt2": "(set-logic QF_LRA)\n; is_fiscal_year_end: true exactly when the observation date is the end of a fiscal year of the Borrower(s).\n; profit_to_expense_ratio: the Profit to Expense Ratio (profit divided by expense, as one atomic ratio because the source gives no formula) at this observation, where 1:1 is the value 1.0.\n(define-fun covenant_holds ((is_fiscal_year_end Bool) (profit_to_expense_ratio Real)) Bool\n  (=> is_fiscal_year_end (>= profit_to_expense_ratio 1.0)))",
  "symbols": [
    {
      "name": "is_fiscal_year_end",
      "meaning": "True exactly when the observation date is the end of a fiscal year of the Borrower(s); false at all other observation times.",
      "source_quote": "As at the end of each fiscal year"
    },
    {
      "name": "profit_to_expense_ratio",
      "meaning": "The Profit to Expense Ratio at the observation, supplied as one atomic Real because the source gives no arithmetic definition. A ratio of 1:1 corresponds to the value 1.0.",
      "source_quote": "a Profit to Expense Ratio of not less than 1:1"
    }
  ],
  "notes": "The requirement applies only at fiscal year end, so the body is an implication from is_fiscal_year_end. 'Not less than 1:1' is non-strict, giving >= 1.0. The source does not define profit or expense, so the ratio is left atomic and no sign or denominator assumptions are made. The opening phrase 'until payment in full of the Obligations and termination of this Agreement' describes how long the covenant lasts. The evaluator only supplies observations while the covenant is in force, so it is not encoded."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_LRA)\n; term_loan_remains_unpaid: true if all or any portion of the Term Loan remains unpaid at the observation time.\n; other_obligation_unpaid_or_unperformed: true if any other Obligation remains unpaid or unperformed at the observation time.\n; aggregate_commitments_in_force: true if any portion of the Aggregate Commitments remains in force at the observation time.\n; is_last_day_of_fiscal_quarter: true if the observation date is the last day of a Fiscal Quarter.\n; total_leverage_ratio: the Total Leverage Ratio as of the observation date, as a ratio to 1.00 (0.60 means 0.60 to 1.00).\n(define-fun covenant_holds ((term_loan_remains_unpaid Bool) (other_obligation_unpaid_or_unperformed Bool) (aggregate_commitments_in_force Bool) (is_last_day_of_fiscal_quarter Bool) (total_leverage_ratio Real)) Bool\n  (=> (and (or term_loan_remains_unpaid other_obligation_unpaid_or_unperformed aggregate_commitments_in_force) is_last_day_of_fiscal_quarter)\n      (<= total_leverage_ratio 0.60)))",
  "symbols": [
    {
      "name": "term_loan_remains_unpaid",
      "meaning": "True if all or any portion of the Term Loan remains unpaid at the observation time.",
      "source_quote": "So long as all or any portion of the Term Loan remains unpaid"
    },
    {
      "name": "other_obligation_unpaid_or_unperformed",
      "meaning": "True if any other Obligation remains unpaid or unperformed at the observation time.",
      "source_quote": "any other Obligation remains unpaid or unperformed"
    },
    {
      "name": "aggregate_commitments_in_force",
      "meaning": "True if any portion of the Aggregate Commitments remains in force at the observation time.",
      "source_quote": "any portion of the Aggregate Commitments remains in force"
    },
    {
      "name": "is_last_day_of_fiscal_quarter",
      "meaning": "True if the observation date is the last day of a Fiscal Quarter.",
      "source_quote": "as of the last day of any Fiscal Quarter"
    },
    {
      "name": "total_leverage_ratio",
      "meaning": "The Total Leverage Ratio as of the observation date, expressed as a ratio to 1.00 (0.60 means 0.60 to 1.00). It is an atomic input because no arithmetic definition is supplied.",
      "source_quote": "Permit the Total Leverage Ratio, as of the last day of any Fiscal Quarter, to be greater than 0.60 to 1.00."
