}

{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n; is_monthly_period_end: true iff the observation date is the end of a monthly accounting period of a fiscal year.\n; is_fiscal_year_end: true iff the observation date is the end of a fiscal year.\n; ebit_rolling_12m: EBIT for the 12 month period ending on the observation date.\n; interest_expense_rolling_12m: Interest Expense for the same 12 month period ending on the observation date.\n(define-fun covenant_holds ((is_monthly_period_end Bool) (is_fiscal_year_end Bool) (ebit_rolling_12m Real) (interest_expense_rolling_12m Real)) Bool\n  (=> (or is_monthly_period_end is_fiscal_year_end)\n      (>= (/ ebit_rolling_12m interest_expense_rolling_12m) 1.5)))",
  "symbols": [
