      "source_quote": "as of the end of each fiscal year"
    },
    {
      "name": "ebit_rolling_12m",
      "meaning": "EBIT for the 12 month period ending on the observation date (rolling 12 month basis).",
      "source_quote": "on a rolling 12 month basis (with the period of determination being the 12 month period ending on the date as of which such determination is made)"
