}

{
  "status": "formalized",
  "smt2": "(set-logic QF_LRA)\n; obligations_outstanding: true if the Obligations have not been repaid in full (other than contingent obligations intended to survive termination of the Agreement or other Loan Documents) at the observation time.\n; commitments_outstanding: true if the Commitments have not yet expired and terminated at the observation time.\n; agent_waiver_in_writing: true if the Administrative Agent, on behalf of the Lenders, has waived compliance with the financial covenant in writing at the observation time.\n; is_last_day_of_fiscal_quarter: true if the observation date is the last day of a fiscal quarter of Borrower (for 5.11.2, this is also the last day of a period of four consecutive fiscal quarters ending on that date).\n; date_on_or_after_2004_09_30: true if the fiscal quarter or four-quarter period ending on the observation date ends on or after September 30, 2004.\n; consolidated_leverage_ratio: Consolidated Leverage Ratio as at the observation date, expressed as X in 'X to 1' (atomic input, definition not supplied).\n; consolidated_interest_coverage_ratio: Consolidated Interest Coverage Ratio for the four consecutive fiscal quarters ending on the observation date, expressed as X in 'X to 1' (atomic input, definition not supplied).\n(define-fun covenant_holds ((obligations_outstanding Bool) (commitments_outstanding Bool) (agent_waiver_in_writing Bool) (is_last_day_of_fiscal_quarter Bool) (date_on_or_after_2004_09_30 Bool) (consolidated_leverage_ratio Real) (consolidated_interest_coverage_ratio Real)) Bool\n  (=> (and (or obligations_outstanding commitments_outstanding) (not agent_waiver_in_writing))\n      (and\n        ; 5.11.1 leverage ratio must not exceed 5.25 to 1\n        (=> (and is_last_day_of_fiscal_quarter date_on_or_after_2004_09_30)\n            (<= consolidated_leverage_ratio 5.25))\n        ; 5.11.2 interest coverage ratio must not be less than 2.25 to 1\n        (=> (and is_last_day_of_fiscal_quarter date_on_or_after_2004_09_30)\n            (>= consolidated_interest_coverage_ratio 2.25)))))",
  "symbols": [
    {
      "name": "obligations_outstanding",
      "meaning": "True if the Obligations have not been repaid in full (other than contingent obligations intended to survive termination of the Agreement or other Loan Documents) at the observation time.",
      "source_quote": "until the repayment in full of the Obligations (other than those contingent obligations that are intended to survive the termination of this Agreement or the other Loan Documents)"
    },
    {
      "name": "commitments_outstanding",
      "meaning": "True if the Commitments have not yet expired and terminated at the observation time.",
      "source_quote": "the expiration and termination of all Commitments"
    },
    {
      "name": "agent_waiver_in_writing",
      "meaning": "True if the Administrative Agent, on behalf of the Lenders, has waived compliance with the financial covenant in writing at the observation time.",
      "source_quote": "unless Administrative Agent on behalf of the Lenders waives compliance in writing"
    },
    {
      "name": "is_last_day_of_fiscal_quarter",
      "meaning": "True if the observation date is the last day of a fiscal quarter of Borrower, which is also the last day of the four-consecutive-fiscal-quarter period ending on that date.",
      "source_quote": "as at the last day of any fiscal quarter"
    },
    {
      "name": "date_on_or_after_2004_09_30",
      "meaning": "True if the fiscal quarter or four-quarter period ending on the observation date ends on or after September 30, 2004.",
      "source_quote": "ending on or after September 30, 2004"
    },
    {
      "name": "consolidated_leverage_ratio",
      "meaning": "Consolidated Leverage Ratio as at the observation date, expressed as X in 'X to 1' (atomic input; definition not supplied).",
      "source_quote": "Borrower shall not permit the Consolidated Leverage Ratio as at the last day of any fiscal quarter"
    },
    {
      "name": "consolidated_interest_coverage_ratio",
      "meaning": "Consolidated Interest Coverage Ratio for the four consecutive fiscal quarters ending on the observation date, expressed as X in 'X to 1' (atomic input; definition not supplied).",
      "source_quote": "Consolidated Interest Coverage Ratio as at the last day of any period of four consecutive fiscal quarters of Borrower"
    }
  ],
  "notes": "Pointwise translation. The covenant applies while the Obligations or the Commitments remain outstanding and no written waiver exists. The leverage test is ratio <= 5.25 (not exceeding) and the interest coverage test is ratio >= 2.25 (not less than). Both tests apply at the last day of a fiscal quarter on or after 2004-09-30. The four-quarter period for 5.11.2 ends on that same quarter-end date, and the first such period ends on 2004-09-30, so one shared date flag covers both. The two ratios are atomic Real inputs because their definitions are not supplied, and no division is performed."
}

{
