{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n; is_fiscal_quarter_end: true iff the observation date is the end of a fiscal quarter of the Company.\n; is_on_or_after_2011_06_30: true iff the fiscal quarter end is on or after June 30, 2011.\n; consolidated_ebitdar: Consolidated EBITDAR of the Company and its Subsidiaries (consolidated) for the 4 consecutive fiscal quarters ending with this quarter end, pro forma for any Permitted Acquisition per the source.\n; consolidated_capex: Consolidated Capital Expenditures of the Company and its Subsidiaries for the same 4-quarter period, pro forma.\n; consolidated_interest_expense: Consolidated Interest Expense of the Company and its Subsidiaries for the same 4-quarter period, pro forma.\n; consolidated_rental_payments: Consolidated Rental Payments of the Company and its Subsidiaries for the same 4-quarter period, pro forma.\n; consolidated_total_indebtedness: Consolidated Total Indebtedness of the Company and its Subsidiaries as of this fiscal quarter end, pro forma for any Permitted Acquisition per the source.\n; consolidated_ebitda: Consolidated EBITDA of the Company and its Subsidiaries for the 4 consecutive fiscal quarters ending with this quarter end, pro forma.\n(define-fun covenant_holds (\n    (is_fiscal_quarter_end Bool)\n    (is_on_or_after_2011_06_30 Bool)\n    (consolidated_ebitdar Real)\n    (consolidated_capex Real)\n    (consolidated_interest_expense Real)\n    (consolidated_rental_payments Real)\n    (consolidated_total_indebtedness Real)\n    (consolidated_ebitda Real)) Bool\n  (=> (and is_fiscal_quarter_end is_on_or_after_2011_06_30)\n      (and\n        ; 6.11.1: FCCR must not be less than 1.15 to 1.00\n        (>= (/ (- consolidated_ebitdar consolidated_capex)\n               (+ consolidated_interest_expense consolidated_rental_payments))\n            1.15)\n        ; 6.11.2: Leverage Ratio must not be greater than 2.25 to 1.0\n        (<= (/ consolidated_total_indebtedness consolidated_ebitda) 2.25))))",
  "symbols": [
