{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n; consolidated_ebitda: Consolidated EBITDA of the Borrower for the period of four consecutive fiscal quarters ending at this observation.\n; consolidated_interest_expense: Consolidated Interest Expense of the Borrower for the same four-consecutive-fiscal-quarter period.\n; period_ends_dec_29_2001: True iff the four-quarter period ends during the period 'December 29, 2001' (that date only).\n; period_ends_dec_30_2001_to_mar_30_2002: True iff the four-quarter period ends during December 30, 2001 through March 30, 2002.\n; period_ends_mar_31_2002_to_jun_28_2003: True iff the four-quarter period ends during March 31, 2002 through June 28, 2003.\n; period_ends_jun_29_2003_to_jun_26_2004: True iff the four-quarter period ends during June 29, 2003 through June 26, 2004.\n; period_ends_jun_27_2004_and_thereafter: True iff the four-quarter period ends on or after June 27, 2004.\n(define-fun covenant_holds ((consolidated_ebitda Real)\n                            (consolidated_interest_expense Real)\n                            (period_ends_dec_29_2001 Bool)\n                            (period_ends_dec_30_2001_to_mar_30_2002 Bool)\n                            (period_ends_mar_31_2002_to_jun_28_2003 Bool)\n                            (period_ends_jun_29_2003_to_jun_26_2004 Bool)\n                            (period_ends_jun_27_2004_and_thereafter Bool)) Bool\n  (and\n    (=> period_ends_dec_29_2001\n        (>= (/ consolidated_ebitda consolidated_interest_expense) 2.5))\n    (=> period_ends_dec_30_2001_to_mar_30_2002\n        (>= (/ consolidated_ebitda consolidated_interest_expense) 2.75))\n    (=> period_ends_mar_31_2002_to_jun_28_2003\n        (>= (/ consolidated_ebitda consolidated_interest_expense) 3.0))\n    (=> period_ends_jun_29_2003_to_jun_26_2004\n        (>= (/ consolidated_ebitda consolidated_interest_expense) 3.25))\n    (=> period_ends_jun_27_2004_and_thereafter\n        (>= (/ consolidated_ebitda consolidated_interest_expense) 3.5))))",
