  "smt2": "(set-logic QF_NRA)\n; is_fiscal_quarter_end: true exactly when the observation date is the end of a fiscal quarter of the Company.\n; senior_funded_debt: Senior Funded Debt, the numerator of the ratio, measured as of the observation date.\n; adjusted_ebitda: Adjusted EBITDA, the denominator of the ratio, measured for the Adjusted EBITDA period used in the covenant test as of that date.\n(define-fun covenant_holds ((is_fiscal_quarter_end Bool) (senior_funded_debt Real) (adjusted_ebitda Real)) Bool\n  (=> is_fiscal_quarter_end (<= (/ senior_funded_debt adjusted_ebitda) 4.75)))",
  "symbols": [
    {
      "name": "is_fiscal_quarter_end",
      "meaning": "True exactly when the observation date is the end of a fiscal quarter of the Company, so the covenant test applies.",
      "source_quote": "as of the end of each fiscal quarter"
    },
    {
      "name": "senior_funded_debt",
      "meaning": "Senior Funded Debt, the numerator of the ratio, measured as of the observation date. The source gives no further definition, so this is an atomic Real input.",
      "source_quote": "Senior Funded Debt"
    },
    {
      "name": "adjusted_ebitda",
      "meaning": "Adjusted EBITDA, the denominator of the ratio, for the measurement period used in the covenant test as of the observation date. The source gives no further definition, so this is an atomic Real input.",
      "source_quote": "Adjusted EBITDA"
    }
  ],
  "notes": "The covenant is applied at fiscal quarter-end observations only. The ratio is Senior Funded Debt divided by Adjusted EBITDA, and the limit is non-strict (not more than 4.75 to 1.0). Division by variable requires QF_NRA. A zero Adjusted EBITDA is left to the evaluator to report as unresolved, with no positivity assumption added. The 'until the Revolving Credit Maturity Date and thereafter...' duration is the covenant's temporal scope, and the evaluator covers it by supplying only relevant observations."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_LRA)\n; senior_secured_net_leverage_ratio: Senior Secured Net Leverage Ratio of the Borrower as of the observation date (atomic ratio; definition not supplied), expressed as a number x for x:1.00.\n; is_last_day_of_fiscal_quarter: true iff the observation date is the last day of a fiscal quarter.\n; termination_date_has_occurred: true iff the Termination Date has already occurred at the observation date, so the covenant no longer applies.\n; in_period_jun2008_to_dec2008: true iff the observation date is in the period from the last day of the fiscal quarter ending June 30, 2008 through the day before the last day of the fiscal quarter ending December 31, 2008 (limit 6.50:1.00).\n; in_period_dec2008_to_jun2009: true iff the observation date is in the period from the last day of the fiscal quarter ending December 31, 2008 through the day before the last day of the fiscal quarter ending June 30, 2009 (limit 6.25:1.00).\n; in_period_jun2009_to_jun2010: true iff the observation date is in the period from the last day of the fiscal quarter ending June 30, 2009 through the day before the last day of the fiscal quarter ending June 30, 2010 (limit 6.00:1.00).\n; in_period_jun2010_to_jun2011: true iff the observation date is in the period from the last day of the fiscal quarter ending June 30, 2010 through the day before the last day of the fiscal quarter ending June 30, 2011 (limit 5.75:1.00).\n; in_period_jun2011_to_jun2012: true iff the observation date is in the period from the last day of the fiscal quarter ending June 30, 2011 through the day before the last day of the fiscal quarter ending June 30, 2012 (limit 5.25:1.00).\n; in_period_thereafter: true iff the observation date is after all of the preceding stated periods (limit 5.00:1.00).\n(define-fun covenant_holds (\n    (senior_secured_net_leverage_ratio Real)\n    (is_last_day_of_fiscal_quarter Bool)\n    (termination_date_has_occurred Bool)\n    (in_period_jun2008_to_dec2008 Bool)\n    (in_period_dec2008_to_jun2009 Bool)\n    (in_period_jun2009_to_jun2010 Bool)\n    (in_period_jun2010_to_jun2011 Bool)\n    (in_period_jun2011_to_jun2012 Bool)\n    (in_period_thereafter Bool)) Bool\n  (=> (and is_last_day_of_fiscal_quarter (not termination_date_has_occurred))\n      (and\n        (=> in_period_jun2008_to_dec2008 (<= senior_secured_net_leverage_ratio 6.5))\n        (=> in_period_dec2008_to_jun2009 (<= senior_secured_net_leverage_ratio 6.25))\n        (=> in_period_jun2009_to_jun2010 (<= senior_secured_net_leverage_ratio 6.0))\n        (=> in_period_jun2010_to_jun2011 (<= senior_secured_net_leverage_ratio 5.75))\n        (=> in_period_jun2011_to_jun2012 (<= senior_secured_net_leverage_ratio 5.25))\n        (=> in_period_thereafter (<= senior_secured_net_leverage_ratio 5.0)))))",
