      "source_quote": "The last day of the Borrower's fiscal quarter ending June 30, 2008 through and including the day before the last day of Holdings' fiscal quarter ending December 31, 2008 6.50:1.00"
    },
    {
      "name": "in_period_dec2008_to_jun2009",
      "meaning": "True iff the observation date is in the period from the last day of the fiscal quarter ending December 31, 2008 through the day before the last day of the fiscal quarter ending June 30, 2009 (limit 6.25:1.00).",
      "source_quote": "The last day of the Borrower's fiscal quarter ending December 31, 2008 through and including the day before the last day of the Borrower's fiscal quarter ending June 30, 2009 6.25:1.00"
