    },
    {
      "name": "total_capitalization",
      "meaning": "Total Capitalization at the observation time, as defined in the Agreement; same currency units as long_term_indebtedness. It is the denominator of the ratio.",
      "source_quote": "the ratio of Long-Term Indebtedness to Total Capitalization"
    },
    {
      "name": "commitments_terminated",
      "meaning": "True iff the Commitments have been terminated at the observation time.",
      "source_quote": "until the Commitments have been terminated"
    },
    {
      "name": "all_obligations_paid_in_full",
      "meaning": "True iff the principal of and interest on each Loan, all Fees and all other expenses or amounts payable under any Loan Document have been paid in full at the observation time.",
      "source_quote": "the principal of and interest on each Loan, all Fees and all other expenses or amounts payable under any Loan Document have been paid in full"
    },
    {
      "name": "required_lenders_consent",
      "meaning": "True iff the Required Lenders have consented in writing, at the observation time, to the ratio exceeding .65 to 1.0.",
