{
  "status": "formalized",
  "smt2": "(set-logic QF_LRA)\n; interest_coverage_ratio: Interest Coverage Ratio of Millennium and its Subsidiaries for the period of four consecutive fiscal quarters ending at this observation, expressed as a number X meaning X to 1.00.\n; covenant_in_effect: True iff the Agreement remains in effect, or principal or interest on any Loan, any Fees, any reimbursement obligations in respect of LC Disbursements, or any other expenses or amounts payable under the Agreement are unpaid.\n; required_lenders_consented: True iff the Required Lenders have otherwise consented in writing to the relevant action or non-compliance.\n; period_ends_2001_window: True iff the four-quarter test period ends from June 30, 2001 through December 31, 2001.\n; period_ends_2002: True iff the four-quarter test period ends from January 1, 2002 through December 31, 2002.\n; period_ends_2003: True iff the four-quarter test period ends from January 1, 2003 through December 31, 2003.\n; period_ends_2004_onward: True iff the four-quarter test period ends on or after January 1, 2004.\n(define-fun covenant_holds ((interest_coverage_ratio Real) (covenant_in_effect Bool) (required_lenders_consented Bool) (period_ends_2001_window Bool) (period_ends_2002 Bool) (period_ends_2003 Bool) (period_ends_2004_onward Bool)) Bool\n  (=> (and covenant_in_effect (not required_lenders_consented))\n      (and (=> period_ends_2001_window (>= interest_coverage_ratio 2.25))\n           (=> period_ends_2002 (>= interest_coverage_ratio 2.5))\n           (=> period_ends_2003 (>= interest_coverage_ratio 2.75))\n           (=> period_ends_2004_onward (>= interest_coverage_ratio 3.0)))))",
