      "source_quote": "Permit the Consolidated Leverage Ratio as of the end of any fiscal quarter of the Borrower"
    },
    {
      "name": "consolidated_fccr",
      "meaning": "Consolidated Fixed Charge Coverage Ratio as of the observation date, as a number x meaning x:1.0. Treated as an atomic input because its definition is not supplied.",
      "source_quote": "Permit the Consolidated Fixed Charge Coverage Ratio as of the end of any fiscal quarter of the Borrower"
    },
    {
      "name": "consolidated_tangible_net_worth",
      "meaning": "Consolidated Tangible Net Worth in US dollars as of the observation date.",
      "source_quote": "Permit Consolidated Tangible Net Worth as of the end of any fiscal quarter of the Borrower"
    },
    {
      "name": "net_income_quarterly_sum_losses_floored_at_zero",
      "meaning": "Sum in US dollars, over each full fiscal quarter ending after June 30, 2012 and up to the observation date, of Consolidated Net Income earned in that quarter, with a quarter showing a net loss counted as 0.",
      "source_quote": "50% of the Consolidated Net Income earned each full fiscal quarter ending after June 30, 2012 (with no deduction for net loss in any such fiscal quarter)"
    },
    {
      "name": "equity_issuance_increases",
      "meaning": "Aggregate increases in US dollars in stockholders' equity of the Borrower and its Subsidiaries after the date of the agreement from the issuance and sale of Equity Interests of the Borrower or any Subsidiary, including upon conversion of Borrower debt securities into such Equity Interests, excluding issuances to the Borrower or a Wholly Owned Subsidiary.",
      "source_quote": "100% of the aggregate increases in stockholders' equity of the Borrower and its Subsidiaries after the date hereof by reason of the issuance and sale of Equity Interests of the Borrower or any Subsidiary (other than issuances to the Borrower or a Wholly Owned Subsidiary), including upon any conversion of debt securities of the Borrower into such Equity Interests"
    }
  ],
  "notes": "The three financial covenants in 8.11 are conjoined and apply only at fiscal quarter-ends on or after December 31, 2012. The opening condition that Commitments, Loans or Letters of Credit remain outstanding is a precondition for the whole Article. It is assumed to hold for every supplied observation and is not modeled as a separate input. The thresholds 2.00:1.0 and 1.50:1.0 are encoded as 2.0 and 1.5 on the ratio value. Leverage is capped inclusively, since only a ratio greater than 2.00 is prohibited. Coverage and tangible net worth have inclusive floors, since only a value less than the threshold is prohibited. The tangible net worth floor is 156,600,000 + 0.5 * (sum of quarterly net income with losses counted as zero) + 1.0 * (equity issuance increases). The evaluator must supply the net income sum with losses floored at zero, because the number of quarters is unbounded and cannot be summed in a fixed-arity function. There is no division, so no unresolved-denominator case arises in this formula."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n; is_on_or_after_effective_date: true iff the observation date is on or after the Effective Date.\n; is_fiscal_quarter_end: true iff the observation date is the last day of a fiscal quarter of the Borrower.\n; is_at_or_after_first_full_fiscal_quarter_end: true iff the observation date is on or after the first full fiscal quarter-end date occurring after the Effective Date.\n; lender_has_commitment: true iff any Lender has any Commitment outstanding under the agreement at the observation.\n; obligation_unpaid_or_unsatisfied: true iff any Revolving Loan or other Obligation remains unpaid or unsatisfied, excluding contingent indemnification obligations for which no claim has been made.\n; consolidated_debt: Consolidated Debt of the Borrower as of the observation date (currency units).\n; total_capitalization: Total Capitalization as of the observation date (currency units, same as consolidated_debt).\n(define-fun covenant_holds ((is_on_or_after_effective_date Bool)\n                            (is_fiscal_quarter_end Bool)\n                            (is_at_or_after_first_full_fiscal_quarter_end Bool)\n                            (lender_has_commitment Bool)\n                            (obligation_unpaid_or_unsatisfied Bool)\n                            (consolidated_debt Real)\n                            (total_capitalization Real)) Bool\n  (=> (and is_on_or_after_effective_date\n           (or lender_has_commitment obligation_unpaid_or_unsatisfied)\n           is_fiscal_quarter_end\n           is_at_or_after_first_full_fiscal_quarter_end)\n      (<= (/ consolidated_debt total_capitalization) 0.60)))",
  "symbols": [
    {
      "name": "is_on_or_after_effective_date",
      "meaning": "True iff the observation date is on or after the Effective Date.",
      "source_quote": "From the Effective Date"
    },
    {
      "name": "is_fiscal_quarter_end",
      "meaning": "True iff the observation date is the last day of a fiscal quarter of the Borrower.",
      "source_quote": "As of the last day of each fiscal quarter of the Borrower"
    },
    {
      "name": "is_at_or_after_first_full_fiscal_quarter_end",
      "meaning": "True iff the observation date is on or after the first full fiscal quarter-end date occurring after the Effective Date.",
      "source_quote": "commencing with the first full fiscal quarter-end date occurring after the Effective Date"
    },
    {
      "name": "lender_has_commitment",
      "meaning": "True iff any Lender has any Commitment outstanding under the agreement at the observation.",
      "source_quote": "so long as any Lender shall have any Commitment hereunder"
    },
    {
      "name": "obligation_unpaid_or_unsatisfied",
      "meaning": "True iff any Revolving Loan or other Obligation remains unpaid or unsatisfied, excluding contingent indemnification obligations for which no claim has been made.",
      "source_quote": "any Revolving Loan or other Obligation hereunder (other than any contingent indemnification obligations for which no claim has been made) shall remain unpaid or unsatisfied"
    },
    {
      "name": "consolidated_debt",
      "meaning": "Consolidated Debt as of the observation date (currency units); numerator of the ratio.",
      "source_quote": "the ratio of Consolidated Debt to Total Capitalization"
    },
    {
      "name": "total_capitalization",
      "meaning": "Total Capitalization as of the observation date (currency units); denominator of the ratio.",
      "source_quote": "the ratio of Consolidated Debt to Total Capitalization"
    }
  ],
  "notes": "The covenant applies only when all of the following hold: the Effective Date has passed, a Commitment is outstanding or an Obligation remains unpaid (these two are alternatives), the date is a fiscal quarter-end, and it is at or after the first full fiscal quarter-end following the Effective Date. When it applies, Consolidated Debt / Total Capitalization must be <= 0.60 (not greater than 0.60:1.00). The ratio is computed by division, so a zero Total Capitalization is left to the evaluator to report as unresolved. No positivity assumptions are made. The definitions of Consolidated Debt and Total Capitalization were not supplied, so each is an atomic Real input."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n; commitment_in_effect: True if the Bank's commitment remains in effect at this observation.\n; revolving_note_outstanding_unpaid: True if the Revolving Credit Note remains outstanding and unpaid at this observation.\n; letter_of_credit_outstanding: True if any Letter of Credit remains outstanding (and unpaid) at this observation.\n; other_amount_owing_to_bank: True if any other amount is owing to the Bank under the agreement at this observation.\n; total_consolidated_liabilities: Total liabilities of the Borrower and its Subsidiaries on a consolidated basis at this observation.\n; consolidated_net_worth: Consolidated net worth of the Borrower and its Subsidiaries at this observation, before subtracting officer loans receivable.\n; officer_loans_receivable: Officer loans receivable, subtracted from consolidated net worth in the ratio denominator.\n(define-fun covenant_holds (\n  (commitment_in_effect Bool)\n  (revolving_note_outstanding_unpaid Bool)\n  (letter_of_credit_outstanding Bool)\n  (other_amount_owing_to_bank Bool)\n  (total_consolidated_liabilities Real)\n  (consolidated_net_worth Real)\n  (officer_loans_receivable Real)\n) Bool\n  (=> (or commitment_in_effect\n          revolving_note_outstanding_unpaid\n          letter_of_credit_outstanding\n          other_amount_owing_to_bank)\n      (<= (/ total_consolidated_liabilities\n             (- consolidated_net_worth officer_loans_receivable))\n          1.7)))",
  "symbols": [
    {
      "name": "commitment_in_effect",
      "meaning": "True if the Bank's commitment remains in effect at this observation.",
      "source_quote": "so long as the commitment remains in effect"
    },
    {
      "name": "revolving_note_outstanding_unpaid",
      "meaning": "True if the Revolving Credit Note remains outstanding and unpaid at this observation.",
      "source_quote": "the Revolving Credit Note or any Letter of Credit remains or remain outstanding and unpaid"
    },
    {
      "name": "letter_of_credit_outstanding",
      "meaning": "True if any Letter of Credit remains outstanding (and unpaid) at this observation.",
      "source_quote": "the Revolving Credit Note or any Letter of Credit remains or remain outstanding and unpaid"
    },
    {
      "name": "other_amount_owing_to_bank",
      "meaning": "True if any other amount is owing to the Bank under the agreement at this observation.",
      "source_quote": "any other amount is owing to the Bank hereunder"
    },
    {
      "name": "total_consolidated_liabilities",
      "meaning": "Total liabilities of the Borrower and its Subsidiaries on a consolidated basis at this observation.",
      "source_quote": "total consolidated liabilities"
    },
    {
      "name": "consolidated_net_worth",
      "meaning": "Consolidated net worth of the Borrower and its Subsidiaries at this observation, before subtracting officer loans receivable.",
      "source_quote": "consolidated net worth"
    },
    {
      "name": "officer_loans_receivable",
      "meaning": "Officer loans receivable, subtracted from consolidated net worth in the ratio denominator.",
      "source_quote": "officer loans receivable"
    }
  ],
  "notes": "Pointwise translation of 'at all times'. Applicability is the OR of the four stated conditions (commitment in effect; Revolving Credit Note or Letter of Credit outstanding and unpaid; any other amount owing). Compliance requires liabilities / (net worth - officer loans receivable) <= 1.7, a non-strict bound ('not more than 1.7 to 1.0'). The ratio is kept as a division so that a zero denominator is reported as unresolved by the evaluator, and no positivity of the denominator is assumed. QF_NRA is used because the division by a variable term is nonlinear. The Note and Letter of Credit conditions are split into separate flags to preserve the OR."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n; is_fiscal_quarter_end: true iff the observation date is the end of a fiscal quarter (the measurement date for all three covenants).\n; term_in_effect: true iff the observation date falls during the term of the Agreement.\n; obligations_outstanding: true iff, after the term, there are still any Obligations to Lender.\n; lender_written_consent: true iff Lender has consented in writing to Borrower not complying with these Section 8.3 financial covenants at this observation.\n; total_liabilities: Borrower's Total Liabilities as of the observation date (fiscal quarter end).\n; effective_tangible_net_worth: Borrower's Effective Tangible Net Worth as of the observation date (fiscal quarter end).\n; total_funded_debt: Borrower's Total Funded Debt as of the observation date (fiscal quarter end).\n; ebitda_rolling_four_quarters: Borrower's EBITDA calculated on a rolling four quarter basis ending at the observation date.\n; fixed_charge_coverage_ratio: Borrower's Fixed Charge Coverage Ratio calculated on a rolling four quarter basis ending at the observation date (atomic ratio; no definition supplied).\n(define-fun covenant_holds ((is_fiscal_quarter_end Bool)\n                            (term_in_effect Bool)\n                            (obligations_outstanding Bool)\n                            (lender_written_consent Bool)\n                            (total_liabilities Real)\n                            (effective_tangible_net_worth Real)\n                            (total_funded_debt Real)\n                            (ebitda_rolling_four_quarters Real)\n                            (fixed_charge_coverage_ratio Real)) Bool\n  (=> (and is_fiscal_quarter_end\n           (or term_in_effect obligations_outstanding)\n           (not lender_written_consent))\n      (and (<= (/ total_liabilities effective_tangible_net_worth) 2.0)\n           (<= (/ total_funded_debt ebitda_rolling_four_quarters) 2.0)\n           (>= fixed_charge_coverage_ratio 1.25))))",
