{
  "status": "formalized",
  "smt2": "(set-logic QF_LRA)\n(define-fun covenant_holds (\n  (sum_remains_unpaid Bool) ; true if, at the observation time, any sum remains unpaid under the agreement, in whole or in part\n  (lender_prior_written_consent Bool) ; true if Lender has given prior written consent excusing compliance with the net worth and debt to worth requirements at the observation time\n  (net_worth Real) ; Borrower's net worth in US dollars at the observation time\n  (debt_to_worth_ratio Real) ; Borrower's debt to worth ratio at the observation time, expressed as X in 'X to 1'\n  ) Bool\n  (=> (and sum_remains_unpaid (not lender_prior_written_consent))\n      (and (>= net_worth 25000000.0)\n           (<= debt_to_worth_ratio 3.5))))",
  "symbols": [
    {
      "name": "sum_remains_unpaid",
      "meaning": "True if, at the observation time, any sum remains unpaid under the agreement, in whole or in part.",
      "source_quote": "So long as any sum remains unpaid hereunder, in whole or in part"
    },
    {
      "name": "lender_prior_written_consent",
      "meaning": "True if Lender has given prior written consent excusing compliance with the net worth and debt to worth requirements at the observation time.",
      "source_quote": "except with the prior written consent of Lender"
    },
    {
      "name": "net_worth",
      "meaning": "Borrower's net worth in US dollars at the observation time.",
      "source_quote": "a minimum net worth of $25,000,000"
    },
    {
      "name": "debt_to_worth_ratio",
      "meaning": "Borrower's debt to worth ratio at the observation time, expressed as X in 'X to 1'. It is kept as an atomic input because the source gives no arithmetic definition.",
      "source_quote": "a maximum debt to worth ratio of 3.5 to 1"
    }
  ],
  "notes": "The covenant applies pointwise while a sum remains unpaid and no prior written consent applies. When it applies, both limits must hold: net worth >= 25,000,000 (a minimum, so equality complies) and debt to worth ratio <= 3.5 (a maximum, so equality complies). Both are joined by AND, as the clause says '(1) ... and (2) ...'. The 'at all times' language is checked at each supplied observation. The sentence on Lender's internal determination procedures and Borrower cooperation is procedural, so it is not encoded. The ratio is an atomic input, so the function performs no division."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n; commitments_ended: Commitments have expired or been terminated in whole at this observation.\n; obligations_paid_in_full: principal of and interest on each Loan and all fees payable under the agreement have been paid in full at this observation.\n; consolidated_ebitda_ltm4q: Consolidated EBITDA for the period of four consecutive fiscal quarters ending at this observation.\n; consolidated_interest_expense_ltm4q: Consolidated Interest Expense for the same four-consecutive-fiscal-quarter period.\n(define-fun covenant_holds ((commitments_ended Bool) (obligations_paid_in_full Bool) (consolidated_ebitda_ltm4q Real) (consolidated_interest_expense_ltm4q Real)) Bool\n  (=> (not (and commitments_ended obligations_paid_in_full))\n      (>= (/ consolidated_ebitda_ltm4q consolidated_interest_expense_ltm4q) 4.0)))",
  "symbols": [
    {
      "name": "commitments_ended",
      "meaning": "True if the Commitments have expired or been terminated in whole at this observation.",
      "source_quote": "Until the Commitments have expired or been terminated in whole"
    },
    {
      "name": "obligations_paid_in_full",
      "meaning": "True if the principal of and interest on each Loan and all fees payable under the agreement have been paid in full at this observation.",
      "source_quote": "the principal of and interest on each Loan and all fees payable hereunder have been paid in full"
    },
    {
      "name": "consolidated_ebitda_ltm4q",
      "meaning": "Consolidated EBITDA for the period of four consecutive fiscal quarters ending at this observation.",
      "source_quote": "Consolidated EBITDA"
    },
    {
      "name": "consolidated_interest_expense_ltm4q",
      "meaning": "Consolidated Interest Expense for the same period of four consecutive fiscal quarters.",
      "source_quote": "Consolidated Interest Expense"
