      "source_quote": "the Company shall not have outstanding Index Debt that is investment grade rated by two of Moody's, S&P and Fitch"
    },
    {
      "name": "leverage_ratio",
      "meaning": "The Leverage Ratio at this observation, expressed as a ratio to 1.0.",
      "source_quote": "the Leverage Ratio exceeds"
    },
    {
