{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n; commitments_expired_or_terminated_in_whole: true iff the Commitments have expired or been terminated in whole at the observation time.\n; principal_and_interest_paid_in_full: true iff the principal of and interest on each Loan have been paid in full at the observation time.\n; fees_paid_in_full: true iff all fees payable under the agreement have been paid in full at the observation time.\n; consolidated_total_debt: Consolidated Total Debt of the Borrower at the observation time.\n; consolidated_ebitda_ltm: Consolidated EBITDA for the most recently ended period of four consecutive fiscal quarters as of the observation time.\n(define-fun covenant_holds ((commitments_expired_or_terminated_in_whole Bool) (principal_and_interest_paid_in_full Bool) (fees_paid_in_full Bool) (consolidated_total_debt Real) (consolidated_ebitda_ltm Real)) Bool\n  (=> (not (and commitments_expired_or_terminated_in_whole principal_and_interest_paid_in_full fees_paid_in_full))\n      (<= (/ consolidated_total_debt consolidated_ebitda_ltm) 3.25)))",
  "symbols": [
    {
      "name": "commitments_expired_or_terminated_in_whole",
      "meaning": "True iff the Commitments have expired or been terminated in whole at the observation time.",
      "source_quote": "the Commitments have expired or been terminated in whole"
    },
    {
      "name": "principal_and_interest_paid_in_full",
      "meaning": "True iff the principal of and interest on each Loan have been paid in full at the observation time.",
      "source_quote": "the principal of and interest on each Loan"
    },
    {
      "name": "fees_paid_in_full",
      "meaning": "True iff all fees payable under the agreement have been paid in full at the observation time.",
      "source_quote": "all fees payable hereunder have been paid in full"
    },
    {
      "name": "consolidated_total_debt",
      "meaning": "Consolidated Total Debt of the Borrower at the observation time (the numerator of the ratio).",
      "source_quote": "Consolidated Total Debt at such time"
    },
    {
      "name": "consolidated_ebitda_ltm",
      "meaning": "Consolidated EBITDA for the most recently ended period of four consecutive fiscal quarters as of the observation time (the denominator of the ratio).",
      "source_quote": "Consolidated EBITDA for the most recently ended period of four consecutive fiscal quarters"
    }
  ],
  "notes": "The covenant is in force until the Commitments have expired or been terminated AND principal, interest and fees are all paid in full. It is therefore active whenever not all three of those conditions hold. While active, the ratio Consolidated Total Debt / Consolidated EBITDA must not be greater than 3.25 to 1.0, i.e. it must be <= 3.25 (non-strict). The covenant applies 'at any time', so it is translated pointwise at each observation. A zero EBITDA makes the division undefined, and the evaluator reports that as unresolved. QF_NRA is used because the division is by a variable."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n; covenant_period_active: true at this observation time if the Credit Agreement is in effect and the Loans, with interest, fees and other obligations, have not yet been paid in full and the Commitments have not yet terminated.\n; total_funded_debt: Borrower's Total Funded Debt at the observation time, on a consolidated basis (currency units).\n; capitalization: Borrower's Capitalization at the observation time, on a consolidated basis (currency units), in the same units as total_funded_debt.\n(define-fun covenant_holds ((covenant_period_active Bool) (total_funded_debt Real) (capitalization Real)) Bool\n  (=> covenant_period_active\n      (<= (/ total_funded_debt capitalization) 0.65)))",
  "symbols": [
    {
      "name": "covenant_period_active",
      "meaning": "True at this observation time if the Credit Agreement is in effect and the Loans, with interest, fees and other obligations, have not yet been paid in full and the Commitments have not yet terminated.",
      "source_quote": "so long as this Credit Agreement is in effect and until the Loans made to it, together with interest, fees and other obligations hereunder, have been paid in full and the Commitments hereunder shall have terminated"
    },
    {
      "name": "total_funded_debt",
      "meaning": "Borrower's Total Funded Debt at the observation time, on a consolidated basis (currency units); the numerator of the ratio.",
      "source_quote": "The ratio of (a) Total Funded Debt to (b) Capitalization for the Borrower"
    },
    {
      "name": "capitalization",
      "meaning": "Borrower's Capitalization at the observation time, on a consolidated basis, in the same currency units as total_funded_debt; the denominator of the ratio.",
      "source_quote": "(b) Capitalization for the Borrower shall at all times be less than or equal to .65 to 1.00 (each on a consolidated basis)"
    }
  ],
  "notes": "The ratio is Total Funded Debt divided by Capitalization and must be <= 0.65 (0.65 to 1.00, non-strict). 'At all times' is translated pointwise at each observation. The definitions of Total Funded Debt and Capitalization are not supplied, so each is an atomic Real input. The division is by a variable, so the logic is QF_NRA. A zero Capitalization is reported by the evaluator as unresolved, and no positivity is assumed. The covenant applies only while the agreement is in effect and until the Loans are paid in full and the Commitments terminate, which is the covenant_period_active flag."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n; is_fiscal_quarter_end: true iff the observation is at the end of a Fiscal Quarter.\n; is_on_or_after_march_31_1995_quarter: true iff the Fiscal Quarter just ended is the Fiscal Quarter ending March 31, 1995 or a later Fiscal Quarter.\n; csc_put_test_quarter: true iff the CSC Put is funded and the Fiscal Quarter just ended is either the Fiscal Quarter in which the CSC Put is funded or one of the immediately succeeding 3 Fiscal Quarters.\n; income_available_for_fixed_charges: Income Available for Fixed Charges for the Fiscal Quarter just ended and the immediately preceding 3 Fiscal Quarters (4 quarters in total).\n; consolidated_fixed_charges: Consolidated Fixed Charges for the same 4-Fiscal-Quarter period.\n(define-fun covenant_holds ((is_fiscal_quarter_end Bool) (is_on_or_after_march_31_1995_quarter Bool) (csc_put_test_quarter Bool) (income_available_for_fixed_charges Real) (consolidated_fixed_charges Real)) Bool\n  (=> (and is_fiscal_quarter_end is_on_or_after_march_31_1995_quarter)\n      (ite csc_put_test_quarter\n           (> (/ income_available_for_fixed_charges consolidated_fixed_charges) 2.0)\n           (>= (/ income_available_for_fixed_charges consolidated_fixed_charges) 2.5))))",
  "symbols": [
    {
      "name": "is_fiscal_quarter_end",
      "meaning": "True iff the observation is at the end of a Fiscal Quarter.",
      "source_quote": "At the end of each Fiscal Quarter"
    },
    {
      "name": "is_on_or_after_march_31_1995_quarter",
      "meaning": "True iff the Fiscal Quarter just ended is the Fiscal Quarter ending March 31, 1995 or a later Fiscal Quarter.",
      "source_quote": "commencing with the Fiscal Quarter ending March 31, 1995"
    },
    {
      "name": "csc_put_test_quarter",
      "meaning": "True iff the CSC Put is funded and the Fiscal Quarter just ended is the quarter in which the CSC Put is funded or one of the immediately succeeding 3 Fiscal Quarters.",
      "source_quote": "if the CSC Put is funded, such ratio shall be greater than 2.0 to 1.0 at the end of the Fiscal Quarter in which the CSC Put is funded and at the end of each of the immediately succeeding 3 Fiscal Quarters"
