{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n; accounts_receivable: Holdings' consolidated accounts receivable, including receivables sold or otherwise transferred under Permitted Securitizations permitted by Section 6.01(k), at the observation date (currency units).\n; first_priority_inventory: Holdings' consolidated inventories subject to a first priority perfected security interest in favor of the Collateral Agent under the Guarantee and Collateral Agreement, at the observation date (currency units).\n; inventory_secured_6_02_f: then outstanding amounts secured by a security interest on inventory permitted by Section 6.02(f), at the observation date (currency units); excluded from the inventory term.\n; consolidated_funded_indebtedness: Consolidated Funded Indebtedness at the observation date (currency units); the ratio denominator.\n; is_fiscal_quarter_end: true iff the observation date is the end of a Fiscal Quarter.\n; is_quarter_ending_2005_09_30: true iff the Fiscal Quarter ending at the observation is the quarter ending 9/30/05.\n; is_quarter_ending_2005_12_31: true iff the Fiscal Quarter ending at the observation is the quarter ending 12/31/05.\n; is_quarter_ending_2006_03_31: true iff the Fiscal Quarter ending at the observation is the quarter ending 3/31/06.\n; is_quarter_ending_2006_06_30_or_later: true iff the Fiscal Quarter ending at the observation is the quarter ending 6/30/06 or any later quarter.\n(define-fun covenant_holds (\n  (accounts_receivable Real)\n  (first_priority_inventory Real)\n  (inventory_secured_6_02_f Real)\n  (consolidated_funded_indebtedness Real)\n  (is_fiscal_quarter_end Bool)\n  (is_quarter_ending_2005_09_30 Bool)\n  (is_quarter_ending_2005_12_31 Bool)\n  (is_quarter_ending_2006_03_31 Bool)\n  (is_quarter_ending_2006_06_30_or_later Bool)) Bool\n  (=> is_fiscal_quarter_end\n    (and\n      (=> is_quarter_ending_2005_09_30\n        (>= (/ (- (+ accounts_receivable first_priority_inventory) inventory_secured_6_02_f) consolidated_funded_indebtedness) 1.20))\n      (=> is_quarter_ending_2005_12_31\n        (>= (/ (- (+ accounts_receivable first_priority_inventory) inventory_secured_6_02_f) consolidated_funded_indebtedness) 1.20))\n      (=> is_quarter_ending_2006_03_31\n        (>= (/ (- (+ accounts_receivable first_priority_inventory) inventory_secured_6_02_f) consolidated_funded_indebtedness) 1.20))\n      (=> is_quarter_ending_2006_06_30_or_later\n        (>= (/ (- (+ accounts_receivable first_priority_inventory) inventory_secured_6_02_f) consolidated_funded_indebtedness) 1.25)))))",
  "symbols": [
    {
