      "source_quote": "exclusive of any then outstanding amounts secured by a security interest on inventory permitted by Section 6.02(f)"
    },
    {
      "name": "consolidated_funded_indebtedness",
      "meaning": "Consolidated Funded Indebtedness at the observation date (currency units); the ratio denominator.",
      "source_quote": "Consolidated Funded Indebtedness"
    },
    {
      "name": "is_fiscal_quarter_end",
      "meaning": "True iff the observation date is the end of a Fiscal Quarter.",
      "source_quote": "at the end of any Fiscal Quarter"
    },
    {
      "name": "is_quarter_ending_2005_09_30",
      "meaning": "True iff the Fiscal Quarter ending at the observation is the quarter ending 9/30/05.",
      "source_quote": "9/30/05 1.20:1"
    },
    {
      "name": "is_quarter_ending_2005_12_31",
      "meaning": "True iff the Fiscal Quarter ending at the observation is the quarter ending 12/31/05.",
      "source_quote": "12/31/05 1.20:1"
    },
    {
      "name": "is_quarter_ending_2006_03_31",
      "meaning": "True iff the Fiscal Quarter ending at the observation is the quarter ending 3/31/06.",
      "source_quote": "3/31/06 1.20:1"
    },
    {
