      "source_quote": "the aggregate amount of management fees and similar charges accrued and payable to the Hotel Manager in respect of the Hotels during any fiscal year of AIRCOA"
    },
    {
      "name": "gross_revenues_fy",
      "meaning": "Gross Revenues for the same fiscal year, used as the base for the 4% cap.",
      "source_quote": "4% of Gross Revenues for such fiscal year"
    },
    {
      "name": "in_compliance_with_section_8_10",
      "meaning": "True iff the Borrowers are in compliance with Section 8.10 (minimum Debt Service Coverage Ratio) at the observation time.",
      "source_quote": "when the Borrowers are not in compliance with Section 8.10 hereof (relating to the minimum Debt Service Coverage Ratio)"
    },
    {
      "name": "mgmt_fee_paid_by_operating_partnership_now",
      "meaning": "True iff an Operating Partnership pays any management fee or similar charge to the Hotel Manager at the observation time.",
      "source_quote": "the Operating Partnerships will not pay any management fees or similar charges to the Hotel Manager"
