      "source_quote": "as of the last day of any Test Period ending after the Closing Date"
    },
    {
      "name": "consolidated_net_leverage_ratio",
      "meaning": "Consolidated Net Leverage Ratio as of the last day of the observed Test Period, as a ratio to 1.0 (for example 5.50 means 5.50 to 1.0).",
      "source_quote": "Consolidated Net Leverage Ratio as of the last day of any Test Period ending after the Closing Date to be greater than 5.50 to 1.0"
    }
