{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n; current_assets: Borrower's Current Assets at the observation time, the numerator (a) of the Section 11.3 ratio.\n; current_liabilities: Borrower's Current Liabilities at the observation time, the denominator (b) of the Section 11.3 ratio.\n; obligations_outstanding: true iff the Obligations or any part thereof are outstanding at the observation time.\n; lender_has_commitment: true iff any Lender has any Commitment under the agreement at the observation time.\n; letter_of_credit_outstanding: true iff any Letter of Credit remains outstanding at the observation time.\n(define-fun covenant_holds ((current_assets Real) (current_liabilities Real) (obligations_outstanding Bool) (lender_has_commitment Bool) (letter_of_credit_outstanding Bool)) Bool\n  (=> (or obligations_outstanding lender_has_commitment letter_of_credit_outstanding)\n      (>= (/ current_assets current_liabilities) 1.5)))",
  "symbols": [
    {
      "name": "current_assets",
      "meaning": "Borrower's Current Assets at the observation time, the numerator (a) of the Section 11.3 ratio.",
      "source_quote": "Current Assets"
    },
    {
      "name": "current_liabilities",
      "meaning": "Borrower's Current Liabilities at the observation time, the denominator (b) of the Section 11.3 ratio.",
      "source_quote": "Current Liabilities"
    },
    {
      "name": "obligations_outstanding",
      "meaning": "True iff the Obligations or any part thereof are outstanding at the observation time.",
      "source_quote": "as long as the Obligations or any part thereof are outstanding"
    },
    {
      "name": "lender_has_commitment",
      "meaning": "True iff any Lender has any Commitment under the agreement at the observation time.",
      "source_quote": "any Lender has any Commitment hereunder"
    },
    {
      "name": "letter_of_credit_outstanding",
      "meaning": "True iff any Letter of Credit remains outstanding at the observation time.",
