{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n; funded_debt: Funded Debt outstanding at the end of the fiscal quarter being observed, in dollars.\n; ebitda_four_quarters_before_proviso: EBITDA at the end of the observed fiscal quarter for the period of the four prior fiscal quarters, in dollars, before applying the June 30, 1999 one-time-charge proviso (any such charge is still deducted in this figure).\n; is_fiscal_quarter_end: true iff the observation is at the end of a fiscal quarter.\n; is_on_or_after_june_30_1999_quarter: true iff the observed fiscal quarter is the quarter ended June 30, 1999 or a later fiscal quarter.\n; period_includes_june_30_1999_quarter: true iff the four-fiscal-quarter EBITDA period includes the fiscal quarter ended June 30, 1999.\n(define-fun covenant_holds ((funded_debt Real) ; Funded Debt outstanding at quarter end, dollars\n                            (ebitda_four_quarters_before_proviso Real) ; four-quarter EBITDA before the proviso adjustment, dollars\n                            (is_fiscal_quarter_end Bool) ; observation is a fiscal quarter end\n                            (is_on_or_after_june_30_1999_quarter Bool) ; observed quarter is the quarter ended June 30, 1999 or later\n                            (period_includes_june_30_1999_quarter Bool) ; four-quarter period includes the quarter ended June 30, 1999\n                            ) Bool\n  (=> (and is_fiscal_quarter_end is_on_or_after_june_30_1999_quarter)\n      (<= (/ funded_debt\n             (ite period_includes_june_30_1999_quarter\n                  (+ ebitda_four_quarters_before_proviso 3996000.0)\n                  ebitda_four_quarters_before_proviso))\n          3.75)))",
  "symbols": [
    {
      "name": "funded_debt",
      "meaning": "Funded Debt outstanding at the end of the observed fiscal quarter, in dollars.",
      "source_quote": "Funded Debt outstanding at the end of any of the fiscal quarter"
    },
    {
      "name": "ebitda_four_quarters_before_proviso",
      "meaning": "EBITDA at the end of the observed fiscal quarter for the period of the four prior fiscal quarters, in dollars, before the June 30, 1999 one-time-charge proviso is applied. Any such charge is still deducted in this figure.",
      "source_quote": "EBITDA at the end of such fiscal quarter for the period of the four prior fiscal quarters"
    },
    {
      "name": "is_fiscal_quarter_end",
      "meaning": "True iff the observation is at the end of a fiscal quarter.",
      "source_quote": "at the end of any of the fiscal quarter"
    },
    {
      "name": "is_on_or_after_june_30_1999_quarter",
      "meaning": "True iff the observed fiscal quarter is the quarter ended June 30, 1999 or a later fiscal quarter.",
      "source_quote": "Beginning with the fiscal quarter ended June 30, 1999"
    },
    {
      "name": "period_includes_june_30_1999_quarter",
      "meaning": "True iff the four-fiscal-quarter EBITDA measurement period includes the fiscal quarter ended June 30, 1999, so the proviso's exclusion of the one-time charge applies to that quarter's EBITDA.",
      "source_quote": "EBITDA for the fiscal quarter ended June 30, 1999 shall exclude a one time charge against earnings of $3,996,000"
    }
  ],
  "notes": "The ratio of Funded Debt to EBITDA must not exceed 3.75 to 1.00, so the formula requires ratio <= 3.75. The covenant applies only at fiscal quarter ends, starting with the quarter ended June 30, 1999. The proviso is modeled by adding back $3,996,000 to four-quarter EBITDA whenever the measurement period includes the June 30, 1999 quarter, because that quarter's EBITDA excludes the charge. If EBITDA is zero, division is unresolved under the evaluator policy. QF_NRA is used because the formula divides by a variable."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n; notes_unpaid: true iff any of the Notes remains unpaid at this observation.\n; commitments_in_effect: true iff the Loan Commitments remain in effect at this observation.\n; other_amount_owing: true iff any other amount is owing by Borrower to Administrative Agent or any Bank under this Agreement or any other Loan Document at this observation.\n; combined_ebitda: Combined EBITDA for the twelve-month period ending at this observation (prior twelve-month period).\n; total_outstanding_indebtedness: Total Outstanding Indebtedness as of the end of that twelve-month period.\n; unrestricted_cash: Borrower's unrestricted cash and cash equivalent securities as of the end of that twelve-month period.\n(define-fun covenant_holds ((notes_unpaid Bool) (commitments_in_effect Bool) (other_amount_owing Bool) (combined_ebitda Real) (total_outstanding_indebtedness Real) (unrestricted_cash Real)) Bool\n  (=> (or notes_unpaid commitments_in_effect other_amount_owing)\n      (>= (* 100 (/ combined_ebitda (- total_outstanding_indebtedness unrestricted_cash))) 16)))",
  "symbols": [
    {
      "name": "notes_unpaid",
      "meaning": "True iff any of the Notes remains unpaid at this observation time.",
      "source_quote": "any of the Notes shall remain unpaid"
    },
    {
