    },
    {
      "name": "is_reference_period_end",
      "meaning": "True iff the observation date is the end of a Reference Period.",
      "source_quote": "as of the end of any Reference Period"
    },
    {
      "name": "reference_period_ends_on_or_after_2000_12_30",
