{
  "status": "formalized",
  "smt2": "(set-logic QF_LRA)\n; interest_coverage_ratio: The Borrower's Interest Coverage Ratio as of the observation date, as a plain ratio (e.g. 2.00 for 2.00 : 1.00). Its definition is not supplied, so it is atomic.\n; is_fiscal_quarter_end: True iff the observation date is the last day of a fiscal quarter.\n; is_in_initial_period: True iff the observation date falls in the period December 31, 1997 through December 30, 1998.\n; is_thereafter_period: True iff the observation date is after December 30, 1998 (the 'Thereafter' period).\n; covenant_term_in_effect: True iff the covenant term has not ended, i.e. the Commitments have not terminated, all Letters of Credit have not terminated or expired, and the Loans' principal and interest, the Reimbursement Obligations and all other amounts then due and owing have not been paid in full.\n(define-fun covenant_holds ((interest_coverage_ratio Real) (is_fiscal_quarter_end Bool) (is_in_initial_period Bool) (is_thereafter_period Bool) (covenant_term_in_effect Bool)) Bool\n  (and\n    (=> (and covenant_term_in_effect is_fiscal_quarter_end is_in_initial_period)\n        (>= interest_coverage_ratio 2.0))\n    (=> (and covenant_term_in_effect is_fiscal_quarter_end is_thereafter_period)\n        (>= interest_coverage_ratio 2.5))))",
  "symbols": [
    {
      "name": "interest_coverage_ratio",
      "meaning": "The Borrower's Interest Coverage Ratio as of the observation date, as a plain ratio (2.00 means 2.00 : 1.00). Its definition is not supplied, so it is atomic.",
      "source_quote": "The Borrower will not permit the Interest Coverage Ratio as of the last day of any fiscal quarter"
    },
    {
      "name": "is_fiscal_quarter_end",
      "meaning": "True iff the observation date is the last day of a fiscal quarter.",
      "source_quote": "as of the last day of any fiscal quarter"
    },
    {
      "name": "is_in_initial_period",
      "meaning": "True iff the observation date falls in the period December 31, 1997 through December 30, 1998.",
      "source_quote": "December 31, 1997 through December 30, 1998 2.00 : 1.00"
    },
    {
      "name": "is_thereafter_period",
      "meaning": "True iff the observation date is after December 30, 1998 (the 'Thereafter' period).",
      "source_quote": "Thereafter 2.50 : 1.00"
    },
    {
      "name": "covenant_term_in_effect",
      "meaning": "True iff the covenant term has not ended: the Commitments have not terminated, all Letters of Credit have not terminated or expired, and the Loans' principal and interest, the Reimbursement Obligations and all other amounts then due and owing have not been paid in full.",
      "source_quote": "until the termination of the Commitments, the termination or expiration of all Letters of Credit and the payment in full of all principal and interest with respect to the Loans and all Reimbursement Obligations together with all other amounts then due and owing hereunder"
    }
  ],
  "notes": "'Not less than' is encoded as >=. The initial period (2.00) and the thereafter period (2.50) are separate Boolean inputs, so observations before December 31, 1997 carry no requirement. The ratio is not divided, so no division-by-zero issue arises. Applicability depends on the fiscal-quarter-end flag, the period flags and the covenant-term flag."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_LRA)\n; is_last_day_of_fiscal_period: true iff the observation date is the last day of a Fiscal Period (the date as of which the ratios are determined).\n; consolidated_leverage_ratio: Consolidated Leverage Ratio as determined as of the last day of the Fiscal Period, expressed as X in X:1.00.\n; consolidated_interest_coverage_ratio: Consolidated Interest Coverage Ratio as determined as of the last day of the Fiscal Period, expressed as X in X:1.00.\n(define-fun covenant_holds ((is_last_day_of_fiscal_period Bool) (consolidated_leverage_ratio Real) (consolidated_interest_coverage_ratio Real)) Bool\n  (=> is_last_day_of_fiscal_period\n      (and (<= consolidated_leverage_ratio 3.0)\n           (>= consolidated_interest_coverage_ratio 3.0))))",
