{
  "status": "formalized",
  "smt2": "(set-logic QF_LRA)\n; consolidated_fixed_charge_coverage_ratio: Consolidated Fixed Charge Coverage Ratio of the Borrower for the Test Period ending on the observed fiscal quarter end (ratio value X in X:1.00).\n; is_quarter_in_1_05_schedule: true iff the Test Period ends on the last day of a fiscal quarter listed in the schedule with required ratio 1.05:1.00 (fiscal quarters ended closest to Oct 31, 1999 through Oct 31, 2001).\n; is_quarter_in_1_25_schedule: true iff the Test Period ends on the last day of a fiscal quarter listed in the schedule with required ratio 1.25:1.00 (fiscal quarters ended closest to Jan 31, 2002 through Jul 31, 2004).\n(define-fun covenant_holds ((consolidated_fixed_charge_coverage_ratio Real) (is_quarter_in_1_05_schedule Bool) (is_quarter_in_1_25_schedule Bool)) Bool\n  (and\n    (=> is_quarter_in_1_05_schedule (>= consolidated_fixed_charge_coverage_ratio 1.05))\n    (=> is_quarter_in_1_25_schedule (>= consolidated_fixed_charge_coverage_ratio 1.25))))",
  "symbols": [
    {
      "name": "consolidated_fixed_charge_coverage_ratio",
      "meaning": "Consolidated Fixed Charge Coverage Ratio of the Borrower for the Test Period ending on the observed fiscal quarter end, expressed as X for X:1.00.",
      "source_quote": "Consolidated Fixed Charge Coverage Ratio"
    },
    {
      "name": "is_quarter_in_1_05_schedule",
      "meaning": "True iff the Test Period ends on the last day of a fiscal quarter listed with required ratio 1.05:1.00 (fiscal quarters ended closest to Oct 31, 1999 through Oct 31, 2001).",
      "source_quote": "October 31, 1999 1.05:1.00"
    },
    {
      "name": "is_quarter_in_1_25_schedule",
      "meaning": "True iff the Test Period ends on the last day of a fiscal quarter listed with required ratio 1.25:1.00 (fiscal quarters ended closest to Jan 31, 2002 through Jul 31, 2004).",
      "source_quote": "January 31, 2002 1.25:1.00"
    }
  ],
  "notes": "The ratio must not be less than the scheduled minimum, so the comparison is non-strict (>=). The two schedule flags are mutually exclusive calendar inputs supplied by the evaluator. If neither is true, the covenant is not applicable at that observation and the result is vacuously true. The covenant's temporal scope (from the Effective Date until payment in full and termination) is handled by the pointwise observation convention. The ratio's internal definition is not supplied, so it is kept as an atomic Real."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n; is_first_three_fiscal_quarter_end: true iff the observation date is the end of one of the first three fiscal quarters of a year.\n; is_december_31: true iff the observation date is December 31 of a year.\n; total_liabilities: Total Liabilities (USD) at the observation date.\n; tangible_net_worth: Tangible Net Worth (USD) at the observation date.\n; working_capital: Working Capital (USD) at the observation time.\n; is_fiscal_quarter_end: true iff the observation date is the end of a fiscal quarter.\n; adjusted_ebitda_coverage_ratio: Adjusted EBITDA Coverage Ratio, as a ratio to 1, on a rolling four quarter basis as of the observation date.\n; actual_expenses_ytd: actual expenses for the portion of the fiscal year ended with the quarter ending at the observation date (USD).\n; projected_expenses_ytd: projected expenses in the Annual Budget for the same portion of the fiscal year (USD).\n(define-fun covenant_holds ((is_first_three_fiscal_quarter_end Bool)\n                            (is_december_31 Bool)\n                            (total_liabilities Real)\n                            (tangible_net_worth Real)\n                            (working_capital Real)\n                            (is_fiscal_quarter_end Bool)\n                            (adjusted_ebitda_coverage_ratio Real)\n                            (actual_expenses_ytd Real)\n                            (projected_expenses_ytd Real)) Bool\n  (and\n    ; (a) Total Liabilities to Tangible Net Worth\n    (=> is_first_three_fiscal_quarter_end (<= (/ total_liabilities tangible_net_worth) 1.5))\n    (=> is_december_31 (<= (/ total_liabilities tangible_net_worth) 1.25))\n    ; (b) Working Capital at all times\n    (>= working_capital 11000000.0)\n    ; (c) Adjusted EBITDA Coverage Ratio at each fiscal quarter end\n    (=> is_fiscal_quarter_end (>= adjusted_ebitda_coverage_ratio 2.25))\n    ; (d) Annual Budget Variance: actual must not exceed projected by more than 15%\n    (=> is_fiscal_quarter_end (<= actual_expenses_ytd (* 1.15 projected_expenses_ytd)))))",
  "symbols": [
    {
      "name": "is_first_three_fiscal_quarter_end",
      "meaning": "True iff the observation date is the end of one of the first three fiscal quarters of a year.",
      "source_quote": "as of the end of the first three fiscal quarters of each year"
    },
    {
      "name": "is_december_31",
      "meaning": "True iff the observation date is December 31 of a year.",
      "source_quote": "as of December 31 of each year"
    },
    {
      "name": "total_liabilities",
      "meaning": "Total Liabilities (USD) at the observation date, the numerator of the ratio.",
      "source_quote": "ratio of Total Liabilities to Tangible Net Worth"
    },
    {
      "name": "tangible_net_worth",
      "meaning": "Tangible Net Worth (USD) at the observation date, the denominator of the ratio.",
      "source_quote": "ratio of Total Liabilities to Tangible Net Worth"
    },
    {
      "name": "working_capital",
      "meaning": "Working Capital (USD) at the observation time.",
      "source_quote": "Maintain at all times, Working Capital of not less than $11,000,000"
    },
    {
      "name": "is_fiscal_quarter_end",
      "meaning": "True iff the observation date is the end of a fiscal quarter.",
      "source_quote": "as of end of each fiscal quarter"
    },
    {
      "name": "adjusted_ebitda_coverage_ratio",
      "meaning": "Adjusted EBITDA Coverage Ratio (to 1) on a rolling four quarter basis as of the observation date; atomic because no definition is supplied.",
      "source_quote": "Adjusted EBITDA Coverage Ratio of not less than 2.25 to 1 as of end of each fiscal quarter on a rolling four quarter basis"
    },
    {
      "name": "actual_expenses_ytd",
      "meaning": "Actual expenses (USD) for the portion of the fiscal year ended with the quarter ending at the observation date.",
      "source_quote": "for the portion of the fiscal year ended with such quarter, actual expenses when compared to the Annual Budget"
    },
    {
      "name": "projected_expenses_ytd",
      "meaning": "Projected expenses (USD) in the Annual Budget for the same portion of the fiscal year.",
      "source_quote": "exceed projected expenses for such period by more than 15%"
