      "meaning": "Debt Service Coverage Ratio of the Gaming Enterprise Borrower as of the observation date (atomic Real; no arithmetic definition supplied).",
      "source_quote": "the Debt Service Coverage Ratio of the Gaming Enterprise Borrower to be less than 1.35"
    },
    {
      "name": "is_fiscal_quarter_end",
      "meaning": "True iff the observation date is the last day of a fiscal quarter.",
      "source_quote": "as of the last day of each fiscal quarter"
    },
    {
      "name": "is_quarter_on_or_after_dec_31_2003",
      "meaning": "True iff the fiscal quarter ending on the observation date is the quarter ending December 31, 2003 or a later quarter.",
      "source_quote": "commencing with the quarter ending December 31, 2003"
    },
    {
      "name": "loan_not_paid_in_full",
      "meaning": "True iff the principal of and interest on the Loan have not yet been paid in full at the observation date.",
