  "smt2": "(set-logic QF_NRA)\n; lender_has_commitment: true if any Lender has any Commitment hereunder at the observation time.\n; amount_payable_unpaid: true if any amount payable hereunder or under any Revolving Note or other Loan Document remains unpaid at the observation time.\n; letter_of_credit_liability_outstanding: true if any Letter of Credit Liability remains outstanding at the observation time.\n; consolidated_ffo_trailing_four_quarters: Consolidated Funds From Operations of the Borrower for the four most recently ended consecutive fiscal quarters, taken as a single accounting period.\n; consolidated_cash_interest_expense_trailing_four_quarters: Consolidated Cash Interest Expense of the Borrower for the same four most recently ended consecutive fiscal quarters, taken as a single accounting period.\n(define-fun covenant_holds ((lender_has_commitment Bool) (amount_payable_unpaid Bool) (letter_of_credit_liability_outstanding Bool) (consolidated_ffo_trailing_four_quarters Real) (consolidated_cash_interest_expense_trailing_four_quarters Real)) Bool\n  (=> (or lender_has_commitment amount_payable_unpaid letter_of_credit_liability_outstanding)\n      (>= (/ consolidated_ffo_trailing_four_quarters consolidated_cash_interest_expense_trailing_four_quarters) 2.0)))",
