      "source_quote": "Permit at any time the Consolidated Capitalization Ratio to be greater than 0.55 to 1.00"
    },
    {
      "name": "is_last_day_of_four_quarter_period",
      "meaning": "True iff the observation date is the last day of a Four-Quarter Period.",
      "source_quote": "as at the last day of any Four-Quarter Period"
