{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n; indebtedness_unpaid: true iff any Indebtedness remains unpaid at the observation time.\n; agent_written_consent: true iff the Agent, with the approval of the Required Banks, has consented in writing to otherwise waive this covenant at the observation time.\n; is_fp_ending_sep_30_2000: true iff the fiscal period being tested ends September 30, 2000.\n; is_fp_ending_dec_31_2000: true iff the fiscal period being tested ends December 31, 2000.\n; ebitda_4q: Borrower EBITDA for the four most recently completed fiscal quarters (the default numerator basis).\n; interest_expense_4q: Borrower interest expense for the four most recently completed fiscal quarters (the default denominator basis).\n; ebitda_2q: Borrower EBITDA for the two fiscal quarters ended on September 30, 2000.\n; interest_expense_2q: Borrower interest expense for the two fiscal quarters ended on September 30, 2000.\n; ebitda_3q: Borrower EBITDA for the three fiscal quarters ended on December 31, 2000.\n; interest_expense_3q: Borrower interest expense for the three fiscal quarters ended on December 31, 2000.\n(define-fun covenant_holds ((indebtedness_unpaid Bool)\n                            (agent_written_consent Bool)\n                            (is_fp_ending_sep_30_2000 Bool)\n                            (is_fp_ending_dec_31_2000 Bool)\n                            (ebitda_4q Real)\n                            (interest_expense_4q Real)\n                            (ebitda_2q Real)\n                            (interest_expense_2q Real)\n                            (ebitda_3q Real)\n                            (interest_expense_3q Real)) Bool\n  (=> (and indebtedness_unpaid (not agent_written_consent))\n      (> (/ (ite is_fp_ending_sep_30_2000 (* 2.0 ebitda_2q)\n              (ite is_fp_ending_dec_31_2000 (* (/ 4.0 3.0) ebitda_3q) ebitda_4q))\n            (ite is_fp_ending_sep_30_2000 (* 2.0 interest_expense_2q)\n              (ite is_fp_ending_dec_31_2000 (* (/ 4.0 3.0) interest_expense_3q) interest_expense_4q)))\n         3.5)))",
