      "meaning": "True iff the observation date is the last day of a fiscal quarter of the Company. It is also the end date of the four-consecutive-fiscal-quarter period used for the ratio tests.",
      "source_quote": "as of the last day of any fiscal quarter of the Company"
    },
    {
      "name": "consolidated_total_debt",
      "meaning": "Consolidated Total Debt as of the observation date, the last day of the fiscal quarter.",
      "source_quote": "Consolidated Total Debt as of the last day of any fiscal quarter of the Company"
    },
    {
