{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n; commitment_or_note_outstanding: true if, at this observation, any Bank has any Commitment under the agreement, or any amount payable under any Note remains unpaid.\n; required_banks_written_consent: true if the Required Banks have consented in writing to non-compliance with Section 5.03 at this observation.\n; is_fiscal_quarter_end: true if this observation is at the end of a Fiscal Quarter.\n; is_on_or_after_sept_30_1997_quarter: true if this observation falls in the Fiscal Quarter ending September 30, 1997 or any later Fiscal Quarter.\n; consolidated_funded_debt: Consolidated Funded Debt of the Borrower at this observation (numerator of the ratio, as defined in the agreement).\n; consolidated_total_capitalization: Consolidated Total Capitalization of the Borrower at this observation (denominator of the ratio, as defined in the agreement).\n(define-fun covenant_holds (\n    (commitment_or_note_outstanding Bool)\n    (required_banks_written_consent Bool)\n    (is_fiscal_quarter_end Bool)\n    (is_on_or_after_sept_30_1997_quarter Bool)\n    (consolidated_funded_debt Real)\n    (consolidated_total_capitalization Real)) Bool\n  (=> (and commitment_or_note_outstanding\n           (not required_banks_written_consent)\n           is_fiscal_quarter_end\n           is_on_or_after_sept_30_1997_quarter)\n      (<= (/ consolidated_funded_debt consolidated_total_capitalization) 0.70)))",
  "symbols": [
    {
      "name": "commitment_or_note_outstanding",
      "meaning": "True if, at this observation, any Bank has any Commitment under the agreement, or any amount payable under any Note remains unpaid.",
      "source_quote": "so long as any Bank has any Commitment hereunder or any amount payable under any Note remains unpaid"
    },
    {
      "name": "required_banks_written_consent",
      "meaning": "True if the Required Banks have consented in writing to non-compliance with Section 5.03 at this observation.",
      "source_quote": "unless the Required Banks consent in writing"
    },
    {
      "name": "is_fiscal_quarter_end",
      "meaning": "True if this observation is at the end of a Fiscal Quarter.",
      "source_quote": "At the end of each Fiscal Quarter"
    },
    {
      "name": "is_on_or_after_sept_30_1997_quarter",
      "meaning": "True if this observation falls in the Fiscal Quarter ending September 30, 1997 or any later Fiscal Quarter.",
      "source_quote": "commencing with the Fiscal Quarter ending September 30, 1997"
    },
    {
      "name": "consolidated_funded_debt",
      "meaning": "Consolidated Funded Debt of the Borrower at this observation (numerator of the ratio, as defined in the agreement).",
      "source_quote": "Consolidated Funded Debt"
    },
    {
      "name": "consolidated_total_capitalization",
      "meaning": "Consolidated Total Capitalization of the Borrower at this observation (denominator of the ratio, as defined in the agreement).",
      "source_quote": "Consolidated Total Capitalization"
    }
  ],
  "notes": "The covenant applies only when the Commitment/Note condition holds, no written Required Banks consent exists, the observation is at a Fiscal Quarter end, and the quarter is on or after the one ending September 30, 1997. In that case the ratio of Consolidated Funded Debt to Consolidated Total Capitalization must be <= 0.70 (.70 to 1.00, so the limit is not strict). The ratio is computed by division, so a zero capitalization is reported by the evaluator as unresolved. The definitions of Consolidated Funded Debt and Consolidated Total Capitalization were not supplied, so both are atomic Real inputs. QF_NRA is used because the division has a variable denominator. 'At any time' is evaluated pointwise at the supplied quarter-end observations."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_LRA)\n; lender_has_commitment: true if any Lender has any Commitment under the agreement at the observation time.\n; loan_or_obligation_unpaid: true if any Loan or other Obligation under the agreement remains unpaid or unsatisfied at the observation time.\n; uncollateralized_lc_outstanding: true if any Letter of Credit that is not Cash Collateralized remains outstanding at the observation time.\n; is_fiscal_quarter_end: true if the observation date is the end of a fiscal quarter of the Borrower.\n; indebtedness: Indebtedness of the Borrower and its Subsidiaries on a consolidated basis as of the observation date (currency units).\n; stockholders_equity: Stockholders' Equity of the Borrower and its Subsidiaries on a consolidated basis as of the observation date (same currency units as indebtedness).\n(define-fun covenant_holds ((lender_has_commitment Bool) (loan_or_obligation_unpaid Bool) (uncollateralized_lc_outstanding Bool) (is_fiscal_quarter_end Bool) (indebtedness Real) (stockholders_equity Real)) Bool\n  (=> (and (or lender_has_commitment loan_or_obligation_unpaid uncollateralized_lc_outstanding) is_fiscal_quarter_end)\n      (<= (/ indebtedness (+ indebtedness stockholders_equity)) 0.65)))",
  "symbols": [
    {
      "name": "lender_has_commitment",
      "meaning": "True if any Lender has any Commitment under the agreement at the observation time (one of the alternative conditions keeping the covenant in force).",
      "source_quote": "any Lender shall have any Commitment hereunder"
    },
    {
      "name": "loan_or_obligation_unpaid",
      "meaning": "True if any Loan or other Obligation under the agreement remains unpaid or unsatisfied at the observation time (one of the alternative conditions keeping the covenant in force).",
      "source_quote": "any Loan or other Obligation hereunder shall remain unpaid or unsatisfied"
    },
    {
      "name": "uncollateralized_lc_outstanding",
      "meaning": "True if any Letter of Credit that is not Cash Collateralized remains outstanding at the observation time (one of the alternative conditions keeping the covenant in force).",
      "source_quote": "any Letter of Credit that is not Cash Collateralized shall remain outstanding"
    },
    {
      "name": "is_fiscal_quarter_end",
      "meaning": "True if the observation date is the end of a fiscal quarter of the Borrower.",
      "source_quote": "as of the end of any fiscal quarter of the Borrower"
    },
    {
      "name": "indebtedness",
      "meaning": "Indebtedness of the Borrower and its Subsidiaries on a consolidated basis as of the observation date, in currency units (numerator of the ratio, and part of the denominator sum).",
      "source_quote": "Indebtedness"
    },
    {
      "name": "stockholders_equity",
      "meaning": "Stockholders' Equity of the Borrower and its Subsidiaries on a consolidated basis as of the observation date, in the same currency units as indebtedness (part of the denominator sum).",
      "source_quote": "Stockholders' Equity"
    }
  ],
  "notes": "The covenant applies only while at least one of the three 'so long as' conditions holds (OR) and only as of a fiscal quarter end (AND). The ratio is Indebtedness / (Indebtedness + Stockholders' Equity), and the cap is 65.0% = 0.65, non-strict (<=) because the text says 'to exceed 65.0%'. If the denominator is zero, the evaluator reports the result as unresolved. No positivity or other domain assumptions are added."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n; covenant_in_effect: true when the observation is on or after the Effective Date and the Agreement is still in effect, i.e. the Commitments have not terminated or the Loans, interest, Fees and other Obligations are not yet paid in full.\n; adjusted_operating_income: Adjusted Operating Income of Holdings for the Test Period being tested at this observation.\n; consolidated_cash_interest_expense: Consolidated Cash Interest Expense for the same Test Period.\n(define-fun covenant_holds ((covenant_in_effect Bool) (adjusted_operating_income Real) (consolidated_cash_interest_expense Real)) Bool\n  (=> covenant_in_effect\n      (>= (/ adjusted_operating_income consolidated_cash_interest_expense) 3.0)))",
  "symbols": [
    {
      "name": "covenant_in_effect",
      "meaning": "True when the observation is on or after the Effective Date and the Agreement is still in effect, i.e. the Commitments have not terminated or the Loans, interest, Fees and other Obligations are not yet paid in full.",
      "source_quote": "on the Effective Date and thereafter, for so long as this Agreement is in effect and until the Commitments have terminated and the Loans, together with interest, Fees and all other Obligations incurred hereunder, are paid in full"
    },
    {
      "name": "adjusted_operating_income",
      "meaning": "Adjusted Operating Income for the Test Period being tested at this observation (numerator of the ratio).",
      "source_quote": "the ratio of (i) Adjusted Operating Income"
    },
    {
      "name": "consolidated_cash_interest_expense",
      "meaning": "Consolidated Cash Interest Expense for the same Test Period (denominator of the ratio).",
      "source_quote": "(ii) Consolidated Cash Interest Expense for any Test Period"
    }
  ],
  "notes": "The ratio is Adjusted Operating Income divided by Consolidated Cash Interest Expense, and the covenant prohibits it from being less than 3.00 to 1.00, so compliance is ratio >= 3.0 (non-strict). The division by a variable requires QF_NRA. A zero denominator is left to the evaluator to report as unresolved. Test Period, Adjusted Operating Income and Consolidated Cash Interest Expense are not defined in the supplied text, so they are atomic inputs, with each observation supplying values for the Test Period it tests. The 'any Test Period' requirement is handled by the evaluator conjoining results over all observed Test Periods. The covenant_in_effect flag captures the stated duration of the covenant."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_LRA)\n; adjusted_funded_debt_ratio: Borrower's Adjusted Funded Debt Ratio determined as of the observation date, expressed as the first number of an 'X to 1.00' ratio (e.g. 4.25 means 4.25 to 1.00).\n; is_fiscal_quarter_end: true iff the observation date is the last day of one of the Borrower's fiscal quarters.\n; is_on_or_after_2002_09_30: true iff the observation date is on or after September 30, 2002 (the first test date).\n; is_through_2003_03_31: true iff the observation date falls in a fiscal quarter ending on or before March 31, 2003.\n; is_before_2004_03_31_quarter: true iff the observation date is before the fiscal quarter ending March 31, 2004 (i.e. that quarter-end itself is not before it).\n(define-fun covenant_holds ((adjusted_funded_debt_ratio Real) (is_fiscal_quarter_end Bool) (is_on_or_after_2002_09_30 Bool) (is_through_2003_03_31 Bool) (is_before_2004_03_31_quarter Bool)) Bool\n  (=> (and is_fiscal_quarter_end is_on_or_after_2002_09_30)\n      (ite is_through_2003_03_31\n           (<= adjusted_funded_debt_ratio 4.25)\n           (ite is_before_2004_03_31_quarter\n                (<= adjusted_funded_debt_ratio 4.0)\n                (<= adjusted_funded_debt_ratio 3.5)))))",
  "symbols": [
    {
      "name": "adjusted_funded_debt_ratio",
      "meaning": "Borrower's Adjusted Funded Debt Ratio determined as of the observation date, expressed as the first number of an 'X to 1.00' ratio.",
      "source_quote": "Adjusted Funded Debt Ratio"
    },
    {
      "name": "is_fiscal_quarter_end",
      "meaning": "True iff the observation date is the last day of one of the Borrower's fiscal quarters.",
      "source_quote": "determined as of the last day of each of the Borrower's fiscal quarters"
    },
    {
      "name": "is_on_or_after_2002_09_30",
      "meaning": "True iff the observation date is on or after September 30, 2002, the first test date.",
      "source_quote": "commencing September 30, 2002"
    },
    {
      "name": "is_through_2003_03_31",
      "meaning": "True iff the observation date falls in a fiscal quarter ending on or before March 31, 2003.",
      "source_quote": "through the fiscal quarter ending March 31, 2003"
    },
    {
      "name": "is_before_2004_03_31_quarter",
      "meaning": "True iff the observation date is before the fiscal quarter ending March 31, 2004; the March 31, 2004 quarter-end itself is not before it.",
      "source_quote": "until the fiscal quarter ending March 31, 2004"
    }
  ],
  "notes": "Pointwise test at fiscal quarter-ends from September 30, 2002. The limit is 4.25 through the quarter ending March 31, 2003, then 4.00 for the following quarters until the quarter ending March 31, 2004, then 3.50. 'Through' is read as inclusive and 'until' as exclusive, so the March 31, 2004 quarter-end falls under the 3.50 limit; the source wording is ambiguous on this point. The ratio is an atomic Real because its definition is not supplied. The consent-of-Requisite-Lenders exception and the 'so long as' duration are not modeled, since no input for them was specified."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_LRA)\n; current_ratio: Borrowers' consolidated Current Ratio at the observation (as a ratio X to 1).\n; leverage_ratio: Borrowers' consolidated Leverage Ratio at the observation (as a ratio X to 1).\n; fixed_charges_coverage_ratio: Borrowers' consolidated Fixed Charges Coverage Ratio (X to 1) over the rolling twelve calendar month period ending at the observation.\n; is_jun30_or_sep30_quarter_end: true iff the observation is for a calendar quarter ending June 30 or September 30.\n; is_dec31_or_mar31_quarter_end: true iff the observation is for a calendar quarter ending December 31 or March 31.\n; is_quarterly_fccr_test_date: true iff the observation is a quarterly test date for the Fixed Charges Coverage Ratio covenant.\n(define-fun covenant_holds ((current_ratio Real) (leverage_ratio Real) (fixed_charges_coverage_ratio Real) (is_jun30_or_sep30_quarter_end Bool) (is_dec31_or_mar31_quarter_end Bool) (is_quarterly_fccr_test_date Bool)) Bool\n  (and\n    (=> is_jun30_or_sep30_quarter_end (>= current_ratio 1.15))\n    (=> is_dec31_or_mar31_quarter_end (>= current_ratio 1.10))\n    (=> is_jun30_or_sep30_quarter_end (<= leverage_ratio 4.00))\n    (=> is_dec31_or_mar31_quarter_end (<= leverage_ratio 5.0))\n    (=> is_quarterly_fccr_test_date (>= fixed_charges_coverage_ratio 1.35))))",
  "symbols": [
    {
      "name": "current_ratio",
      "meaning": "Borrowers' consolidated Current Ratio at the observation, expressed as X in 'X to 1'. Atomic input because no arithmetic definition is supplied.",
      "source_quote": "Current Ratio of at least"
    },
    {
      "name": "leverage_ratio",
      "meaning": "Borrowers' consolidated Leverage Ratio at the observation, expressed as X in 'X to 1'. Atomic input because no arithmetic definition is supplied.",
      "source_quote": "Leverage Ratio of not more than"
    },
    {
      "name": "fixed_charges_coverage_ratio",
      "meaning": "Borrowers' consolidated Fixed Charges Coverage Ratio, expressed as X in 'X to 1', over the rolling twelve calendar month period ending at the observation. Atomic input because no arithmetic definition is supplied.",
      "source_quote": "Fixed Charges Coverage Ratio of at least 1.35 to 1, tested quarterly on the basis of a rolling period of twelve (12) calendar months"
    },
    {
      "name": "is_jun30_or_sep30_quarter_end",
      "meaning": "True iff the observation is for a calendar quarter ending June 30 or September 30 of a year.",
      "source_quote": "for the calendar quarters ending June 30 and September 30 of each year"
    },
    {
      "name": "is_dec31_or_mar31_quarter_end",
      "meaning": "True iff the observation is for a calendar quarter ending December 31 or March 31 of a year.",
      "source_quote": "for the calendar quarters ending December 31 and March 31 of each year"
    },
    {
      "name": "is_quarterly_fccr_test_date",
      "meaning": "True iff the observation is a quarterly test date for the Fixed Charges Coverage Ratio covenant.",
      "source_quote": "tested quarterly"
    }
  ],
  "notes": "Each of the three financial covenants is applied pointwise and conjoined. The Current Ratio and Leverage Ratio thresholds depend on the quarter-end flags: 1.15 and 4.00 for June 30 and September 30 quarters, 1.10 and 5.0 for December 31 and March 31 quarters. Minimums use >= and the maximum uses <=, matching 'at least' and 'not more than'. The Fixed Charges Coverage Ratio minimum of 1.35 applies on quarterly test dates, with the rolling twelve-month basis carried in the input's meaning. The ratios are atomic inputs because the source supplies no definitions, so the formula has no division. The 'consolidated basis' requirement is carried in the input meanings. The general 'so long as this Agreement is in effect' preamble is treated as the observation scope."
