    },
    {
      "name": "is_period_end_dec2013_to_sep2014",
      "meaning": "True iff the Testing Period ends December 31, 2013 through September 30, 2014 (maximum ratio 5.50 to 1.00).",
      "source_quote": "December 31, 2013 through September 30, 2014 5.50 to 1.00"
    },
    {
      "name": "is_period_end_dec2014_to_sep2015",
      "meaning": "True iff the Testing Period ends December 31, 2014 through September 30, 2015 (maximum ratio 5.25 to 1.00).",
      "source_quote": "December 31, 2014 through September 30, 2015 5.25 to 1.00"
