    {
      "name": "is_period_end_dec2015_to_sep2016",
      "meaning": "True iff the Testing Period ends December 31, 2015 through September 30, 2016 (maximum ratio 5.00 to 1.00).",
      "source_quote": "December 31, 2015 through September 30, 2016 5.00 to 1.00"
