{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n; credit_available: true if credit is available under the Agreement at the observation time.\n; bank_repaid_in_full: true if the Bank has been repaid in full at the observation time.\n; current_liabilities: Borrower's current liabilities at the observation time (currency units).\n; long_term_liabilities: Borrower's long term liabilities at the observation time (currency units).\n; gross_assets_ex_intangibles: gross book value of the Borrower's assets at the observation time, excluding goodwill, patents, trademarks, trade names, organization expense, treasury stock, unamortized debt discount and expense, deferred research and development costs, deferred marketing expenses, and other like intangibles (currency units).\n(define-fun covenant_holds ((credit_available Bool) (bank_repaid_in_full Bool) (current_liabilities Real) (long_term_liabilities Real) (gross_assets_ex_intangibles Real)) Bool\n  (=> (or credit_available (not bank_repaid_in_full))\n      (<= (/ (+ current_liabilities long_term_liabilities)\n             (- gross_assets_ex_intangibles (+ current_liabilities long_term_liabilities)))\n          0.5)))",
  "symbols": [
    {
      "name": "credit_available",
      "meaning": "True if credit is available under the Agreement at the observation time.",
      "source_quote": "so long as credit is available under this Agreement"
    },
    {
      "name": "bank_repaid_in_full",
      "meaning": "True if the Bank has been repaid in full at the observation time.",
      "source_quote": "until the Bank is repaid in full"
    },
    {
      "name": "current_liabilities",
      "meaning": "Borrower's current liabilities at the observation time, in currency units. It is one component of total liabilities.",
      "source_quote": "current liabilities plus long term liabilities"
    },
    {
      "name": "long_term_liabilities",
      "meaning": "Borrower's long term liabilities at the observation time, in currency units. It is one component of total liabilities.",
      "source_quote": "current liabilities plus long term liabilities"
    },
    {
      "name": "gross_assets_ex_intangibles",
      "meaning": "Gross book value of the Borrower's assets at the observation time, in currency units, excluding goodwill, patents, trademarks, trade names, organization expense, treasury stock, unamortized debt discount and expense, deferred research and development costs, deferred marketing expenses, and other like intangibles. Total liabilities are subtracted in the formula to give tangible net worth.",
      "source_quote": "the gross book value of the Borrower's assets (excluding goodwill, patents, trademarks, trade names, organization expense, treasury stock, unamortized debt discount and expense, deferred research and development costs, deferred marketing expenses, and other like intangibles)"
    }
  ],
  "notes": "Total liabilities = current_liabilities + long_term_liabilities. Tangible net worth = gross_assets_ex_intangibles - total liabilities. The covenant requires total liabilities / tangible net worth <= 0.50 (0.50:1.0). The ratio is kept as a division, not cross-multiplied, so a negative or zero tangible net worth is not silently treated as compliant. Zero tangible net worth is reported by the evaluator as unresolved. The covenant applies while credit is available or until the Bank is repaid in full; this is modeled as (credit_available OR NOT bank_repaid_in_full). This reading of the source's wording is an interpretation. The 'including but not limited to accrued and deferred income taxes, and any reserves against assets' language is assumed to be reflected in the supplied liability and asset inputs."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_LRA)\n; commitments_or_obligations_outstanding: true if the observation falls before the Commitments have expired or terminated and the principal of and interest on each Loan and all fees and other amounts payable have been paid in full (the covenant is in force).\n; is_four_quarter_period_end: true if the observation is for a period of four consecutive fiscal quarters of the Company, ending at this observation.\n; period_ends_after_agreement_date: true if that four-quarter period ends after the date of this Agreement.\n; period_ends_on_or_after_2014_09_30: true if that four-quarter period ends on or after September 30, 2014, the first tested period.\n; consolidated_ebitda: Consolidated EBITDA of the Company for the four-quarter period (currency units).\n; consolidated_interest_expense: Consolidated Interest Expense of the Company for the same four-quarter period (currency units).\n(define-fun covenant_holds ((commitments_or_obligations_outstanding Bool)\n                            (is_four_quarter_period_end Bool)\n                            (period_ends_after_agreement_date Bool)\n                            (period_ends_on_or_after_2014_09_30 Bool)\n                            (consolidated_ebitda Real)\n                            (consolidated_interest_expense Real)) Bool\n  (=> (and commitments_or_obligations_outstanding\n           is_four_quarter_period_end\n           period_ends_after_agreement_date\n           period_ends_on_or_after_2014_09_30)\n      (>= (/ consolidated_ebitda consolidated_interest_expense) 3.0)))",
