{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n; is_fiscal_quarter_end: true iff the observation date is the end of a Borrower fiscal quarter.\n; loan_outstanding: true iff any Loan is outstanding at the observation time.\n; unpaid_reimbursement_obligation_outstanding: true iff any Unpaid Reimbursement Obligation is outstanding at the observation time.\n; letter_of_credit_outstanding: true iff any Letter of Credit is outstanding at the observation time.\n; note_outstanding: true iff any Note is outstanding at the observation time.\n; bank_has_obligation_to_lend_or_issue: true iff the Bank has any obligation to make any Loans or to issue, extend or renew any Letters of Credit at the observation time.\n; ebitda_four_quarters: EBITDA for the period of four consecutive fiscal quarters ended on the observation date.\n; consolidated_total_interest_expense_four_quarters: Consolidated Total Interest Expense for that same four-quarter period.\n(define-fun covenant_holds (\n  (is_fiscal_quarter_end Bool)\n  (loan_outstanding Bool)\n  (unpaid_reimbursement_obligation_outstanding Bool)\n  (letter_of_credit_outstanding Bool)\n  (note_outstanding Bool)\n  (bank_has_obligation_to_lend_or_issue Bool)\n  (ebitda_four_quarters Real)\n  (consolidated_total_interest_expense_four_quarters Real)\n  ) Bool\n  (=> (and is_fiscal_quarter_end\n           (or loan_outstanding\n               unpaid_reimbursement_obligation_outstanding\n               letter_of_credit_outstanding\n               note_outstanding\n               bank_has_obligation_to_lend_or_issue))\n      (>= (/ ebitda_four_quarters consolidated_total_interest_expense_four_quarters) 3.0)))",
  "symbols": [
    {
      "name": "is_fiscal_quarter_end",
      "meaning": "True iff the observation date is the end of a Borrower fiscal quarter.",
      "source_quote": "as of the end of any fiscal quarter"
    },
    {
      "name": "loan_outstanding",
      "meaning": "True iff any Loan is outstanding at the observation time.",
      "source_quote": "any Loan"
    },
    {
      "name": "unpaid_reimbursement_obligation_outstanding",
      "meaning": "True iff any Unpaid Reimbursement Obligation is outstanding at the observation time.",
      "source_quote": "Unpaid Reimbursement Obligation"
    },
    {
      "name": "letter_of_credit_outstanding",
      "meaning": "True iff any Letter of Credit is outstanding at the observation time.",
      "source_quote": "Letter of Credit"
    },
    {
      "name": "note_outstanding",
      "meaning": "True iff any Note is outstanding at the observation time.",
      "source_quote": "Note is outstanding"
    },
    {
      "name": "bank_has_obligation_to_lend_or_issue",
      "meaning": "True iff the Bank has any obligation to make any Loans or to issue, extend or renew any Letters of Credit at the observation time.",
      "source_quote": "the Bank has any obligation to make any Loans or to issue, extend or renew any Letters of Credit"
    },
    {
      "name": "ebitda_four_quarters",
      "meaning": "EBITDA for the period of four consecutive fiscal quarters ended on the observation date.",
      "source_quote": "EBITDA for any period of four consecutive fiscal quarters ended on such date"
    },
    {
      "name": "consolidated_total_interest_expense_four_quarters",
      "meaning": "Consolidated Total Interest Expense for the same four-quarter period.",
      "source_quote": "Consolidated Total Interest Expense for such period"
    }
  ],
  "notes": "The ratio EBITDA / Consolidated Total Interest Expense must not be less than 3.00, so the formula requires >= 3.0 at fiscal quarter ends. The covenant applies only while a Loan, Unpaid Reimbursement Obligation, Letter of Credit or Note is outstanding, or the Bank has a lending or issuance obligation. These conditions are kept as separate Boolean inputs combined with OR. 'At any time' is read pointwise at each supplied observation. A zero interest expense makes the division undefined, which the evaluator reports as unresolved. QF_NRA is used because the division is by a variable."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n; consolidated_current_assets: Consolidated Current Assets of the Borrower and its consolidated Subsidiaries at the observation time (numerator of the Current Ratio).\n; consolidated_current_liabilities: Consolidated Current Liabilities at the observation time (denominator of the Current Ratio).\n; in_issuance_through_fy1999_period: true iff the observation time falls in the period from the Date of Issuance (of the Letter of Credit) through Fiscal Year 1999, so the 1.45 : 1.00 minimum applies.\n; in_thereafter_period: true iff the observation time falls after Fiscal Year 1999, so the 1.50 : 1.00 minimum applies.\n(define-fun covenant_holds ((consolidated_current_assets Real) (consolidated_current_liabilities Real) (in_issuance_through_fy1999_period Bool) (in_thereafter_period Bool)) Bool\n  (and\n    (=> in_issuance_through_fy1999_period\n        (not (< (/ consolidated_current_assets consolidated_current_liabilities) 1.45)))\n    (=> in_thereafter_period\n        (not (< (/ consolidated_current_assets consolidated_current_liabilities) 1.5)))))",
  "symbols": [
    {
      "name": "consolidated_current_assets",
      "meaning": "Consolidated Current Assets at the observation time; numerator of the Current Ratio.",
      "source_quote": "ratio of Consolidated Current Assets to Consolidated Current Liabilities"
    },
    {
      "name": "consolidated_current_liabilities",
      "meaning": "Consolidated Current Liabilities at the observation time; denominator of the Current Ratio.",
      "source_quote": "ratio of Consolidated Current Assets to Consolidated Current Liabilities"
    },
    {
      "name": "in_issuance_through_fy1999_period",
      "meaning": "True iff the observation time is in the period from the Date of Issuance through Fiscal Year 1999, where the 1.45 : 1.00 minimum applies.",
      "source_quote": "Date of Issuance 1.45 : 1.00 Through Fiscal Year 1999"
    },
    {
      "name": "in_thereafter_period",
      "meaning": "True iff the observation time is after Fiscal Year 1999, where the 1.50 : 1.00 minimum applies.",
      "source_quote": "Thereafter 1.50 : 1.00"
    }
  ],
  "notes": "The covenant forbids permitting the ratio to be less than the minimum, so compliance is not (ratio < minimum), i.e. ratio >= minimum. The minimum is 1.45 from the Date of Issuance through Fiscal Year 1999 and 1.50 thereafter. The ratio is the stated quotient of current assets to current liabilities. Division by zero is left to the evaluator to report as unresolved. QF_NRA is used because the division is by a variable. The period flags are calendar inputs supplied by the evaluator. The 'until obligations are paid' and 'unless the Bank consents' lead-in is not modeled, since no input for it is needed under the pointwise convention and the observations supplied are assumed to fall within the covenant's life."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_LRA)\n; fixed_charge_coverage_ratio: Borrowers' Fixed Charge Coverage Ratio as of the last day of the calendar month being observed, as a ratio X in X:1 (for example 1.10 means 1.10:1). It is an atomic input because no arithmetic definition is supplied.\n; is_month_end_after_closing_date: true iff the observation date is the last day of a calendar month that ends after the Closing Date.\n; month_ends_on_or_before_2007_11_30: true iff the calendar month ends on or prior to November 30, 2007. When false, the month ends thereafter.\n(define-fun covenant_holds ((fixed_charge_coverage_ratio Real) (is_month_end_after_closing_date Bool) (month_ends_on_or_before_2007_11_30 Bool)) Bool\n  (=> is_month_end_after_closing_date\n      (ite month_ends_on_or_before_2007_11_30\n           (>= fixed_charge_coverage_ratio 1.10)\n           (>= fixed_charge_coverage_ratio 1.20))))",
  "symbols": [
    {
      "name": "fixed_charge_coverage_ratio",
      "meaning": "Borrowers' Fixed Charge Coverage Ratio as of the last day of the calendar month being observed, expressed as X for X:1 (1.10 means 1.10:1). It is an atomic input because the source supplies no arithmetic definition.",
      "source_quote": "Fixed Charge Coverage Ratio"
    },
    {
      "name": "is_month_end_after_closing_date",
      "meaning": "True iff the observation date is the last day of a calendar month that ends after the Closing Date. The covenant applies only at such observations.",
      "source_quote": "as of the last day of each calendar month ending after the Closing Date"
    },
    {
      "name": "month_ends_on_or_before_2007_11_30",
      "meaning": "True iff the calendar month being observed ends on or prior to November 30, 2007, so the 1.10:1 minimum applies. When false, the month ends thereafter and the 1.20:1 minimum applies.",
      "source_quote": "on or prior to November 30, 2007"
    }
  ],
  "notes": "The 'not less than' wording is encoded as >=. The 1.10:1 and 1.20:1 thresholds are chosen by the month-end date flag, and both apply only when the month ends after the Closing Date. The introductory phrase 'until payment in full of the Obligations and termination of this Agreement' is a duration clause. It is handled by the evaluator supplying observations only while the agreement is in effect, so it needs no extra input. There is no division in the formula."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_LRA)\n; is_fiscal_month_end: true iff the observation date is a fiscal month end.\n; in_financial_covenant_period: true iff the observation date falls within a Financial Covenant Period (a defined term, supplied by the evaluator).\n; is_month_end_preceding_period_start: true iff the observation date is the end of the fiscal month immediately preceding the date on which a Financial Covenant Period first begins.\n; fixed_charge_coverage_ratio: the Fixed Charge Coverage Ratio (atomic Real, ratio to 1.00) for the twelve fiscal month period ending on the observation date.\n(define-fun covenant_holds ((is_fiscal_month_end Bool) (in_financial_covenant_period Bool) (is_month_end_preceding_period_start Bool) (fixed_charge_coverage_ratio Real)) Bool\n  (=> (and is_fiscal_month_end (or in_financial_covenant_period is_month_end_preceding_period_start))\n      (>= fixed_charge_coverage_ratio 1.1)))",
  "symbols": [
    {
      "name": "is_fiscal_month_end",
      "meaning": "True iff the observation date is a fiscal month end, the basis on which the covenant is measured.",
      "source_quote": "measured on a fiscal month-end basis"
    },
    {
      "name": "in_financial_covenant_period",
      "meaning": "True iff the observation date falls within a Financial Covenant Period (a defined term supplied by the evaluator). Combined with is_fiscal_month_end, it makes the observation one of the 'each fiscal month end thereafter during such Financial Covenant Period'.",
      "source_quote": "during such Financial Covenant Period"
    },
    {
      "name": "is_month_end_preceding_period_start",
      "meaning": "True iff the observation date is the end of the fiscal month immediately preceding the date on which a Financial Covenant Period first begins (the initial test date).",
      "source_quote": "the end of the fiscal month immediately preceding the date on which a Financial Covenant Period first begins"
    },
    {
      "name": "fixed_charge_coverage_ratio",
      "meaning": "The Fixed Charge Coverage Ratio, as a Real in x:1.00 terms, tested for the twelve fiscal month period ending on the observation date. Its internal definition is not supplied, so it is treated as atomic.",
      "source_quote": "Fixed Charge Coverage Ratio, measured on a fiscal month-end basis, tested for the twelve fiscal (12) month period ending on such date"
    }
  ],
  "notes": "The covenant is tested at the fiscal month end immediately preceding the start of a Financial Covenant Period, and at each fiscal month end during the period. The formula is therefore applicable when the date is a fiscal month end AND (it is in a Financial Covenant Period OR it is the month end preceding the period start). When applicable, it requires FCCR >= 1.10 (not less than 1.10 to 1.00, so the threshold is inclusive). The Financial Covenant Period definition and the FCCR formula are not in the supplied source, so both are treated as externally supplied inputs. The clause 'until termination of all of the Commitments and payment in full of the Obligations' is a temporal bound, not a testable condition at a given observation, so it is not modeled. No division is performed."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_LRA)\n; availability: Availability at close of business on the observation day. For a non-Business Day, this is Availability as of the immediately preceding Business Day.\n; minimum_level_1_availability: the Minimum Level 1 Availability threshold in effect on the observation day.\n; fccr_pro_forma: the Fixed Charge Coverage Ratio, calculated on a Pro Forma Basis, using information as of the last day of the fiscal quarter ending immediately before the fiscal quarter in which Availability became less than the Minimum Level 1 Availability. Ratio 1.0:1.0 is represented as 1.0.\n; in_prior_trigger_period: true if, on an earlier day, close-of-business Availability was less than the Minimum Level 1 Availability, and Availability has not since been equal to or greater than the Minimum Level 1 Availability for ten (10) consecutive days as of this observation. False otherwise.\n(define-fun covenant_holds ((availability Real) (minimum_level_1_availability Real) (fccr_pro_forma Real) (in_prior_trigger_period Bool)) Bool\n  (=> (or (< availability minimum_level_1_availability) in_prior_trigger_period)\n      (>= fccr_pro_forma 1.0)))",
  "symbols": [
    {
      "name": "availability",
      "meaning": "Availability at close of business on the observation day. For a non-Business Day, this is Availability as of the immediately preceding Business Day.",
      "source_quote": "Availability for a non-Business Day shall be Availability as of the immediately preceding Business Day"
    },
    {
      "name": "minimum_level_1_availability",
      "meaning": "The Minimum Level 1 Availability threshold in effect on the observation day.",
      "source_quote": "Minimum Level 1 Availability"
    },
    {
      "name": "fccr_pro_forma",
      "meaning": "The Fixed Charge Coverage Ratio, calculated on a Pro Forma Basis, using information as of the last day of the fiscal quarter ending immediately before the fiscal quarter in which Availability became less than the Minimum Level 1 Availability. A ratio of 1.0:1.0 is represented as 1.0.",
      "source_quote": "a Fixed Charge Coverage Ratio, calculated on a Pro Forma Basis, of not less than 1.0:1.0"
    },
    {
      "name": "in_prior_trigger_period",
      "meaning": "True if, on an earlier day, close-of-business Availability was less than the Minimum Level 1 Availability, and Availability has not since been equal to or greater than the Minimum Level 1 Availability for ten consecutive days as of this observation. False otherwise.",
      "source_quote": "until such time as the Availability is equal to or greater than the Minimum Level 1 Availability for ten (10) consecutive days"
    }
  ],
  "notes": "Pointwise translation: on any observation where Availability is below the minimum, or a prior trigger has not yet been cured by ten consecutive days at or above the minimum, the FCCR must be at least 1.0. The ten-consecutive-day cure is an event-state input (in_prior_trigger_period) because it depends on history. Fiscal-quarter timing for the FCCR is carried in the fccr_pro_forma input definition. The covenant has no division, so no unresolved-denominator issue arises in the formula. The Article VII lead-in (termination of Commitments, payment of obligations, Required Lender consent) is a general duration and consent framework and is not modeled as a separate input."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n; is_computation_period_end: True iff the observation date is the last day of a fiscal quarter of the Borrower, i.e. the end of a Computation Period (four consecutive fiscal quarters).\n; commitment_or_credit_exposure_outstanding: True iff any Bank has any Commitment under the agreement, or any Credit Exposure remains.\n; consolidated_net_income: Consolidated Net Income (net income or loss, Borrower and Consolidated Subsidiaries, consolidated basis) for the Computation Period ending at the observation.\n; income_tax_provision: Provision for income taxes for the Computation Period, to the extent included in Consolidated Net Income.\n; depreciation_depletion_amortization: Depreciation, depletion and amortization expenses for the Computation Period, to the extent included in Consolidated Net Income.\n; non_cash_restructuring_and_one_time_costs: Non-cash restructuring charges and non-cash one-time costs for the Computation Period, to the extent included in Consolidated Net Income.\n; non_cash_disposition_loss: Aggregate non-cash loss from the sale, exchange or other disposition of capital assets for the Computation Period, to the extent included in Consolidated Net Income.\n; income_tax_credit: Credit for income taxes for the Computation Period, to the extent included in Consolidated Net Income.\n; net_disposition_gain_excl_land: Aggregate net gain from the sale, exchange or other disposition of capital assets for the Computation Period, ignoring gains from all sales of land and land improvement assets, to the extent included in Consolidated Net Income.\n; other_non_cash_gains: Any other non-cash gains for the Computation Period, to the extent included in Consolidated Net Income.\n; gross_interest_expense: Interest expense for the Computation Period as it appears in the consolidated financial statements and notes (Borrower and Consolidated Subsidiaries), before the insurance-policy and interest-income deductions.\n; insurance_policy_interest_expense: Interest expense with respect to Insurance Policies for the Computation Period, as it appears in the consolidated financial statements of the Borrower.\n; interest_income: Interest income for the Computation Period, as it appears in the consolidated financial statements of the Borrower.\n; Interest Expense = gross_interest_expense - insurance_policy_interest_expense - interest_income.\n; EBITDA = consolidated_net_income + income_tax_provision + Interest Expense + depreciation_depletion_amortization + non_cash_restructuring_and_one_time_costs + non_cash_disposition_loss - income_tax_credit - net_disposition_gain_excl_land - other_non_cash_gains.\n; Covenant: Interest Coverage Ratio = EBITDA / Interest Expense must be >= 3.25 at each Computation Period end while Commitments or Credit Exposure exist.\n(define-fun covenant_holds (\n  (is_computation_period_end Bool)\n  (commitment_or_credit_exposure_outstanding Bool)\n  (consolidated_net_income Real)\n  (income_tax_provision Real)\n  (depreciation_depletion_amortization Real)\n  (non_cash_restructuring_and_one_time_costs Real)\n  (non_cash_disposition_loss Real)\n  (income_tax_credit Real)\n  (net_disposition_gain_excl_land Real)\n  (other_non_cash_gains Real)\n  (gross_interest_expense Real)\n  (insurance_policy_interest_expense Real)\n  (interest_income Real)) Bool\n  (=> (and is_computation_period_end commitment_or_credit_exposure_outstanding)\n      (>= (/ (- (+ consolidated_net_income\n                   income_tax_provision\n                   (- (- gross_interest_expense insurance_policy_interest_expense) interest_income)\n                   depreciation_depletion_amortization\n                   non_cash_restructuring_and_one_time_costs\n                   non_cash_disposition_loss)\n                (+ income_tax_credit\n                   net_disposition_gain_excl_land\n                   other_non_cash_gains))\n             (- (- gross_interest_expense insurance_policy_interest_expense) interest_income))\n          3.25)))",
  "symbols": [
    {
      "name": "is_computation_period_end",
      "meaning": "True iff the observation date is the last day of a fiscal quarter of the Borrower, i.e. the end of a Computation Period of four consecutive fiscal quarters.",
      "source_quote": "ending on the last day of a fiscal quarter of the Borrower"
    },
    {
      "name": "commitment_or_credit_exposure_outstanding",
      "meaning": "True iff any Bank has any Commitment under the agreement, or any Credit Exposure remains.",
      "source_quote": "so long as any Bank has any Commitment hereunder, or there remains any Credit Exposure"
    },
    {
      "name": "consolidated_net_income",
      "meaning": "Consolidated Net Income (net income or loss, Borrower and Consolidated Subsidiaries, consolidated basis) for the Computation Period ending at the observation.",
      "source_quote": "the net income (or loss) appearing on the consolidated financial statements of the Borrower and its Consolidated Subsidiaries for such period"
    },
    {
      "name": "income_tax_provision",
      "meaning": "Provision for income taxes for the Computation Period, to the extent included in Consolidated Net Income.",
      "source_quote": "any provision for income taxes"
    },
    {
      "name": "depreciation_depletion_amortization",
      "meaning": "Depreciation, depletion and amortization expenses for the Computation Period, to the extent included in Consolidated Net Income.",
      "source_quote": "depreciation, depletion and amortization expenses"
    },
    {
      "name": "non_cash_restructuring_and_one_time_costs",
      "meaning": "Non-cash restructuring charges and non-cash one-time costs for the Computation Period, to the extent included in Consolidated Net Income.",
      "source_quote": "non-cash restructuring charges and non-cash one-time costs"
    },
    {
      "name": "non_cash_disposition_loss",
      "meaning": "Aggregate non-cash loss from the sale, exchange or other disposition of capital assets for the Computation Period, to the extent included in Consolidated Net Income.",
      "source_quote": "any aggregate non-cash loss from the sale, exchange or other disposition of capital assets"
    },
    {
      "name": "income_tax_credit",
      "meaning": "Credit for income taxes for the Computation Period, to the extent included in Consolidated Net Income.",
      "source_quote": "any credit for income taxes"
    },
    {
      "name": "net_disposition_gain_excl_land",
      "meaning": "Aggregate net gain from the sale, exchange or other disposition of capital assets for the Computation Period, ignoring gains from all sales of land and land improvement assets, to the extent included in Consolidated Net Income.",
      "source_quote": "any aggregate net gain from the sale, exchange or other disposition of capital assets (ignoring gains from all sales of land and land improvement assets)"
    },
    {
      "name": "other_non_cash_gains",
      "meaning": "Any other non-cash gains for the Computation Period, to the extent included in Consolidated Net Income.",
      "source_quote": "any other non-cash gains"
    },
    {
      "name": "gross_interest_expense",
      "meaning": "Interest expense for the Computation Period as it appears in the consolidated financial statements and notes (Borrower and Consolidated Subsidiaries), before the insurance-policy and interest-income deductions.",
      "source_quote": "as it appears in the consolidated financial statements and the notes to the consolidated financial statements of the Borrower for such period"
    },
    {
      "name": "insurance_policy_interest_expense",
      "meaning": "Interest expense with respect to Insurance Policies for the Computation Period, as it appears in the consolidated financial statements of the Borrower.",
      "source_quote": "any interest expense with respect to"
