{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n; is_fiscal_quarter_end: true exactly when the observation is at the end of a fiscal quarter of the Borrower.\n; consolidated_net_worth: Consolidated Net Worth of the Borrower at the observation date.\n; consolidated_total_liabilities_before_exclusion: Consolidated Total Liabilities at the observation date, before excluding any outstanding indebtedness of the Borrower to the Bank pursuant to this Agreement.\n; bank_agreement_indebtedness: outstanding indebtedness of the Borrower to the Bank pursuant to this Agreement at the observation date, which is excluded from Consolidated Total Liabilities.\n(define-fun covenant_holds ((is_fiscal_quarter_end Bool) (consolidated_net_worth Real) (consolidated_total_liabilities_before_exclusion Real) (bank_agreement_indebtedness Real)) Bool\n  (=> is_fiscal_quarter_end\n      (>= (/ consolidated_net_worth (- consolidated_total_liabilities_before_exclusion bank_agreement_indebtedness)) 0.9)))",
  "symbols": [
    {
      "name": "is_fiscal_quarter_end",
      "meaning": "True exactly when the observation is at the end of a fiscal quarter of the Borrower.",
      "source_quote": "calculated at the end of each fiscal quarter of the Borrower"
    },
    {
      "name": "consolidated_net_worth",
      "meaning": "Consolidated Net Worth of the Borrower at the observation date (numerator of the ratio).",
      "source_quote": "Consolidated Net Worth"
    },
    {
      "name": "consolidated_total_liabilities_before_exclusion",
      "meaning": "Consolidated Total Liabilities at the observation date, before excluding any outstanding indebtedness of the Borrower to the Bank pursuant to this Agreement.",
      "source_quote": "Consolidated Total Liabilities"
    },
    {
      "name": "bank_agreement_indebtedness",
      "meaning": "Outstanding indebtedness of the Borrower to the Bank pursuant to this Agreement at the observation date. It is subtracted from Consolidated Total Liabilities to form the denominator.",
      "source_quote": "exclusive of any outstanding indebtedness of the Borrower to the Bank pursuant to this Agreement"
    }
  ],
  "notes": "The covenant is applied pointwise at fiscal quarter-end observations. The ratio is net worth divided by (total liabilities minus Bank indebtedness under this Agreement). The covenant is violated when the ratio is less than 0.90, so it holds when the ratio is at least 0.90, since the threshold itself is not a breach. The denominator may be zero, in which case the evaluator reports the result as unresolved. No sign or positivity assumptions are made. Division by a variable makes the formula nonlinear, so the logic is QF_NRA. The lead-in about the Bank's Commitments or unpaid Notes is a duration condition for the whole covenant. It is not modeled as an input, because the pointwise evaluation covers only supplied observations."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n; consolidated_ebitda: Consolidated EBITDA of the Borrower and its Restricted Subsidiaries for the Test Period being tested (numerator of the ratio).\n; consolidated_interest_expense: Consolidated Interest Expense of the Borrower and its Restricted Subsidiaries for the same Test Period (denominator of the ratio).\n; test_period_ends_effective_date_to_2003_06_30: true iff the Test Period ends on or after the Effective Date and on or before June 30, 2003.\n; test_period_ends_2003_07_01_to_2003_12_31: true iff the Test Period ends between July 1, 2003 and December 31, 2003, inclusive.\n; test_period_ends_2004: true iff the Test Period ends between January 1, 2004 and December 31, 2004, inclusive.\n; test_period_ends_2005_or_later: true iff the Test Period ends on or after January 1, 2005.\n(define-fun covenant_holds ((consolidated_ebitda Real)\n                            (consolidated_interest_expense Real)\n                            (test_period_ends_effective_date_to_2003_06_30 Bool)\n                            (test_period_ends_2003_07_01_to_2003_12_31 Bool)\n                            (test_period_ends_2004 Bool)\n                            (test_period_ends_2005_or_later Bool)) Bool\n  (and\n    (=> test_period_ends_effective_date_to_2003_06_30\n        (>= (/ consolidated_ebitda consolidated_interest_expense) 1.8))\n    (=> test_period_ends_2003_07_01_to_2003_12_31\n        (>= (/ consolidated_ebitda consolidated_interest_expense) 2.0))\n    (=> test_period_ends_2004\n        (>= (/ consolidated_ebitda consolidated_interest_expense) 2.25))\n    (=> test_period_ends_2005_or_later\n        (>= (/ consolidated_ebitda consolidated_interest_expense) 2.5))))",
  "symbols": [
    {
      "name": "consolidated_ebitda",
      "meaning": "Consolidated EBITDA of the Borrower and its Restricted Subsidiaries for the Test Period being tested (numerator of the ratio).",
      "source_quote": "Consolidated EBITDA of the Borrower and its Restricted Subsidiaries"
    },
    {
      "name": "consolidated_interest_expense",
      "meaning": "Consolidated Interest Expense of the Borrower and its Restricted Subsidiaries for the same Test Period (denominator of the ratio).",
      "source_quote": "Consolidated Interest Expense of the Borrower and its Restricted Subsidiaries"
    },
    {
      "name": "test_period_ends_effective_date_to_2003_06_30",
      "meaning": "True iff the Test Period ends on or after the Effective Date and on or before June 30, 2003.",
      "source_quote": "Effective Date to and including June 30,"
    },
    {
      "name": "test_period_ends_2003_07_01_to_2003_12_31",
      "meaning": "True iff the Test Period ends between July 1, 2003 and December 31, 2003, inclusive.",
      "source_quote": "July 1, 2003 to and including"
    },
    {
      "name": "test_period_ends_2004",
      "meaning": "True iff the Test Period ends between January 1, 2004 and December 31, 2004, inclusive.",
      "source_quote": "January 1, 2004 to and including"
    },
    {
      "name": "test_period_ends_2005_or_later",
      "meaning": "True iff the Test Period ends on or after January 1, 2005.",
      "source_quote": "January 1, 2005 and thereafter"
    }
  ],
  "notes": "The covenant requires the ratio EBITDA / Interest Expense not to be less than the minimum for the period in which the Test Period ends, so the check is >=. Minimums are 1.80, 2.00, 2.25 and 2.50. Division by a variable makes the logic QF_NRA. A zero interest expense is left to the evaluator to report as unresolved. Period flags are supplied by the evaluator and are expected to be mutually exclusive. If no flag is true, the test is not applicable and the function returns true. The general preamble (the Agreement being in effect until Commitments terminate) is treated as the observation scope and is not encoded."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n; is_commitment_period: true iff the observation time falls during the Commitment Period (the period in which the Section 6.14 covenant applies).\n; consolidated_tangible_net_worth: Borrower's Consolidated Tangible Net Worth at the observation time, in the same currency units as the other balance figures.\n; subordinated_indebtedness: Borrower's Subordinated Indebtedness at the observation time, in the same currency units.\n; consolidated_liabilities: Borrower's Consolidated Liabilities at the observation time, in the same currency units.\n(define-fun covenant_holds ((is_commitment_period Bool) (consolidated_tangible_net_worth Real) (subordinated_indebtedness Real) (consolidated_liabilities Real)) Bool\n  (=> is_commitment_period\n      (and (>= (/ consolidated_tangible_net_worth subordinated_indebtedness) 1.0)\n           (<= (/ consolidated_liabilities consolidated_tangible_net_worth) 3.0))))",
  "symbols": [
    {
      "name": "is_commitment_period",
      "meaning": "True iff the observation time falls during the Commitment Period, when Section 6.14 applies.",
      "source_quote": "Maintain at all times during the Commitment Period"
    },
    {
      "name": "consolidated_tangible_net_worth",
      "meaning": "Consolidated Tangible Net Worth at the observation time, used as the numerator in (a) and the denominator in (b).",
      "source_quote": "Consolidated Tangible Net Worth"
    },
    {
      "name": "subordinated_indebtedness",
      "meaning": "Subordinated Indebtedness at the observation time, used as the denominator in (a).",
      "source_quote": "Subordinated Indebtedness"
    },
    {
      "name": "consolidated_liabilities",
      "meaning": "Consolidated Liabilities at the observation time, used as the numerator in (b).",
      "source_quote": "Consolidated Liabilities"
    }
  ],
  "notes": "Pointwise translation of 'at all times during the Commitment Period': if the observation is in the Commitment Period, both (a) CTNW/Subordinated Indebtedness >= 1.0 and (b) Consolidated Liabilities/CTNW <= 3.0 must hold. Ratios are computed by division, so QF_NRA is used. Division by zero is left to the evaluator to report as unresolved, with no positivity assumptions. The definitions of the underlying terms are not supplied, so they stay atomic inputs."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_LRA)\n; obligations_unpaid: True if any obligations under this Agreement or any Note remain unpaid at the observation time.\n; lender_has_commitment: True if any Lender has any Commitment hereunder at the observation time.\n; required_lenders_consent_in_writing: True if the Required Lenders have otherwise consented in writing to non-compliance with Section 6.01(j) at the observation time.\n; is_fiscal_quarter_end: True if the observation date is the last day of a fiscal quarter of the Company.\n; leverage_ratio: The Company's Leverage Ratio as at the observation date, as a number x meaning x to 1.0. Treated as an atomic input because its definition is not supplied.\n(define-fun covenant_holds ((obligations_unpaid Bool) (lender_has_commitment Bool) (required_lenders_consent_in_writing Bool) (is_fiscal_quarter_end Bool) (leverage_ratio Real)) Bool\n  (=> (and (or obligations_unpaid lender_has_commitment)\n           (not required_lenders_consent_in_writing)\n           is_fiscal_quarter_end)\n      (<= leverage_ratio 4.0)))",
  "symbols": [
    {
      "name": "obligations_unpaid",
      "meaning": "True if any obligations under this Agreement or any Note remain unpaid at the observation time.",
      "source_quote": "So long as any obligations under this Agreement or any Note shall remain unpaid"
    },
    {
      "name": "lender_has_commitment",
      "meaning": "True if any Lender has any Commitment under the Agreement at the observation time.",
      "source_quote": "any Lender shall have any Commitment hereunder"
    },
    {
      "name": "required_lenders_consent_in_writing",
      "meaning": "True if the Required Lenders have otherwise consented in writing, waiving compliance with Section 6.01(j), at the observation time.",
      "source_quote": "unless the Required Lenders shall otherwise consent in writing"
    },
    {
      "name": "is_fiscal_quarter_end",
      "meaning": "True if the observation date is the last day of a fiscal quarter of the Company.",
      "source_quote": "as at the last day of each fiscal quarter of the Company"
    },
    {
      "name": "leverage_ratio",
      "meaning": "The Company's Leverage Ratio as at the observation date, as a number x meaning x to 1.0. It is an atomic input because the definition is not supplied.",
      "source_quote": "Leverage Ratio of not greater than 4.0 to 1.0"
    }
  ],
  "notes": "Only Section 6.01(j), the Leverage Ratio covenant, is a numeric financial covenant, so only it is encoded. The other 6.01 clauses are qualitative or reporting duties. The covenant applies while obligations are unpaid or a Commitment exists, unless the Required Lenders consent in writing. The maximum is 4.0 to 1.0 (non-strict, <=), tested at fiscal quarter-end. No division is performed, since Leverage Ratio is atomic."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_LRA)\n; covenant_in_force: true iff any Lender has any Commitment, any Loan or other Obligation remains unpaid or unsatisfied, or any Letter of Credit remains outstanding at the observation.\n; is_measurement_date: true iff the observation date is December 31, 2007 or any Quarter-End Date thereafter.\n; is_acquisition_period: true iff the observation date is a Quarter-End Date during an Acquisition Period.\n; leverage_ratio_mlp: Leverage Ratio of the MLP as of the observation date (ratio X in X to 1.00).\n; leverage_ratio_opco: Leverage Ratio of Opco as of the observation date (ratio X in X to 1.00).\n; max_leverage_ratio_subsidiary_borrower: highest Leverage Ratio among all Subsidiary Borrowers as of the observation date (ratio X in X to 1.00).\n(define-fun covenant_holds ((covenant_in_force Bool) (is_measurement_date Bool) (is_acquisition_period Bool) (leverage_ratio_mlp Real) (leverage_ratio_opco Real) (max_leverage_ratio_subsidiary_borrower Real)) Bool\n  (=> (and covenant_in_force is_measurement_date)\n      (and (<= leverage_ratio_mlp (ite is_acquisition_period 5.5 5.0))\n           (<= leverage_ratio_opco (ite is_acquisition_period 5.5 5.0))\n           (<= max_leverage_ratio_subsidiary_borrower 5.0))))",
  "symbols": [
    {
      "name": "covenant_in_force",
      "meaning": "True iff any Lender has any Commitment, any Loan or other Obligation remains unpaid or unsatisfied, or any Letter of Credit remains outstanding at the observation.",
      "source_quote": "So long as any Lender shall have any Commitment hereunder, any Loan or other Obligation hereunder shall remain unpaid or unsatisfied, or any Letter of Credit shall remain outstanding"
    },
    {
      "name": "is_measurement_date",
      "meaning": "True iff the observation date is December 31, 2007 or any Quarter-End Date thereafter.",
      "source_quote": "as of December 31, 2007 or as of any Quarter-End Date thereafter"
    },
    {
      "name": "is_acquisition_period",
      "meaning": "True iff the observation date is a Quarter-End Date during an Acquisition Period.",
      "source_quote": "as of any Quarter-End Date that is during an Acquisition Period"
    },
    {
      "name": "leverage_ratio_mlp",
      "meaning": "Leverage Ratio of the MLP as of the observation date, expressed as X for X to 1.00.",
      "source_quote": "the Leverage Ratio of the MLP"
    },
    {
      "name": "leverage_ratio_opco",
      "meaning": "Leverage Ratio of Opco as of the observation date, expressed as X for X to 1.00.",
      "source_quote": "the Leverage Ratio of Opco"
    },
    {
      "name": "max_leverage_ratio_subsidiary_borrower",
      "meaning": "Highest Leverage Ratio among all Subsidiary Borrowers as of the observation date, expressed as X for X to 1.00. Bounding the maximum is equivalent to bounding every Subsidiary Borrower.",
      "source_quote": "the Leverage Ratio of any Subsidiary Borrower"
    }
  ],
  "notes": "Under (a), the MLP and Opco ratios must not exceed 5.00, or 5.50 when the quarter-end date falls within an Acquisition Period. Under (b), the Subsidiary Borrower ratio must not exceed 5.00, with no Acquisition Period increase. The bound is non-strict because the covenant prohibits a ratio that 'exceeds' the limit. The covenant applies only while commitments, obligations or letters of credit remain, and only as of measurement dates. The Leverage Ratio definition is unavailable, so each ratio is an atomic Real input. The 'any Subsidiary Borrower' clause is modeled with a maximum over all Subsidiary Borrowers, supplied by the evaluator."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n; is_fiscal_quarter_end: true exactly when the observation date is the end of a fiscal quarter of the Company.\n; consolidated_indebtedness: Consolidated Indebtedness of the Company as of the observation date (currency units, same units as total_tangible_capitalization).\n; total_tangible_capitalization: Total Tangible Capitalization of the Company as of the observation date (currency units, same units as consolidated_indebtedness).\n(define-fun covenant_holds ((is_fiscal_quarter_end Bool) (consolidated_indebtedness Real) (total_tangible_capitalization Real)) Bool\n  (=> is_fiscal_quarter_end\n      (<= (* 100 (/ consolidated_indebtedness total_tangible_capitalization)) 60)))",
  "symbols": [
    {
      "name": "is_fiscal_quarter_end",
      "meaning": "True exactly when the observation date is the end of a fiscal quarter of the Company.",
      "source_quote": "as of the end of each fiscal quarter of the Company"
    },
    {
      "name": "consolidated_indebtedness",
      "meaning": "Consolidated Indebtedness of the Company as of the observation date, in currency units matching total_tangible_capitalization.",
      "source_quote": "Consolidated Indebtedness"
    },
    {
      "name": "total_tangible_capitalization",
      "meaning": "Total Tangible Capitalization of the Company as of the observation date, in currency units matching consolidated_indebtedness.",
      "source_quote": "Total Tangible Capitalization"
    }
  ],
  "notes": "The covenant requires the ratio of Consolidated Indebtedness to Total Tangible Capitalization, expressed as a percentage, to be no greater than 60% at each fiscal quarter end. The formula therefore computes 100 * indebtedness / capitalization and applies a non-strict <= 60. The check applies only when is_fiscal_quarter_end is true. The definitions of Consolidated Indebtedness and Total Tangible Capitalization are not supplied, so each is an atomic Real input. A zero Total Tangible Capitalization is left to the evaluator to report as unresolved. QF_NRA is used because the division is by a variable."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_LRA)\n; cash_flow_leverage_ratio: The Borrower's Cash Flow Leverage Ratio as of the observation date, as a ratio to 1.00 (for example, 3.50 means 3.50 to 1.00). Its definition is not supplied, so it is an atomic input.\n; is_december_31_1996: True iff the observation date is December 31, 1996.\n; is_fiscal_quarter_end_after_1996: True iff the observation date is the last day of a fiscal quarter thereafter, meaning after December 31, 1996.\n(define-fun covenant_holds ((cash_flow_leverage_ratio Real) (is_december_31_1996 Bool) (is_fiscal_quarter_end_after_1996 Bool)) Bool\n  (=> (or is_december_31_1996 is_fiscal_quarter_end_after_1996)\n      (<= cash_flow_leverage_ratio 3.5)))",
  "symbols": [
    {
      "name": "cash_flow_leverage_ratio",
      "meaning": "The Borrower's Cash Flow Leverage Ratio as of the observation date, as a ratio to 1.00. The definition is not supplied, so it is an atomic input.",
      "source_quote": "Cash Flow Leverage Ratio to be more than 3.50 to 1.00"
    },
    {
      "name": "is_december_31_1996",
      "meaning": "True iff the observation date is December 31, 1996.",
      "source_quote": "as of December 31, 1996"
    },
    {
      "name": "is_fiscal_quarter_end_after_1996",
      "meaning": "True iff the observation date is the last day of a fiscal quarter after December 31, 1996.",
      "source_quote": "as of the last day of each fiscal quarter thereafter"
    }
  ],
  "notes": "The covenant is pointwise: at an observation date that is December 31, 1996 or a later fiscal quarter-end, the ratio must not be more than 3.50, so the check is (<= ratio 3.5). A ratio of exactly 3.50 complies. The covenant is vacuously satisfied at other dates. The preamble condition (the covenants apply while Notes, Letters of Credit or Commitments remain outstanding) and the Majority Lenders' written-consent exception are not modeled as inputs. The evaluator is assumed to supply observations only while the Credit Documents are in effect, and consent is treated as outside the covenant's numeric test."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_LRA)\n; covenant_period_in_effect: true iff the Article VI condition period is still running at this observation, i.e. the Commitments have not yet expired or terminated, or the Loan principal, interest and fees have not been paid in full, or Letters of Credit have not expired, terminated or been cash collateralized and LC Disbursements reimbursed.\n; is_fiscal_quarter_end: true iff this observation is the end of a fiscal quarter of MK Holdings and its consolidated Subsidiaries.\n; is_on_or_after_2013_03_31: true iff the observation date (fiscal quarter end) is on or after March 31, 2013.\n; leverage_ratio: the Leverage Ratio as of this observation date, as a ratio X in 'X to 1.00' (atomic input; definition not supplied).\n; fixed_charge_coverage_ratio: the Fixed Charge Coverage Ratio as of this observation date, as a ratio X in 'X to 1.00' (atomic input; definition not supplied).\n(define-fun covenant_holds ((covenant_period_in_effect Bool) (is_fiscal_quarter_end Bool) (is_on_or_after_2013_03_31 Bool) (leverage_ratio Real) (fixed_charge_coverage_ratio Real)) Bool\n  (=> (and covenant_period_in_effect is_fiscal_quarter_end is_on_or_after_2013_03_31)\n      (and (not (> leverage_ratio 3.5))\n           (not (< fixed_charge_coverage_ratio 2.0)))))",
  "symbols": [
    {
      "name": "covenant_period_in_effect",
      "meaning": "True iff the Article VI condition period is still running at this observation: the Commitments have not expired or terminated, or Loan principal, interest and fees are not paid in full, or Letters of Credit have not expired, terminated or been cash collateralized and LC Disbursements reimbursed.",
      "source_quote": "Until the Commitments have expired or terminated and the principal of and interest on each Loan and all fees payable hereunder have been paid in full"
    },
    {
      "name": "is_fiscal_quarter_end",
      "meaning": "True iff this observation is the end of a fiscal quarter of MK Holdings and its consolidated Subsidiaries.",
      "source_quote": "the end of each fiscal quarter of MK Holdings and its consolidated Subsidiaries"
    },
    {
      "name": "is_on_or_after_2013_03_31",
      "meaning": "True iff the fiscal quarter end being observed falls on or after March 31, 2013.",
      "source_quote": "ending on and after March 31, 2013"
    },
    {
      "name": "leverage_ratio",
      "meaning": "The Leverage Ratio determined as of the observation date, expressed as X in 'X to 1.00' (atomic; definition not supplied).",
      "source_quote": "to be greater than 3.50 to 1.00"
    },
    {
      "name": "fixed_charge_coverage_ratio",
      "meaning": "The Fixed Charge Coverage Ratio determined as of the observation date, expressed as X in 'X to 1.00' (atomic; definition not supplied).",
