      "meaning": "True iff the observation date is the last day of a fiscal quarter of the Borrower.",
      "source_quote": "As of the last day of each fiscal quarter of the Borrower"
    },
    {
      "name": "ebitda",
      "meaning": "EBITDA of the Borrower for the four consecutive fiscal quarters taken as a single accounting period ending on the observation date, excluding the EBITDA of any Excluded Subsidiary.",
      "source_quote": "EBITDA of the Borrower"
    },
    {
      "name": "interest_expense",
      "meaning": "Interest Expense of the Borrower for the four consecutive fiscal quarters taken as a single accounting period ending on the observation date, excluding Interest Expense of any Excluded Subsidiary.",
      "source_quote": "Interest Expense of the Borrower"
    },
    {
      "name": "maintenance_capex",
      "meaning": "Maintenance Capital Expenditures of the Borrower for the four consecutive fiscal quarters taken as a single accounting period ending on the observation date, excluding Maintenance Capital Expenditures of any Excluded Subsidiary.",
      "source_quote": "Maintenance Capital Expenditures of the Borrower"
