      "source_quote": "Beginning March 31, 2000"
    },
    {
      "name": "total_liabilities",
      "meaning": "Borrower's Total Liabilities as of the observation date.",
      "source_quote": "Total Liabilities"
    },
    {
      "name": "subordinated_debt",
      "meaning": "Borrower's Subordinated Debt as of the observation date, subtracted from Total Liabilities.",
      "source_quote": "Subordinated Debt"
