{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n; is_month_end: true iff the observation date is the last day of a calendar month.\n; cash_and_equivalents: unrestricted cash and cash equivalents of Borrower and its Subsidiaries (consolidated) at the observation date.\n; net_eligible_trade_receivables: net Eligible Accounts that are trade receivables, determined in accordance with GAAP, at the observation date.\n; current_liabilities: Current Liabilities at the observation date: consolidated GAAP current liabilities of Borrower and its Subsidiaries, plus outstanding Credit Extensions under the Agreement to the extent not already included, including Indebtedness payable on demand or within one year unless renewable or extendible at Borrower's or a Subsidiary's option to a date more than one year out.\n; bank_indebtedness_not_included: all Indebtedness (including Contingent Obligations) owing from Borrower to Bank at the observation date, only to the extent not already included in current_liabilities.\n; deferred_maintenance_contract_revenue: deferred maintenance contract revenue at the observation date, subtracted in the denominator.\n(define-fun covenant_holds ((is_month_end Bool) (cash_and_equivalents Real) (net_eligible_trade_receivables Real) (current_liabilities Real) (bank_indebtedness_not_included Real) (deferred_maintenance_contract_revenue Real)) Bool\n  (=> is_month_end\n      (>= (/ (+ cash_and_equivalents net_eligible_trade_receivables)\n             (- (+ current_liabilities bank_indebtedness_not_included) deferred_maintenance_contract_revenue))\n          1.25)))",
  "symbols": [
    {
      "name": "is_month_end",
      "meaning": "True iff the observation date is the last day of a calendar month, the measurement date for the covenant.",
      "source_quote": "measured as of the last day of each calendar month"
    },
    {
      "name": "cash_and_equivalents",
      "meaning": "Unrestricted cash and cash equivalents of Borrower and its Subsidiaries (consolidated) at the observation date; the first component of Adjusted Quick Assets.",
      "source_quote": "the unrestricted cash and cash equivalents of Borrower and its Subsidiaries"
    },
    {
      "name": "net_eligible_trade_receivables",
      "meaning": "Net Eligible Accounts that are trade receivables, determined in accordance with GAAP, at the observation date; the second component of Adjusted Quick Assets.",
      "source_quote": "net Eligible Accounts which are trade receivables"
    },
    {
      "name": "current_liabilities",
      "meaning": "Current Liabilities at the observation date: consolidated GAAP current liabilities plus outstanding Credit Extensions under the Agreement to the extent not already included, including Indebtedness payable on demand or within one year unless renewable or extendible at the option of Borrower or a Subsidiary to a date more than one year out.",
      "source_quote": "all amounts that should, in accordance with GAAP, be included as current liabilities on the consolidated balance sheet of Borrower and its Subsidiaries, as at such date, plus, to the extent not already included therein, all outstanding Credit Extensions made under this Agreement"
    },
    {
      "name": "bank_indebtedness_not_included",
      "meaning": "All Indebtedness (including Contingent Obligations) owing from Borrower to Bank at the observation date, only to the extent not already included in current_liabilities; added to the denominator.",
      "source_quote": "all Indebtedness (including without limitation any Contingent Obligations) owing from Borrower to Bank"
    },
    {
      "name": "deferred_maintenance_contract_revenue",
      "meaning": "Deferred maintenance contract revenue at the observation date; subtracted in the denominator.",
      "source_quote": "less deferred maintenance contract revenue"
    }
  ],
  "notes": "On month-end observations, the ratio of Adjusted Quick Assets (cash and equivalents plus net eligible trade receivables) to (Current Liabilities + Bank Indebtedness not already included - deferred maintenance contract revenue) must be at least 1.25 (non-strict). The non-month-end case is vacuously true. A zero denominator is left to the evaluator to report as unresolved. QF_NRA is used because the denominator is a variable expression. The stated 'on a consolidated basis' scope is carried in the input meanings. The 'until payment in full' duration clause is outside the pointwise observation schema."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n; bank_has_commitment: true iff the Bank has any Commitment hereunder at the observation time.\n; note_amount_unpaid: true iff any amount payable under the Note remains unpaid at the observation time.\n; funded_liabilities: Borrower's total Funded Liabilities at the observation time (currency units).\n; tangible_net_worth: Borrower's Tangible Net Worth at the observation time (same currency units).\n(define-fun covenant_holds ((bank_has_commitment Bool) (note_amount_unpaid Bool) (funded_liabilities Real) (tangible_net_worth Real)) Bool\n  (=> (or bank_has_commitment note_amount_unpaid)\n      (<= (/ funded_liabilities tangible_net_worth) 0.75)))",
  "symbols": [
    {
      "name": "bank_has_commitment",
      "meaning": "True iff the Bank has any Commitment hereunder at the observation time.",
      "source_quote": "so long as the Bank has any Commitment hereunder"
    },
    {
      "name": "note_amount_unpaid",
      "meaning": "True iff any amount payable under the Note remains unpaid at the observation time.",
      "source_quote": "any amount payable under the Note remains unpaid"
    },
    {
      "name": "funded_liabilities",
      "meaning": "Borrower's total Funded Liabilities at the observation time, in currency units; numerator of the ratio.",
      "source_quote": "total Funded Liabilities"
    },
    {
      "name": "tangible_net_worth",
      "meaning": "Borrower's Tangible Net Worth at the observation time, in the same currency units; denominator of the ratio.",
      "source_quote": "Tangible Net Worth"
    }
  ],
  "notes": "The covenant applies while the Bank has any Commitment or any amount under the Note is unpaid, so the two conditions are joined with OR. The ratio is Funded Liabilities divided by Tangible Net Worth and must be at most 0.75 (.75 to 1.0, 'not more than', non-strict). Division is kept literal with no positivity assumption on Tangible Net Worth, so a zero denominator is reported as unresolved by the evaluator. QF_NRA is used because the division is by a variable."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n; is_fiscal_month_end: true iff the observation is the end of a fiscal monthly period.\n; is_on_or_after_commencement_month: true iff the fiscal month ending at this observation is the month ending September 30, 2004 or a later month.\n; consolidated_senior_debt: Senior Debt of Credit Parties and their Subsidiaries on a consolidated basis, as of the end of the fiscal month.\n; consolidated_ebitda_ttm: consolidated EBITDA of Credit Parties and their Subsidiaries, calculated on a trailing 12-month basis for the 12-month period ending at the fiscal month end.\n(define-fun covenant_holds ((is_fiscal_month_end Bool)\n                            (is_on_or_after_commencement_month Bool)\n                            (consolidated_senior_debt Real)\n                            (consolidated_ebitda_ttm Real)) Bool\n  (=> (and is_fiscal_month_end is_on_or_after_commencement_month)\n      (<= (/ consolidated_senior_debt consolidated_ebitda_ttm) 1.5)))",
  "symbols": [
    {
      "name": "is_fiscal_month_end",
      "meaning": "True iff the observation is as of the end of a fiscal monthly period.",
      "source_quote": "As of the end of each fiscal monthly period"
    },
    {
      "name": "is_on_or_after_commencement_month",
      "meaning": "True iff the fiscal month ending at this observation is the month ending September 30, 2004 or a later month.",
      "source_quote": "commencing with the month ending September 30, 2004"
    },
    {
      "name": "consolidated_senior_debt",
      "meaning": "Senior Debt of Credit Parties and their Subsidiaries on a consolidated basis, as of the end of the fiscal month (numerator of the Senior Debt/EBITDA Ratio).",
      "source_quote": "Credit Parties and their Subsidiaries shall have on a consolidated basis a Senior Debt/EBITDA Ratio"
    },
    {
      "name": "consolidated_ebitda_ttm",
      "meaning": "Consolidated EBITDA of Credit Parties and their Subsidiaries calculated on a trailing 12-month basis for the 12-month period then ended (denominator of the ratio).",
      "source_quote": "EBITDA shall be calculated on a trailing 12-month basis"
    }
  ],
  "notes": "The ratio is modeled as Senior Debt divided by EBITDA, as the name 'Senior Debt/EBITDA Ratio' indicates. 'Not greater than 1.50 to 1.00' becomes <= 1.5. A zero EBITDA makes the division unresolved, per the evaluator's policy, and no positivity of EBITDA is assumed. The test applies only at fiscal month ends on or after the September 30, 2004 commencement month. QF_NRA is used because the division is by a variable."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_LRA)\n; lender_commitment_exists: true iff at the observation time any Lender has any Commitment under the Agreement.\n; loan_or_obligation_unpaid: true iff at the observation time any Loan or other Obligation under the Agreement remains unpaid or unsatisfied.\n; letter_of_credit_outstanding: true iff at the observation time any Letter of Credit remains outstanding.\n; is_fiscal_quarter_end: true iff the observation time is the end of a fiscal quarter of the Borrower.\n; consolidated_leverage_ratio: Consolidated Leverage Ratio at the end of the fiscal quarter, as a number (3.00:1.0 means 3.0), calculated over the twelve month period ending with that quarter, with any Acquisition in the period treated as if it occurred at the beginning of the period.\n; consolidated_interest_coverage_ratio: Consolidated Interest Coverage Ratio at the end of the fiscal quarter, as a number (3.0:1.0 means 3.0), calculated over the twelve month period ending with that quarter.\n(define-fun covenant_holds ((lender_commitment_exists Bool) (loan_or_obligation_unpaid Bool) (letter_of_credit_outstanding Bool) (is_fiscal_quarter_end Bool) (consolidated_leverage_ratio Real) (consolidated_interest_coverage_ratio Real)) Bool\n  (=> (and (or lender_commitment_exists loan_or_obligation_unpaid letter_of_credit_outstanding) is_fiscal_quarter_end)\n      (and (<= consolidated_leverage_ratio 3.0)\n           (>= consolidated_interest_coverage_ratio 3.0))))",
  "symbols": [
    {
      "name": "lender_commitment_exists",
      "meaning": "True iff at the observation time any Lender has any Commitment under the Agreement.",
      "source_quote": "So long as any Lender shall have any Commitment hereunder"
    },
    {
      "name": "loan_or_obligation_unpaid",
      "meaning": "True iff at the observation time any Loan or other Obligation under the Agreement remains unpaid or unsatisfied.",
      "source_quote": "any Loan or other Obligation hereunder shall remain unpaid or unsatisfied"
    },
    {
      "name": "letter_of_credit_outstanding",
      "meaning": "True iff at the observation time any Letter of Credit remains outstanding.",
      "source_quote": "any Letter of Credit shall remain outstanding"
    },
    {
      "name": "is_fiscal_quarter_end",
      "meaning": "True iff the observation time is the end of a fiscal quarter of the Borrower.",
      "source_quote": "at the end of any fiscal quarter"
    },
    {
      "name": "consolidated_leverage_ratio",
      "meaning": "Consolidated Leverage Ratio at the end of the fiscal quarter, as a number (3.00:1.0 means 3.0). It is calculated over the twelve month period ending with that quarter, with any Acquisition in the period treated as if it occurred at the beginning of the period.",
      "source_quote": "the Consolidated Leverage Ratio shall be calculated as if such Acquisition occurred at the beginning of such period"
    },
    {
      "name": "consolidated_interest_coverage_ratio",
      "meaning": "Consolidated Interest Coverage Ratio at the end of the fiscal quarter, as a number (3.0:1.0 means 3.0). It is calculated over the twelve month period ending with that quarter.",
      "source_quote": "Permit its Consolidated Interest Coverage Ratio at the end of any fiscal quarter to be less than 3.0:1.0"
    }
  ],
  "notes": "The covenant is a prohibition, so compliance means the ratios are not in the forbidden range: the leverage ratio must not exceed 3.0 (<= 3.0) and the interest coverage ratio must not be less than 3.0 (>= 3.0). It applies only while a Commitment exists, an Obligation is unpaid, or a Letter of Credit is outstanding (any one of the three), and only at fiscal quarter ends. The two ratios are atomic inputs because their component definitions are not supplied. The Acquisition pro forma adjustment and the twelve-month measurement period are part of the input meanings, so the evaluator must supply ratios computed that way. No division appears in the formula."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_LRA)\n; quick_ratio: Borrower's Quick Ratio as of the observation date, expressed as a multiple of 1.0 (for example, 2.00 means 2.00 to 1.0). The source does not define its arithmetic, so it is atomic.\n; is_last_day_of_fiscal_quarter: true iff the observation date is the last day of a fiscal quarter of Borrower.\n; all_obligations_paid_in_full: true iff all Obligations have been paid in full as of the observation.\n; letter_of_credit_terminated: true iff the Letter of Credit has been terminated as of the observation.\n; bank_prior_written_consent: true iff Bank has given prior written consent that otherwise relieves Borrower from complying with this covenant at the observation.\n(define-fun covenant_holds ((quick_ratio Real) (is_last_day_of_fiscal_quarter Bool) (all_obligations_paid_in_full Bool) (letter_of_credit_terminated Bool) (bank_prior_written_consent Bool)) Bool\n  (=> (and is_last_day_of_fiscal_quarter\n           (not (and all_obligations_paid_in_full letter_of_credit_terminated))\n           (not bank_prior_written_consent))\n      (>= quick_ratio 2.0)))",
  "symbols": [
    {
      "name": "quick_ratio",
      "meaning": "Borrower's Quick Ratio as of the observation date, as a multiple of 1.0 (2.00 means 2.00 to 1.0). Its arithmetic definition is not supplied, so it is atomic.",
      "source_quote": "a Quick Ratio of at least 2.00 to 1.0"
    },
    {
      "name": "is_last_day_of_fiscal_quarter",
      "meaning": "True iff the observation date is the last day of a fiscal quarter of Borrower.",
      "source_quote": "as of the last day of each fiscal quarter"
    },
    {
      "name": "all_obligations_paid_in_full",
      "meaning": "True iff all Obligations have been paid in full as of the observation.",
      "source_quote": "until payment in full of all Obligations"
    },
    {
      "name": "letter_of_credit_terminated",
      "meaning": "True iff the Letter of Credit has been terminated as of the observation.",
      "source_quote": "termination of the Letter of Credit"
    },
    {
      "name": "bank_prior_written_consent",
      "meaning": "True iff Bank has given prior written consent that otherwise relieves Borrower from complying with this covenant at the observation.",
      "source_quote": "unless Bank shall otherwise give its prior written consent"
    }
  ],
  "notes": "The covenant is checked pointwise at quarter-end observations. It applies while the Obligations are not yet paid in full or the Letter of Credit is not yet terminated, and it is waived when Bank's prior written consent is given. When it applies, the Quick Ratio must be at least 2.0 (non-strict). There is no division in the formula, because the ratio is atomic."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n; is_on_or_after_effective_date: true iff the observation time is from and after the Effective Date.\n; consolidated_ebitda: Consolidated EBITDA for the most recently ended period of four consecutive fiscal quarters for which financial statements have been delivered under Section 5.01, or, before any such delivery, for the four consecutive fiscal quarters ended September 30, 2013.\n; consolidated_interest_expense: Consolidated Interest Expense for that same four-fiscal-quarter period.\n(define-fun covenant_holds ((is_on_or_after_effective_date Bool) (consolidated_ebitda Real) (consolidated_interest_expense Real)) Bool\n  (=> is_on_or_after_effective_date\n      (>= (/ consolidated_ebitda consolidated_interest_expense) 4.0)))",
  "symbols": [
    {
      "name": "is_on_or_after_effective_date",
      "meaning": "True iff the observation time is from and after the Effective Date, when Section 6.08 applies.",
      "source_quote": "From and after the Effective Date"
    },
    {
      "name": "consolidated_ebitda",
      "meaning": "Consolidated EBITDA for the most recently ended period of four consecutive fiscal quarters for which financial statements have been delivered under Section 5.01, or, before any such delivery, for the four consecutive fiscal quarters ended September 30, 2013.",
      "source_quote": "Consolidated EBITDA"
    },
    {
      "name": "consolidated_interest_expense",
      "meaning": "Consolidated Interest Expense for the same four-fiscal-quarter period as consolidated_ebitda.",
      "source_quote": "Consolidated Interest Expense"
    }
  ],
  "notes": "The covenant forbids a ratio of Consolidated EBITDA to Consolidated Interest Expense below 4.0 to 1.0, so compliance means ratio >= 4.0 (non-strict). The ratio is kept as an explicit division, so the evaluator reports a zero Consolidated Interest Expense as unresolved. Because of the variable divisor, the logic is QF_NRA. The evaluator selects the applicable four-quarter measurement period (the latest delivered, or the period ended September 30, 2013 before any delivery) when supplying the two Real inputs. The lead-in conditions about Commitments, Loans and Letters of Credit are not modelled separately."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_LRA)\n; fixed_charge_coverage_ratio: Borrower's Fixed Charge Coverage Ratio as of the observation date (atomic Real; definition not supplied), expressed as X in X:1.\n; is_fiscal_quarter_end: true iff the observation date is the last day of a fiscal quarter of the Borrower.\n; is_on_or_after_first_test_quarter: true iff the observation date falls in or after the fiscal quarter ending March 31, 2001.\n; obligations_outstanding_period: true iff the Credit Agreement and Commitments have not terminated and all Obligations (other than then contingent indemnification obligations) have not yet been paid and satisfied.\n; required_lenders_written_consent: true iff the Required Lenders have otherwise consented in writing so that the covenant is not required at this observation.\n(define-fun covenant_holds ((fixed_charge_coverage_ratio Real) (is_fiscal_quarter_end Bool) (is_on_or_after_first_test_quarter Bool) (obligations_outstanding_period Bool) (required_lenders_written_consent Bool)) Bool\n  (=> (and obligations_outstanding_period\n           is_fiscal_quarter_end\n           is_on_or_after_first_test_quarter\n           (not required_lenders_written_consent))\n      (>= fixed_charge_coverage_ratio 1.10)))",
  "symbols": [
    {
      "name": "fixed_charge_coverage_ratio",
      "meaning": "Borrower's Fixed Charge Coverage Ratio as of the observation date, as a Real X meaning X:1. Atomic because its definition is not supplied.",
      "source_quote": "Fixed Charge Coverage Ratio of not less than 1.10:1"
    },
    {
      "name": "is_fiscal_quarter_end",
      "meaning": "True iff the observation date is the last day of a fiscal quarter.",
      "source_quote": "as of the last day of each fiscal quarter"
    },
    {
      "name": "is_on_or_after_first_test_quarter",
      "meaning": "True iff the observation date falls in or after the fiscal quarter ending March 31, 2001.",
      "source_quote": "beginning with the fiscal quarter ending March 31, 2001"
    },
    {
      "name": "obligations_outstanding_period",
      "meaning": "True iff the Credit Agreement and Commitments have not terminated and all Obligations (other than then contingent indemnification obligations) have not yet been paid and satisfied.",
      "source_quote": "Until termination of this Credit Agreement and the Commitments hereunder and payment and satisfaction of all Obligations (other than then contingent indemnification obligations)"
    },
    {
      "name": "required_lenders_written_consent",
      "meaning": "True iff the Required Lenders have consented in writing otherwise than the covenant requires, waiving or modifying it for this observation.",
      "source_quote": "unless the Required Lenders shall have otherwise consented in writing"
    }
  ],
  "notes": "Pointwise translation: the covenant applies only at fiscal quarter-end observations from the March 31, 2001 quarter onward, while the agreement is in force and absent Required Lenders' written consent. In that case the Fixed Charge Coverage Ratio must be >= 1.10 (non-strict, 'not less than'). The ratio is an atomic input because no arithmetic definition was supplied. The consent flag is a Bool because the source gives no scope for the consent. No division occurs in the formula."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n; is_fiscal_quarter_end: true iff the observation date is the last day of a Fiscal Quarter of the Company.\n; current_assets_reported: Current Assets of the Company as of the observation date, before excluding FAS 133 and 143 adjustments.\n; current_liabilities_reported: Current Liabilities of the Company as of the observation date, before excluding FAS 133 and 143 adjustments.\n; fas_133_143_adjustment_in_current_assets: net amount by which adjustments required by FAS 133 and 143 are included in (increase) reported Current Assets; negative if they decrease it. This amount is excluded from current assets.\n; fas_133_143_adjustment_in_current_liabilities: net amount by which adjustments required by FAS 133 and 143 are included in (increase) reported Current Liabilities; negative if they decrease it. This amount is excluded from current liabilities.\n(define-fun covenant_holds ((is_fiscal_quarter_end Bool)\n                            (current_assets_reported Real)\n                            (current_liabilities_reported Real)\n                            (fas_133_143_adjustment_in_current_assets Real)\n                            (fas_133_143_adjustment_in_current_liabilities Real)) Bool\n  (=> is_fiscal_quarter_end\n      (>= (/ (- current_assets_reported fas_133_143_adjustment_in_current_assets)\n             (- current_liabilities_reported fas_133_143_adjustment_in_current_liabilities))\n          1.0)))",
  "symbols": [
    {
      "name": "is_fiscal_quarter_end",
      "meaning": "True iff the observation date is the last day of a Fiscal Quarter of the Company.",
      "source_quote": "As of the last day of any Fiscal Quarter"
    },
    {
      "name": "current_assets_reported",
      "meaning": "Current Assets of the Company as of the observation date, before excluding FAS 133 and 143 adjustments.",
      "source_quote": "the ratio of Current Assets to Current Liabilities"
    },
    {
      "name": "current_liabilities_reported",
      "meaning": "Current Liabilities of the Company as of the observation date, before excluding FAS 133 and 143 adjustments.",
      "source_quote": "the ratio of Current Assets to Current Liabilities"
    },
    {
      "name": "fas_133_143_adjustment_in_current_assets",
      "meaning": "Net amount by which adjustments required by FAS 133 and 143 are included in (increase) reported Current Assets; negative if they decrease it. This amount is excluded from current assets.",
      "source_quote": "adjustments required by FAS 133 and 143 that affect the calculation of Current Assets or Current Liabilities shall be excluded from current assets and current liabilities, respectively"
    },
    {
      "name": "fas_133_143_adjustment_in_current_liabilities",
      "meaning": "Net amount by which adjustments required by FAS 133 and 143 are included in (increase) reported Current Liabilities; negative if they decrease it. This amount is excluded from current liabilities.",
      "source_quote": "adjustments required by FAS 133 and 143 that affect the calculation of Current Assets or Current Liabilities shall be excluded from current assets and current liabilities, respectively"
    }
  ],
  "notes": "Applicability is limited to fiscal quarter-end dates. The ratio is adjusted Current Assets divided by adjusted Current Liabilities, and 'shall not be less than 1.00 to 1.00' becomes ratio >= 1.0. A zero adjusted denominator is reported as unresolved by the evaluator. The FAS 133/143 exclusion is modeled by subtracting each adjustment amount from the corresponding reported figure. The ratio is a division of two Real terms, so QF_NRA is used."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n; covenant_period_in_effect: true iff the Section 6.12 covenant period is still running at this observation, i.e. it is NOT yet the case that the Commitments have expired or terminated, all Loan principal and interest and all fees payable have been paid in full, all Letters of Credit have expired or terminated without any pending draw, and all LC Disbursements have been reimbursed.\n; is_fiscal_quarter_end: true iff the observation date is the last day of a fiscal quarter of the Borrower.\n; quarter_end_on_or_after_2015_10_31: true iff the fiscal quarter ending at this observation date ends on or after October 31, 2015.\n; consolidated_total_indebtedness: Consolidated Total Indebtedness of the Borrower and its Subsidiaries on a consolidated basis, as of the fiscal quarter end (currency units).\n; consolidated_ebitda_ttm: Consolidated EBITDA of the Borrower and its Subsidiaries on a consolidated basis for the four consecutive fiscal quarters ending with this fiscal quarter end (currency units).\n; consolidated_cash_interest_expense_ttm: Consolidated Cash Interest Expense of the Borrower and its Subsidiaries on a consolidated basis for the four consecutive fiscal quarters ending with this fiscal quarter end (currency units).\n(define-fun covenant_holds ((covenant_period_in_effect Bool) (is_fiscal_quarter_end Bool) (quarter_end_on_or_after_2015_10_31 Bool) (consolidated_total_indebtedness Real) (consolidated_ebitda_ttm Real) (consolidated_cash_interest_expense_ttm Real)) Bool\n  (=> (and covenant_period_in_effect is_fiscal_quarter_end quarter_end_on_or_after_2015_10_31)\n      (and\n        ; (a) Total Leverage Ratio must not be greater than 3.00 to 1.00\n        (<= (/ consolidated_total_indebtedness consolidated_ebitda_ttm) 3.0)\n        ; (b) Interest Coverage Ratio must not be less than 3.00 to 1.00\n        (>= (/ consolidated_ebitda_ttm consolidated_cash_interest_expense_ttm) 3.0))))",
  "symbols": [
    {
      "name": "covenant_period_in_effect",
      "meaning": "True iff the covenant period is still running at this observation: it is not yet the case that the Commitments have expired or terminated, all Loan principal, interest and fees have been paid in full, all Letters of Credit have expired or terminated without any pending draw, and all LC Disbursements have been reimbursed.",
      "source_quote": "Until the Commitments have expired or terminated and the principal of and interest on each Loan and all fees payable hereunder have been paid in full and all Letters of Credit have expired or terminated, in each case, without any pending draw, and all LC Disbursements shall have been reimbursed"
    },
    {
      "name": "is_fiscal_quarter_end",
      "meaning": "True iff the observation date is the end of a fiscal quarter of the Borrower.",
      "source_quote": "determined as of the end of each of its fiscal quarters"
    },
    {
      "name": "quarter_end_on_or_after_2015_10_31",
      "meaning": "True iff the fiscal quarter ending at this observation ends on or after October 31, 2015.",
      "source_quote": "fiscal quarters ending on and after October, 31, 2015"
    },
    {
      "name": "consolidated_total_indebtedness",
      "meaning": "Consolidated Total Indebtedness of the Borrower and its Subsidiaries on a consolidated basis as of the fiscal quarter end (numerator of the Total Leverage Ratio).",
      "source_quote": "Consolidated Total Indebtedness"
    },
    {
      "name": "consolidated_ebitda_ttm",
      "meaning": "Consolidated EBITDA of the Borrower and its Subsidiaries on a consolidated basis for the four consecutive fiscal quarters ending with this fiscal quarter end. It is the denominator of the Total Leverage Ratio and the numerator of the Interest Coverage Ratio.",
      "source_quote": "Consolidated EBITDA for the period of four (4) consecutive fiscal quarters ending with the end of such fiscal quarter"
    },
    {
      "name": "consolidated_cash_interest_expense_ttm",
      "meaning": "Consolidated Cash Interest Expense of the Borrower and its Subsidiaries on a consolidated basis for the four consecutive fiscal quarters ending with this fiscal quarter end (denominator of the Interest Coverage Ratio).",
      "source_quote": "Consolidated Cash Interest Expense"
