{
  "status": "formalized",
  "smt2": "(set-logic QF_LRA)\n; consolidated_leverage_ratio: Consolidated Leverage Ratio as at the last day of the four-consecutive-fiscal-quarter period ending with the observed fiscal quarter.\n; senior_secured_leverage_ratio: Consolidated Senior Secured Leverage Ratio as at the last day of the four-consecutive-fiscal-quarter period ending with the observed fiscal quarter.\n; interest_coverage_ratio: Consolidated Interest Coverage Ratio for the four-consecutive-fiscal-quarter period ending with the observed fiscal quarter. The evaluator supplies it with Consolidated Interest Expense already adjusted by the stated provisos (annualization deemed amounts for the quarters ending 12/31/2003, 3/31/2004 and 6/30/2004, and pro forma Refinancing for the quarter ending 12/31/2003).\n; in_fq4_2003_to_fq3_2004: true iff the observation is at the last day of a fiscal quarter from FQ4 2003 through FQ3 2004 inclusive.\n; in_fq4_2004_to_fq3_2005: true iff the observation is at the last day of a fiscal quarter from FQ4 2004 through FQ3 2005 inclusive.\n; in_fq4_2005_to_fq2_2006: true iff the observation is at the last day of a fiscal quarter from FQ4 2005 through FQ2 2006 inclusive.\n; in_fq3_2006: true iff the observation is at the last day of FQ3 2006.\n; in_fq4_2006_to_fq3_2007: true iff the observation is at the last day of a fiscal quarter from FQ4 2006 through FQ3 2007 inclusive.\n; in_fq4_2007_and_thereafter: true iff the observation is at the last day of FQ4 2007 or any later fiscal quarter.\n(define-fun covenant_holds (\n    (consolidated_leverage_ratio Real)\n    (senior_secured_leverage_ratio Real)\n    (interest_coverage_ratio Real)\n    (in_fq4_2003_to_fq3_2004 Bool)\n    (in_fq4_2004_to_fq3_2005 Bool)\n    (in_fq4_2005_to_fq2_2006 Bool)\n    (in_fq3_2006 Bool)\n    (in_fq4_2006_to_fq3_2007 Bool)\n    (in_fq4_2007_and_thereafter Bool)) Bool\n  (and\n    ; 7.1(a) Consolidated Leverage Ratio must not exceed the maximum\n    (=> in_fq4_2003_to_fq3_2004 (<= consolidated_leverage_ratio 5.90))\n    (=> in_fq4_2004_to_fq3_2005 (<= consolidated_leverage_ratio 5.75))\n    (=> in_fq4_2005_to_fq2_2006 (<= consolidated_leverage_ratio 5.50))\n    (=> in_fq3_2006 (<= consolidated_leverage_ratio 5.25))\n    (=> in_fq4_2006_to_fq3_2007 (<= consolidated_leverage_ratio 5.00))\n    (=> in_fq4_2007_and_thereafter (<= consolidated_leverage_ratio 4.75))\n    ; 7.1(b) Consolidated Senior Secured Leverage Ratio must not exceed the maximum\n    (=> in_fq4_2003_to_fq3_2004 (<= senior_secured_leverage_ratio 2.50))\n    (=> in_fq4_2004_to_fq3_2005 (<= senior_secured_leverage_ratio 2.25))\n    (=> (or in_fq4_2005_to_fq2_2006 in_fq3_2006) (<= senior_secured_leverage_ratio 2.00))\n    (=> (or in_fq4_2006_to_fq3_2007 in_fq4_2007_and_thereafter) (<= senior_secured_leverage_ratio 1.75))\n    ; 7.1(c) Consolidated Interest Coverage Ratio must not be less than the minimum\n    (=> in_fq4_2003_to_fq3_2004 (>= interest_coverage_ratio 2.50))\n    (=> in_fq4_2004_to_fq3_2005 (>= interest_coverage_ratio 2.75))\n    (=> (or in_fq4_2005_to_fq2_2006 in_fq3_2006) (>= interest_coverage_ratio 3.00))\n    (=> in_fq4_2006_to_fq3_2007 (>= interest_coverage_ratio 3.25))\n    (=> in_fq4_2007_and_thereafter (>= interest_coverage_ratio 3.50))))",
  "symbols": [
    {
      "name": "consolidated_leverage_ratio",
      "meaning": "Consolidated Leverage Ratio as at the last day of the four-consecutive-fiscal-quarter period ending with the observed fiscal quarter (atomic Real; definition not supplied).",
