    {
      "name": "ebitda_four_quarters",
      "meaning": "EBITDA of the Borrower for the four fiscal quarters then ended, in currency units.",
      "source_quote": "EBITDA for the four fiscal quarters of the Borrower then ended"
    },
    {
      "name": "interest_coverage_ratio",
      "meaning": "The Interest Coverage Ratio at the observation time (last day of the fiscal quarter), expressed as X in X to 1.00.",
