03_p Real) (no_default_before Bool) (no_default_after Bool) (pro_forma_consolidated_leverage_ratio Real) (intercompany_note_repayment Bool)) Bool\n  (=> prepayment_event\n      (or conversion_to_equity\n          permitted_refinancing\n          (<= c_aggregate_consideration (- (- 50000000.0 restricted_payments_7_06_i) investments_7_03_p))\n          (and no_default_before\n               no_default_after\n               (<= pro_forma_consolidated_leverage_ratio 2.0))\n          intercompany_note_repayment)))",
