  "smt2": "(set-logic QF_LRA)\n; lender_has_credit_exposure: true if any Lender has any Credit Exposure under the agreement at the observation time.\n; days_since_fiscal_year_end: days elapsed at the observation since the end of the most recent fiscal year of the Company.\n; annual_package_delivered_within_113_days: true if the annual deliverables for that fiscal year (audited consolidated balance sheet, income and cash flow statements, with prior-year comparatives and accountants' report) were delivered to the Administrative Agent no later than 113 days after the fiscal year end.\n; is_first_three_quarter_period: true if the most recently ended fiscal period is one of the first three quarters of a fiscal year (not the fourth).\n; days_since_quarter_end: days elapsed at the observation since the end of that quarter.\n; quarterly_package_delivered_within_53_days: true if the quarterly deliverables for that quarter (consolidated balance sheet, income and cash flow statements, officer-certified) were delivered no later than 53 days after the quarter end.\n; days_since_officer_knowledge_of_default: days elapsed at the observation since a Responsible Officer of the Company obtained knowledge of the Default.\n; default_continuing_at_day_5: true if that Default is still continuing at the five-day deadline.\n; default_certificate_delivered_within_5_days: true if the certificate of the principal financial officer or principal accounting officer, setting forth the details of the Default and the action the Company is taking or proposes to take, was delivered within five days after such knowledge.\n(define-fun covenant_holds (\n    (lender_has_credit_exposure Bool)\n    (days_since_fiscal_year_end Real)\n    (annual_package_delivered_within_113_days Bool)\n    (is_first_three_quarter_period Bool)\n    (days_since_quarter_end Real)\n    (quarterly_package_delivered_within_53_days Bool)\n    (days_since_officer_knowledge_of_default Real)\n    (default_continuing_at_day_5 Bool)\n    (default_certificate_delivered_within_5_days Bool)) Bool\n  (=> lender_has_credit_exposure\n      (and\n        (=> (> days_since_fiscal_year_end 113) annual_package_delivered_within_113_days)\n        (=> (and is_first_three_quarter_period (> days_since_quarter_end 53))\n            quarterly_package_delivered_within_53_days)\n        (=> (and (> days_since_officer_knowledge_of_default 5) default_continuing_at_day_5)\n            default_certificate_delivered_within_5_days))))",
