      "meaning": "True if the most recently ended fiscal period is one of the first three quarters of a fiscal year.",
      "source_quote": "within 53 days after the end of each of the first three quarters of each fiscal year of the Company"
    },
    {
      "name": "days_since_quarter_end",
      "meaning": "Days elapsed at the observation since the end of the relevant fiscal quarter.",
      "source_quote": "within 53 days after the end of each of the first three quarters of each fiscal year of the Company"
    },
    {
      "name": "quarterly_package_delivered_within_53_days",
      "meaning": "True if the quarterly consolidated balance sheet and income and cash flow statements, certified by the specified officer, were delivered no later than 53 days after the quarter end.",
      "source_quote": "a consolidated balance sheet of the Company and its Consolidated Subsidiaries as of the end of such quarter"
    },
    {
