{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n; commitments_expired_or_terminated: true iff the Aggregate Commitments have expired or been terminated at the observation time.\n; loans_fees_paid_in_full: true iff the principal of and interest on each Loan and all fees and other amounts payable under the agreement have been paid in full at the observation time.\n; lcs_expired_and_reimbursed: true iff all Letters of Credit have expired or terminated and all LC Disbursements have been reimbursed in full at the observation time.\n; is_fiscal_quarter_end: true iff the observation date is the last day of a fiscal quarter of the Borrower.\n; is_quarter_on_or_after_june_30_2005: true iff the fiscal quarter ending on the observation date is the fiscal quarter ended June 30, 2005 or a later fiscal quarter.\n; consolidated_ebitda: Consolidated EBITDA for the twelve-month period ended on the observation date.\n; consolidated_interest_expense: Consolidated Interest Expense for the twelve-month period ended on the observation date.\n(define-fun covenant_holds ((commitments_expired_or_terminated Bool)\n                            (loans_fees_paid_in_full Bool)\n                            (lcs_expired_and_reimbursed Bool)\n                            (is_fiscal_quarter_end Bool)\n                            (is_quarter_on_or_after_june_30_2005 Bool)\n                            (consolidated_ebitda Real)\n                            (consolidated_interest_expense Real)) Bool\n  (=> (and (not (and commitments_expired_or_terminated\n                     loans_fees_paid_in_full\n                     lcs_expired_and_reimbursed))\n           is_fiscal_quarter_end\n           is_quarter_on_or_after_june_30_2005)\n      (>= (/ consolidated_ebitda consolidated_interest_expense) 2.25)))",
  "symbols": [
    {
      "name": "commitments_expired_or_terminated",
      "meaning": "True iff the Aggregate Commitments have expired or been terminated at the observation time.",
      "source_quote": "Until the Aggregate Commitments have expired or been terminated"
    },
    {
      "name": "loans_fees_paid_in_full",
      "meaning": "True iff the principal of and interest on each Loan and all fees and other amounts payable under the agreement have been paid in full at the observation time.",
      "source_quote": "the principal of and interest on each Loan and all fees and other amounts payable hereunder have been paid in full"
    },
    {
      "name": "lcs_expired_and_reimbursed",
      "meaning": "True iff all Letters of Credit have expired or terminated and all LC Disbursements have been reimbursed in full at the observation time.",
      "source_quote": "all Letters of Credit have expired or terminated and all LC Disbursements have been reimbursed in full"
    },
    {
      "name": "is_fiscal_quarter_end",
      "meaning": "True iff the observation date is the last day of a fiscal quarter of the Borrower.",
      "source_quote": "the last day of any fiscal quarter"
    },
    {
      "name": "is_quarter_on_or_after_june_30_2005",
      "meaning": "True iff the fiscal quarter ending on the observation date is the fiscal quarter ended June 30, 2005 or a later fiscal quarter.",
      "source_quote": "commencing with the fiscal quarter ended June 30, 2005"
    },
    {
      "name": "consolidated_ebitda",
      "meaning": "Consolidated EBITDA for the twelve-month period ended on the observation date.",
      "source_quote": "Consolidated EBITDA"
    },
    {
      "name": "consolidated_interest_expense",
      "meaning": "Consolidated Interest Expense for the twelve-month period ended on the observation date.",
      "source_quote": "Consolidated Interest Expense"
    }
  ],
  "notes": "The covenant applies only while the termination and payment conditions are not all satisfied, so the active condition is the negation of their conjunction. It is tested at fiscal quarter ends from the quarter ended June 30, 2005. The requirement is EBITDA / Interest Expense >= 2.25 (not less than 2.25 to 1.0), encoded as a division. A zero denominator is left to the evaluator to report as unresolved. QF_NRA is used because the division is by a variable. No sign or positivity assumptions are made."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_LRA)\n; interest_coverage_ratio: Interest Coverage Ratio of the Borrower as of the last day of the Test Period being observed, as a decimal Real (X:1.00 is X).\n; is_test_period_june_30_2013: True iff the observed Test Period ends June 30, 2013.\n; is_test_period_sept_30_2013: True iff the observed Test Period ends September 30, 2013.\n; is_test_period_dec_31_2013: True iff the observed Test Period ends December 31, 2013.\n(define-fun covenant_holds ((interest_coverage_ratio Real) (is_test_period_june_30_2013 Bool) (is_test_period_sept_30_2013 Bool) (is_test_period_dec_31_2013 Bool)) Bool\n  (and\n    (=> is_test_period_june_30_2013 (>= interest_coverage_ratio 1.25))\n    (=> is_test_period_sept_30_2013 (>= interest_coverage_ratio 1.75))\n    (=> is_test_period_dec_31_2013 (>= interest_coverage_ratio 2.25))))",
  "symbols": [
    {
      "name": "interest_coverage_ratio",
      "meaning": "Interest Coverage Ratio of the Borrower as of the last day of the Test Period being observed, as a decimal Real (X:1.00 is X).",
      "source_quote": "the Borrower shall not permit the Interest Coverage Ratio, in each case as of the last day of any Test Period, to be less than the ratio set forth opposite such Test Period below"
    },
    {
      "name": "is_test_period_june_30_2013",
      "meaning": "True iff the observed Test Period ends June 30, 2013.",
      "source_quote": "June 30, 2013 1.25:1.00"
    },
    {
      "name": "is_test_period_sept_30_2013",
      "meaning": "True iff the observed Test Period ends September 30, 2013.",
      "source_quote": "September 30, 2013 1.75:1.00"
    },
    {
      "name": "is_test_period_dec_31_2013",
      "meaning": "True iff the observed Test Period ends December 31, 2013.",
      "source_quote": "December 31, 2013 2.25:1.00"
    }
  ],
  "notes": "The Borrower must not permit the ratio to be less than the stated minimum, so compliance is ratio >= threshold (equality complies). Each test date has its own flag. A date flag that is false imposes no requirement, because the source sets no threshold outside the three listed Test Periods. Consent by the Required Lenders or Supermajority Lenders is a waiver, not a ratio condition, and is not modeled. The 'Commencing with the fiscal quarter ending June 30, 2013' language is covered by the first listed test date."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n(define-fun covenant_holds (\n  (obligations_unpaid Bool) ; true if any Obligations remain unpaid at the observation time\n  (is_fiscal_quarter_end Bool) ; true if the observation time is the end of one of the Company's fiscal quarters\n  (consolidated_ebit Real) ; Consolidated EBIT for the then most-recently ended four fiscal quarters\n  (consolidated_interest_expense Real) ; Consolidated Interest Expense for the then most-recently ended four fiscal quarters\n) Bool\n  (=> (and obligations_unpaid is_fiscal_quarter_end)\n      (not (< (/ consolidated_ebit consolidated_interest_expense) 2.0))))",
  "symbols": [
    {
      "name": "obligations_unpaid",
      "meaning": "True if any Obligations remain unpaid at the observation time, so the covenant is in force.",
      "source_quote": "So long as any Obligations shall remain unpaid"
    },
    {
      "name": "is_fiscal_quarter_end",
      "meaning": "True if the observation time is the end of one of the Company's fiscal quarters.",
      "source_quote": "determined as of the end of each of its fiscal quarters"
    },
    {
      "name": "consolidated_ebit",
      "meaning": "Consolidated EBIT for the then most-recently ended four fiscal quarters, as of the observation date.",
      "source_quote": "Consolidated EBIT"
    },
    {
      "name": "consolidated_interest_expense",
      "meaning": "Consolidated Interest Expense for the then most-recently ended four fiscal quarters, as of the observation date. It is the denominator of the ratio.",
      "source_quote": "Consolidated Interest Expense"
    }
  ],
  "notes": "The covenant applies only while Obligations are unpaid and only at fiscal quarter ends. The ratio is Consolidated EBIT divided by Consolidated Interest Expense over the trailing four fiscal quarters, and it must not be less than 2.0 to 1.0. The check is therefore non-strict (>= 2.0), written as (not (< ratio 2.0)). Exactly 2.0 complies. Division by a zero interest expense is left to the evaluator's unresolved policy, and no positivity is assumed. QF_NRA is used because the denominator is a variable. The EBIT and interest expense definitions are not supplied, so both are atomic Real inputs."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_LRA)\n; is_test_date: true iff this observation is a Section 6.10 test date, i.e. the last day of the most recently ended fiscal quarter for which the Borrowers were required to deliver Section 5.04 financial statements, or the end of a succeeding fiscal quarter.\n; fccr: Consolidated Fixed Charge Coverage Ratio of the Borrowers and their Restricted Subsidiaries for the four fiscal quarter period ending on the test date, as a plain ratio (1.10 to 1.00 = 1.10). EBITDA includes any Cure Action proceeds under Section 6.10(c).\n; total_leverage_ratio: Total Leverage Ratio of the Borrowers and their Restricted Subsidiaries for the four fiscal quarter period ending on the test date, as a plain ratio (4.00 to 1.00 = 4.00). EBITDA includes any Cure Action proceeds under Section 6.10(c).\n; period_ends_jan30_2016_through_oct29_2016: true iff the tested period ends on a date from January 30, 2016 through October 29, 2016.\n; period_ends_on_or_after_jan28_2017: true iff the tested period ends on or after January 28, 2017.\n(define-fun covenant_holds ((is_test_date Bool) (fccr Real) (total_leverage_ratio Real) (period_ends_jan30_2016_through_oct29_2016 Bool) (period_ends_on_or_after_jan28_2017 Bool)) Bool\n  (and\n    (=> is_test_date (>= fccr 1.10))\n    (=> (and is_test_date period_ends_jan30_2016_through_oct29_2016) (<= total_leverage_ratio 4.00))\n    (=> (and is_test_date period_ends_on_or_after_jan28_2017) (<= total_leverage_ratio 3.50))))",
  "symbols": [
    {
      "name": "is_test_date",
      "meaning": "True iff the observation is a Section 6.10 test date: the last day of the most recently ended fiscal quarter for which the Borrowers were required to deliver Section 5.04 financial statements, or the end of a succeeding fiscal quarter.",
      "source_quote": "at the end of each succeeding fiscal quarter thereafter"
    },
    {
      "name": "fccr",
      "meaning": "Consolidated Fixed Charge Coverage Ratio of the Borrowers and their Restricted Subsidiaries for the four fiscal quarter period ending on the test date, as a plain ratio (1.10 to 1.00 = 1.10). EBITDA includes any Cure Action proceeds under Section 6.10(c).",
      "source_quote": "Consolidated Fixed Charge Coverage Ratio of at least 1.10 to 1.00"
    },
    {
      "name": "total_leverage_ratio",
      "meaning": "Total Leverage Ratio of the Borrowers and their Restricted Subsidiaries for the four fiscal quarter period ending on the test date, as a plain ratio (4.00 to 1.00 = 4.00). EBITDA includes any Cure Action proceeds under Section 6.10(c).",
      "source_quote": "shall maintain a Total Leverage Ratio as set out below"
    },
    {
      "name": "period_ends_jan30_2016_through_oct29_2016",
      "meaning": "True iff the tested period ends on a date from January 30, 2016 through October 29, 2016, so the 4.00 to 1.00 maximum applies.",
      "source_quote": "For the period ending January 30, 2016 through the period ending October 29, 2016 4.00 to 1.00"
    },
    {
      "name": "period_ends_on_or_after_jan28_2017",
      "meaning": "True iff the tested period ends on or after January 28, 2017, so the 3.50 to 1.00 maximum applies.",
      "source_quote": "For the period ending January 28, 2017 and thereafter 3.50 to 1.00"
    }
  ],
  "notes": "The Total Leverage Ratio is a maximum: the source says to maintain a ratio 'as set out below' with a 'to 1.00' level, which is read as a ceiling. The covenant sets no explicit direction, so this is an interpretation. Section 6.10(c) is modelled only through its effect on the inputs. Because the ratios include Cure Action proceeds in EBITDA, a valid cure that restores compliance is reflected there. The cure mechanics (the 10 Business Day window, the limits of two Cure Actions per four quarters and five over the term, and the standstill on remedies) are not encoded. They need event-state history that a pointwise test cannot hold, and the standstill is a lender-remedy restriction rather than a borrower financial test. Ratio definitions are not supplied, so both ratios are atomic Real inputs."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n; obligations_outstanding: true when the Section 6.13 covenant period is still running, i.e. the Commitments have not both expired/terminated and all Loan principal, interest and fees been paid in full, and Letters of Credit have not all expired, terminated or been collateralized, without pending draw, with all LC Disbursements reimbursed.\n; is_fiscal_quarter_end: true when the observation date is the end of a fiscal quarter of the Borrower.\n; is_on_or_after_2013_12_31: true when the observation date (fiscal quarter end) is on or after December 31, 2013.\n; consolidated_total_indebtedness: Consolidated Total Indebtedness of the Borrower and its Subsidiaries, consolidated, as of the observation date.\n; consolidated_adjusted_ebitda_ttm: Consolidated Adjusted EBITDA of the Borrower and its Subsidiaries, consolidated, for the four consecutive fiscal quarters ending with the observed fiscal quarter end.\n; consolidated_interest_expense_ttm: Consolidated Interest Expense of the Borrower and its Subsidiaries, consolidated, for the four consecutive fiscal quarters ending with the observed fiscal quarter end.\n(define-fun covenant_holds ((obligations_outstanding Bool) (is_fiscal_quarter_end Bool) (is_on_or_after_2013_12_31 Bool) (consolidated_total_indebtedness Real) (consolidated_adjusted_ebitda_ttm Real) (consolidated_interest_expense_ttm Real)) Bool\n  (=> (and obligations_outstanding is_fiscal_quarter_end is_on_or_after_2013_12_31)\n      (and\n        ; (a) Leverage Ratio must not be greater than 2.50 to 1.00\n        (<= (/ consolidated_total_indebtedness consolidated_adjusted_ebitda_ttm) 2.5)\n        ; (b) Interest Coverage Ratio must not be less than 3.00 to 1.00\n        (>= (/ consolidated_adjusted_ebitda_ttm consolidated_interest_expense_ttm) 3.0))))",
  "symbols": [
    {
      "name": "obligations_outstanding",
      "meaning": "True when the covenant period is still running: the Commitments have not expired or terminated and/or Loan principal, interest and fees have not been paid in full and/or Letters of Credit have not expired, terminated or been collateralized without pending draw, and LC Disbursements have not been reimbursed.",
      "source_quote": "Until the Commitments have expired or terminated and the principal of and interest on each Loan and all fees payable hereunder have been paid in full"
    },
    {
      "name": "is_fiscal_quarter_end",
      "meaning": "True when the observation date is the end of a fiscal quarter of the Borrower.",
      "source_quote": "determined as of the end of each of its fiscal quarters"
    },
    {
      "name": "is_on_or_after_2013_12_31",
      "meaning": "True when the observed fiscal quarter end falls on or after December 31, 2013.",
      "source_quote": "ending on and after December 31, 2013"
    },
    {
      "name": "consolidated_total_indebtedness",
      "meaning": "Consolidated Total Indebtedness of the Borrower and its Subsidiaries on a consolidated basis as of the observed fiscal quarter end.",
      "source_quote": "Consolidated Total Indebtedness"
    },
    {
      "name": "consolidated_adjusted_ebitda_ttm",
      "meaning": "Consolidated Adjusted EBITDA of the Borrower and its Subsidiaries on a consolidated basis for the four consecutive fiscal quarters ending with the observed fiscal quarter end.",
      "source_quote": "Consolidated Adjusted EBITDA for the period of four (4) consecutive fiscal quarters ending with the end of such fiscal quarter"
    },
    {
      "name": "consolidated_interest_expense_ttm",
      "meaning": "Consolidated Interest Expense of the Borrower and its Subsidiaries on a consolidated basis for the four consecutive fiscal quarters ending with the observed fiscal quarter end.",
      "source_quote": "Consolidated Interest Expense"
    }
  ],
  "notes": "Both Section 6.13 financial covenants are combined into one conjunction, applicable only at fiscal quarter ends on or after December 31, 2013 while the Article VI covenant period remains in effect. 'Not greater than 2.50 to 1.00' becomes <= 2.5 and 'not less than 3.00 to 1.00' becomes >= 3.0. The ratios are expressed as the divisions stated in the source. A zero denominator is left to the evaluator to report as unresolved, and no positivity assumptions are added. QF_NRA is used because the divisions are by variables."
