{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n; is_fiscal_quarter_end: true iff the observation date is the last day of a Fiscal Quarter of Holdings.\n; is_quarter_ending_2005_09_30: true iff the Fiscal Quarter ending on this observation date ends 9/30/05.\n; is_quarter_ending_2005_12_31: true iff the Fiscal Quarter ending on this observation date ends 12/31/05.\n; is_quarter_ending_2006_03_31: true iff the Fiscal Quarter ending on this observation date ends 3/31/06.\n; is_quarter_ending_2006_06_30_or_later: true iff the Fiscal Quarter ending on this observation date ends on 6/30/06 or any later date.\n; ebitdar_4q: EBITDAR of Holdings for the period of four Fiscal Quarters ending on the observation date.\n; capital_expenditures_4q: Capital Expenditures for the same four-Fiscal-Quarter period.\n; consolidated_cash_interest_expense_4q: Consolidated Cash Interest Expense for the same period.\n; scheduled_payments_4q: Scheduled Payments for the same period.\n; consolidated_rental_expense_4q: Consolidated Rental Expense for the same period.\n; restricted_payments_4q: Restricted Payments for the same period.\n(define-fun covenant_holds (\n  (is_fiscal_quarter_end Bool)\n  (is_quarter_ending_2005_09_30 Bool)\n  (is_quarter_ending_2005_12_31 Bool)\n  (is_quarter_ending_2006_03_31 Bool)\n  (is_quarter_ending_2006_06_30_or_later Bool)\n  (ebitdar_4q Real)\n  (capital_expenditures_4q Real)\n  (consolidated_cash_interest_expense_4q Real)\n  (scheduled_payments_4q Real)\n  (consolidated_rental_expense_4q Real)\n  (restricted_payments_4q Real)\n) Bool\n  (and\n    (=> (and is_fiscal_quarter_end is_quarter_ending_2005_09_30)\n        (>= (/ (- ebitdar_4q capital_expenditures_4q)\n               (+ consolidated_cash_interest_expense_4q scheduled_payments_4q consolidated_rental_expense_4q restricted_payments_4q))\n            1.15))\n    (=> (and is_fiscal_quarter_end is_quarter_ending_2005_12_31)\n        (>= (/ (- ebitdar_4q capital_expenditures_4q)\n               (+ consolidated_cash_interest_expense_4q scheduled_payments_4q consolidated_rental_expense_4q restricted_payments_4q))\n            1.15))\n    (=> (and is_fiscal_quarter_end is_quarter_ending_2006_03_31)\n        (>= (/ (- ebitdar_4q capital_expenditures_4q)\n               (+ consolidated_cash_interest_expense_4q scheduled_payments_4q consolidated_rental_expense_4q restricted_payments_4q))\n            1.15))\n    (=> (and is_fiscal_quarter_end is_quarter_ending_2006_06_30_or_later)\n        (>= (/ (- ebitdar_4q capital_expenditures_4q)\n               (+ consolidated_cash_interest_expense_4q scheduled_payments_4q consolidated_rental_expense_4q restricted_payments_4q))\n            1.20))))",
