{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n; agreement_period_active: true iff the observation is on or after the date of the Agreement, the Agreement is in effect, and the Commitments have not yet terminated.\n; in_first_four_quarters: true iff the observation falls within the first four (4) quarters after the Execution Date.\n; after_first_four_quarters: true iff the observation falls after that first four-quarter period (\"at any time thereafter\").\n; ebitda_ttm: EBITDA for the preceding four quarters, rolling four-quarter basis, in dollars.\n; taxes_paid_ttm: taxes actually paid during those same four quarters, in dollars.\n; current_ltd_next_4q: current portion of long-term debt for the upcoming four quarters, in dollars.\n; interest_expense_ttm: interest expense for the preceding four quarters, rolling four-quarter basis, in dollars.\n; cash_capex_ttm: uncapped cash Consolidated Capital Expenditures for the preceding four quarters, rolling basis, in dollars. The $2,000,000 cap is applied in the formula.\n(define-fun covenant_holds (\n  (agreement_period_active Bool)\n  (in_first_four_quarters Bool)\n  (after_first_four_quarters Bool)\n  (ebitda_ttm Real)\n  (taxes_paid_ttm Real)\n  (current_ltd_next_4q Real)\n  (interest_expense_ttm Real)\n  (cash_capex_ttm Real)) Bool\n  (=> agreement_period_active\n    (and\n      (=> in_first_four_quarters\n        (>= (/ (- ebitda_ttm taxes_paid_ttm)\n               (+ current_ltd_next_4q\n                  interest_expense_ttm\n                  (ite (<= cash_capex_ttm 2000000.0) cash_capex_ttm 2000000.0)))\n            1.0))\n      (=> after_first_four_quarters\n        (>= (/ (- ebitda_ttm taxes_paid_ttm)\n               (+ current_ltd_next_4q\n                  interest_expense_ttm\n                  (ite (<= cash_capex_ttm 2000000.0) cash_capex_ttm 2000000.0)))\n            2.0)))))",
  "symbols": [
    {
      "name": "agreement_period_active",
      "meaning": "True iff the observation is on or after the date of the Agreement, the Agreement is in effect, and the Commitments have not yet terminated.",
      "source_quote": "on and after the date hereof and for so long as this Agreement is in effect and until the Commitments have terminated"
    },
    {
      "name": "in_first_four_quarters",
      "meaning": "True iff the observation falls within the first four quarters after the Execution Date, where the minimum ratio is 1.0 to 1.0.",
      "source_quote": "for the first four (4) quarters after the Execution Date"
    },
    {
      "name": "after_first_four_quarters",
      "meaning": "True iff the observation falls after the first four quarters following the Execution Date, where the minimum ratio is 2.0 to 1.0.",
      "source_quote": "at any time thereafter"
    },
    {
      "name": "ebitda_ttm",
      "meaning": "EBITDA of the Company for the preceding four quarters on a rolling four-quarter basis, in dollars.",
      "source_quote": "EBITDA calculated for the preceding four (4) quarters on a rolling four (4) quarter basis"
    },
    {
      "name": "taxes_paid_ttm",
      "meaning": "Taxes actually paid during the preceding four quarters, in dollars. It is subtracted from EBITDA in the numerator.",
      "source_quote": "taxes actually paid during such four (4) quarters"
    },
    {
      "name": "current_ltd_next_4q",
      "meaning": "Current portion of long-term debt for the upcoming four quarters, in dollars.",
      "source_quote": "the current portion of long-term debt for the upcoming four (4) quarters"
    },
    {
      "name": "interest_expense_ttm",
      "meaning": "Interest expense for the preceding four quarters on a rolling four-quarter basis, in dollars.",
      "source_quote": "interest expense"
    },
    {
      "name": "cash_capex_ttm",
      "meaning": "Uncapped cash Consolidated Capital Expenditures for the preceding four quarters on a rolling basis, in dollars. The formula caps the amount included in the denominator at 2,000,000.",
      "source_quote": "cash Consolidated Capital Expenditures up to a maximum of $2,000,000.00"
    }
  ],
  "notes": "The covenant forbids the ratio from being less than the threshold, so compliance is ratio >= 1.0 in the first four quarters after the Execution Date and ratio >= 2.0 thereafter. The ratio is (EBITDA - taxes paid) / (current portion of LTD + interest expense + min(cash capex, 2,000,000)). The source says 'both calculated for the preceding four quarters', which I applied to interest expense and capex; the current portion of long-term debt uses the upcoming four quarters. A zero denominator is left to the evaluator to report as unresolved. QF_NRA is used because the ratio divides by a non-constant term. Two separate period flags are used so an observation before the Execution Date, where neither flag is true, gets no threshold."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n; Section 7.3 Fixed Charge Coverage Ratio, evaluated pointwise at an observation time.\n; All period amounts below cover the rolling 4 fiscal quarters ending at the observation date, for Borrower and its Subsidiaries.\n(define-fun covenant_holds (\n  (is_fiscal_quarter_end Bool) ; observation date is the end of a fiscal quarter\n  (obligation_outstanding Bool) ; any Obligation is outstanding at the observation time\n  (bank_commitment_exists Bool) ; the Bank has any commitment under the Agreement at the observation time\n  (net_income Real) ; Borrower's GAAP net income for the rolling 4 quarters, after all expenses, cash taxes paid and other proper charges\n  (noncash_addbacks Real) ; Sum of depreciation, non-cash accretion of closure/post-closure obligations and amortization, to the extent deducted in computing net income, over the rolling 4 quarters\n  (cash_capital_contributions Real) ; Cash capital contributions to Borrower during the rolling 4 quarters\n  (sub_debt_increase Real) ; Increase, if any, in Borrower's Subordinated Debt during the rolling 4 quarters (0 if none)\n  (unfunded_capex Real) ; All unfunded capital expenditures during the rolling 4 quarters\n  (sub_debt_decrease Real) ; Decrease, if any, in Borrower's Subordinated Debt during the rolling 4 quarters (0 if none)\n  (fixed_charges Real) ; Principal payments owing to third parties for money borrowed, including capitalized leases, paid or scheduled to be paid during the rolling 4 quarters, including scheduled reductions in the Reducing Revolving Commitment Amount\n  ) Bool\n  (=> (and is_fiscal_quarter_end (or obligation_outstanding bank_commitment_exists))\n      (>= (/ (- (- (+ (+ (+ net_income noncash_addbacks) cash_capital_contributions) sub_debt_increase) unfunded_capex) sub_debt_decrease)\n             fixed_charges)\n          1.5)))",
