{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n; on_or_after_closing_date: true iff the observation date is on or after the Closing Date.\n; lenders_committed_to_fund: true iff Lenders are still committed to fund Borrowings under this Agreement at the observation time.\n; principal_debt_or_due_obligation_unpaid: true iff the Principal Debt has not been paid in full, or other interest, fees, and amounts of the Obligation then due and owing have not been paid in full.\n; prior_written_consent_received: true iff Borrower has received prior written consent to the contrary from Administrative Agent as authorized by Determining Lenders, covering this covenant at the observation time.\n; total_debt: Total Debt of the Restricted Companies, calculated on a consolidated basis, at the date of determination (currency units).\n; total_capitalization: Total Capitalization of the Restricted Companies, calculated on a consolidated basis, at the date of determination (same currency units).\n(define-fun covenant_holds ((on_or_after_closing_date Bool) (lenders_committed_to_fund Bool) (principal_debt_or_due_obligation_unpaid Bool) (prior_written_consent_received Bool) (total_debt Real) (total_capitalization Real)) Bool\n  (=> (and on_or_after_closing_date\n           (or lenders_committed_to_fund principal_debt_or_due_obligation_unpaid)\n           (not prior_written_consent_received))\n      (<= (/ total_debt total_capitalization) 0.68)))",
  "symbols": [
    {
      "name": "on_or_after_closing_date",
      "meaning": "True iff the observation date is on or after the Closing Date, the start of the covenant period.",
      "source_quote": "from the Closing Date"
