    {
      "name": "lenders_committed_to_fund",
      "meaning": "True iff Lenders are still committed to fund Borrowings under this Agreement at the observation time.",
      "source_quote": "SO LONG THEREAFTER AS Lenders are committed to fund Borrowings under this Agreement"
    },
    {
      "name": "principal_debt_or_due_obligation_unpaid",
      "meaning": "True iff the Principal Debt, or any other interest, fees, or amounts of the Obligation then due and owing, has not been paid in full. This keeps the covenant active after commitments end.",
      "source_quote": "until the payment in full of the Principal Debt and payment in full of all other interest, fees, and other amounts of the Obligation then due and owing"
