    },
    {
      "name": "is_on_or_after_fiscal_quarter_ending_june_30_2012",
      "meaning": "True iff the Test Period ends on or after the fiscal quarter ending June 30, 2012, which is when the covenant begins to apply.",
      "source_quote": "Beginning with the fiscal quarter ending June 30, 2012"
