      "meaning": "True if the observation date is on or after the Effective Date.",
      "source_quote": "on and after the Effective Date"
    },
    {
      "name": "is_commitment_termination_date_occurred",
      "meaning": "True if the Commitment Termination Date has occurred as of the observation.",
      "source_quote": "the Commitment Termination Date"
