      "meaning": "True iff the observation is as of the end of a fiscal quarter of the Borrower and its Subsidiaries; applicability flag for clauses (a) and (b).",
      "source_quote": "as of the end of each fiscal quarter"
    },
    {
      "name": "leverage_ratio",
      "meaning": "Leverage Ratio of the Borrower and its Subsidiaries at the observation, as X in X to 1.0 (atomic input).",
      "source_quote": "a Leverage Ratio less than 3.0 to 1.0"
    },
    {
      "name": "fixed_charge_coverage_ratio",
      "meaning": "Fixed Charge Coverage Ratio of the Borrower and its Subsidiaries at the observation, as X in X to 1.0 (atomic input).",
      "source_quote": "a Fixed Charge Coverage Ratio greater than 1.5 to 1.0"
    },
    {
      "name": "net_worth",
      "meaning": "Net Worth at the observation time, in dollars.",
      "source_quote": "not permit Net Worth to be less than $227,000,000"
    },
    {
      "name": "cumulative_quarterly_net_income_excluding_losses",
      "meaning": "Sum of Net Income for each fiscal quarter from the quarter ending February 28, 1998 through the latest quarter end, with loss quarters counted as zero, in dollars. The 50% factor is applied in the formula.",
      "source_quote": "50% of Net Income for the fiscal quarter then ended (without deductions for losses)"
    },
    {
      "name": "cumulative_equity_net_cash_proceeds",
      "meaning": "Cumulative Net Cash Proceeds from all Equity Transactions after the Closing Date, up to the observation, in dollars. The 75% factor is applied in the formula.",
      "source_quote": "75% of the Net Cash Proceeds from any Equity Transaction subsequent to the Closing Date"
