{
  "status": "formalized",
  "smt2": "(set-logic QF_LRA)\n; current_assets: Borrower's Consolidated current assets at the observation time.\n; current_liabilities: Borrower's Consolidated current liabilities at the observation time, before removing Note principal payments due within one year.\n; note_principal_due_within_one_year: Payments of principal on the Note required to be repaid within one year from the time of calculation. They are excluded from current liabilities in the current ratio.\n; ebitda: Borrower's Consolidated EBITDA as of the end of the Fiscal Quarter.\n; fixed_charges: Borrower's Consolidated Fixed Charges as of the end of the same Fiscal Quarter.\n; is_fiscal_quarter_end: True iff the observation is as of the end of a Fiscal Quarter.\n; is_after_agreement_date: True iff the observation time is after the date of the Agreement (the date hereof).\n; is_after_dec_31_1994: True iff the observation time is after December 31, 1994.\n(define-fun covenant_holds ((current_assets Real) (current_liabilities Real) (note_principal_due_within_one_year Real) (ebitda Real) (fixed_charges Real) (is_fiscal_quarter_end Bool) (is_after_agreement_date Bool) (is_after_dec_31_1994 Bool)) Bool\n  (and\n    ; 5.2(k): current ratio never less than 1.5 to 1.0, with the Note principal due within one year excluded from current liabilities\n    (>= (/ current_assets (- current_liabilities note_principal_due_within_one_year)) 1.5)\n    ; 5.2(l)(A): fixed charge coverage at least 1.0 at quarter-end observations after the date hereof\n    (=> (and is_fiscal_quarter_end is_after_agreement_date)\n        (>= (/ ebitda fixed_charges) 1.0))\n    ; 5.2(l)(B): fixed charge coverage at least 1.5 at quarter-end observations after December 31, 1994\n    (=> (and is_fiscal_quarter_end is_after_dec_31_1994)\n        (>= (/ ebitda fixed_charges) 1.5))))",
  "symbols": [
    {
      "name": "current_assets",
      "meaning": "Borrower's Consolidated current assets at the observation time.",
      "source_quote": "The ratio of Borrower's Consolidated current assets to Borrower's Consolidated current liabilities will never be less than 1.5 to 1.0."
    },
    {
      "name": "current_liabilities",
      "meaning": "Borrower's Consolidated current liabilities at the observation time, before removing Note principal payments due within one year.",
      "source_quote": "The ratio of Borrower's Consolidated current assets to Borrower's Consolidated current liabilities will never be less than 1.5 to 1.0."
    },
    {
      "name": "note_principal_due_within_one_year",
      "meaning": "Payments of principal on the Note required to be repaid within one year from the time of calculation. They are excluded from current liabilities for the current ratio.",
      "source_quote": "payments of principal on the Note which are required to be repaid within one year from the time of calculation"
    },
    {
      "name": "ebitda",
      "meaning": "Borrower's Consolidated EBITDA as of the end of the Fiscal Quarter.",
      "source_quote": "Borrower's Consolidated EBITDA as of the end of each Fiscal Quarter"
    },
    {
      "name": "fixed_charges",
      "meaning": "Borrower's Consolidated Fixed Charges as of the end of the same Fiscal Quarter.",
      "source_quote": "Borrower's Consolidated Fixed Charges as of the end of such Fiscal Quarter"
    },
    {
      "name": "is_fiscal_quarter_end",
      "meaning": "True iff the observation is as of the end of a Fiscal Quarter.",
      "source_quote": "as of the end of each Fiscal Quarter"
    },
    {
      "name": "is_after_agreement_date",
      "meaning": "True iff the observation time is after the date of the Agreement (the date hereof).",
      "source_quote": "at any time after the date hereof"
    },
    {
      "name": "is_after_dec_31_1994",
      "meaning": "True iff the observation time is after December 31, 1994.",
      "source_quote": "at any time after December 31, 1994"
    }
  ],
  "notes": "Formalizes the two quantitative financial ratio covenants in Section 5.2, (k) Working Capital and Current Ratio and (l) Fixed Charge Coverage Ratio. The other negative covenants (debt, liens, mergers, asset sales, dividends and so on) are transaction restrictions or are not stated as ratios, so they are not encoded. Because the evaluator conjoins results over observations, (k) applies at every observation (never less than 1.5). Both (l) thresholds apply on quarter-end observations after their respective dates, so after 1994 the stricter 1.5 requirement governs. The current ratio uses the source definition, with Note principal due within one year subtracted from current liabilities. Division by zero is left to the evaluator to report as unresolved. No positivity assumptions are made."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n; note_unpaid: true if the Note remains unpaid at the observation time.\n; commitment_outstanding: true if the Bank has any Commitment under the Agreement at the observation time.\n; is_date_1996_06_30: true if the observation date is 6/30/96.\n; is_date_1996_09_30: true if the observation date is 9/30/96.\n; is_date_1996_12_31: true if the observation date is 12/31/96.\n; total_unsubordinated_liabilities: the Borrower's Total Unsubordinated Liabilities at the observation date (numerator A of the leverage ratio).\n; effective_net_worth: the Borrower's Effective Net Worth at the observation date (denominator B of the leverage ratio).\n(define-fun covenant_holds ((note_unpaid Bool) (commitment_outstanding Bool) (is_date_1996_06_30 Bool) (is_date_1996_09_30 Bool) (is_date_1996_12_31 Bool) (total_unsubordinated_liabilities Real) (effective_net_worth Real)) Bool\n  (=> (or note_unpaid commitment_outstanding)\n      (and (=> is_date_1996_06_30 (<= (/ total_unsubordinated_liabilities effective_net_worth) 1.5))\n           (=> is_date_1996_09_30 (<= (/ total_unsubordinated_liabilities effective_net_worth) 1.25))\n           (=> is_date_1996_12_31 (<= (/ total_unsubordinated_liabilities effective_net_worth) 1.0)))))",
  "symbols": [
    {
      "name": "note_unpaid",
      "meaning": "True if the Note remains unpaid at the observation time.",
      "source_quote": "the Note shall remain unpaid"
    },
    {
      "name": "commitment_outstanding",
      "meaning": "True if the Bank has any Commitment under the Agreement at the observation time.",
      "source_quote": "the Bank shall have any Commitment under this Agreement"
    },
    {
      "name": "is_date_1996_06_30",
      "meaning": "True if the observation date is 6/30/96, where the maximum ratio is 1.5:1.0.",
      "source_quote": "6/30/96 1.5:1.0"
    },
    {
      "name": "is_date_1996_09_30",
      "meaning": "True if the observation date is 9/30/96, where the maximum ratio is 1.25:1.0.",
      "source_quote": "9/30/96 1.25:1.0"
    },
    {
      "name": "is_date_1996_12_31",
      "meaning": "True if the observation date is 12/31/96, where the maximum ratio is 1.0:1.0.",
      "source_quote": "12/31/96 1.0:1.0"
    },
    {
      "name": "total_unsubordinated_liabilities",
      "meaning": "The Borrower's Total Unsubordinated Liabilities at the observation date (numerator A of the leverage ratio).",
      "source_quote": "Total Unsubordinated Liabilities"
    },
    {
      "name": "effective_net_worth",
      "meaning": "The Borrower's Effective Net Worth at the observation date (denominator B of the leverage ratio).",
