}

{
  "status": "formalized",
  "smt2": "(set-logic QF_LRA)\n; total_leverage_ratio: Total Leverage Ratio of the Borrower at the observation time, as a ratio to 1.00 (3.00 means 3.00 to 1.00).\n; interest_coverage_ratio: Interest Coverage Ratio of the Borrower at the observation time, as a ratio to 1.00 (2.50 means 2.50 to 1.00).\n; obligations_outstanding_and_unpaid: true iff any of the Obligations are outstanding and unpaid at the observation time.\n; commitment_outstanding: true iff the Commitment is outstanding (not terminated) at the observation time.\n; letter_of_credit_outstanding: true iff any Letter of Credit is outstanding at the observation time.\n(define-fun covenant_holds ((total_leverage_ratio Real) (interest_coverage_ratio Real) (obligations_outstanding_and_unpaid Bool) (commitment_outstanding Bool) (letter_of_credit_outstanding Bool)) Bool\n  (=> (or obligations_outstanding_and_unpaid commitment_outstanding letter_of_credit_outstanding)\n      (and (<= total_leverage_ratio 3.00)\n           (>= interest_coverage_ratio 2.50))))",
  "symbols": [
    {
      "name": "total_leverage_ratio",
      "meaning": "Total Leverage Ratio of the Borrower at the observation time, as a ratio to 1.00 (3.00 means 3.00 to 1.00). Treated as an atomic input because its definition is not supplied.",
      "source_quote": "Total Leverage Ratio"
    },
    {
      "name": "interest_coverage_ratio",
      "meaning": "Interest Coverage Ratio of the Borrower at the observation time, as a ratio to 1.00 (2.50 means 2.50 to 1.00). Treated as an atomic input because its definition is not supplied.",
      "source_quote": "Interest Coverage Ratio"
    },
    {
      "name": "obligations_outstanding_and_unpaid",
      "meaning": "True iff any of the Obligations are outstanding and unpaid at the observation time.",
      "source_quote": "any of the Obligations are outstanding and unpaid"
    },
    {
      "name": "commitment_outstanding",
      "meaning": "True iff the Commitment is outstanding (not terminated) at the observation time.",
      "source_quote": "the Commitment"
    },
    {
      "name": "letter_of_credit_outstanding",
