{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n; is_fiscal_quarter_end: true iff the observation date is the end of a fiscal quarter of the Borrower.\n; indebtedness: Indebtedness of the Borrower and its Subsidiaries on a consolidated basis, as of the observation date.\n; stockholders_equity: Stockholders' Equity of the Borrower and its Subsidiaries on a consolidated basis, as of the observation date.\n(define-fun covenant_holds ((is_fiscal_quarter_end Bool) (indebtedness Real) (stockholders_equity Real)) Bool\n  (=> is_fiscal_quarter_end\n      (<= (/ indebtedness (+ indebtedness stockholders_equity)) 0.65)))",
  "symbols": [
    {
      "name": "is_fiscal_quarter_end",
      "meaning": "True iff the observation date is the end of a fiscal quarter of the Borrower.",
      "source_quote": "as of the end of any fiscal quarter of the Borrower"
    },
    {
      "name": "indebtedness",
      "meaning": "Indebtedness of the Borrower and its Subsidiaries on a consolidated basis, as of the observation date. It is the numerator of the ratio and one addend of the denominator.",
      "source_quote": "the ratio of (a) Indebtedness to (b) the sum of Indebtedness and Stockholders' Equity"
    },
    {
      "name": "stockholders_equity",
      "meaning": "Stockholders' Equity of the Borrower and its Subsidiaries on a consolidated basis, as of the observation date. It is the second addend of the denominator.",
      "source_quote": "the sum of Indebtedness and Stockholders' Equity"
    }
  ],
  "notes": "The covenant applies only at fiscal quarter end. At that point the ratio Indebtedness / (Indebtedness + Stockholders' Equity) must not exceed 65.0%, which is encoded as <= 0.65. The ratio is computed explicitly from its stated definition. A zero denominator is left to the evaluator to report as unresolved, and no positivity assumptions are added. QF_NRA is used because the division is by a non-constant term. The 'So long as any Lender shall have any Commitment...' lead-in is a duration condition. It is not modeled as a separate input because the evaluator supplies observations only during that period."
}

{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n; is_fiscal_quarter_end: true iff the observation date is the last day of a fiscal quarter, the end of a four-quarter test period\n; in_period_1: true iff that fiscal quarter end date falls in March 30, 2001 to June 29, 2002 (required ratio 1.20 to 1.00)\n; in_period_2: true iff that fiscal quarter end date falls in June 30, 2002 to June 29, 2003 (required ratio 1.25 to 1.00)\n; in_period_3: true iff that fiscal quarter end date is on or after June 30, 2003 (required ratio 1.50 to 1.00)\n; consolidated_ebitda: Consolidated EBITDA for the four consecutive fiscal quarters ending on the observation date\n; cash_held: cash held on the observation date by Holdings, either Borrower and the Subsidiaries, excluding cash held by Excluded Subsidiaries; for each non-Core-Loan-Party Subsidiary in which Holdings does not directly or indirectly hold 100% of the Equity Interests, the Subsidiary's cash is already replaced by actual cash times Holdings' ownership percentage\n; permitted_investments_carrying_value: carrying value on the observation date of Permitted Investments reflected as cash or short-term investments on Holdings's consolidated balance sheet, excluding those held by Excluded Subsidiaries; for each non-Core-Loan-Party Subsidiary in which Holdings does not hold 100% of the Equity Interests, the Subsidiary's carrying value is already replaced by actual carrying value times Holdings' ownership percentage\n; revolving_swingline_loans_outstanding: aggregate principal amount of Revolving Loans and Swingline Loans outstanding on the observation date\n; consolidated_fixed_charges: Consolidated Fixed Charges for the four consecutive fiscal quarter period ending on the observation date\n(define-fun covenant_holds (\n  (is_fiscal_quarter_end Bool)\n  (in_period_1 Bool)\n  (in_period_2 Bool)\n  (in_period_3 Bool)\n  (consolidated_ebitda Real)\n  (cash_held Real)\n  (permitted_investments_carrying_value Real)\n  (revolving_swingline_loans_outstanding Real)\n  (consolidated_fixed_charges Real)) Bool\n  (ite is_fiscal_quarter_end\n    (let ((ratio (/ (- (+ consolidated_ebitda (+ cash_held permitted_investments_carrying_value)) revolving_swingline_loans_outstanding) consolidated_fixed_charges)))\n      (and\n        (=> in_period_1 (>= ratio 1.2))\n        (=> in_period_2 (>= ratio 1.25))\n        (=> in_period_3 (>= ratio 1.5))))\n    true))",
  "symbols": [
    {
      "name": "is_fiscal_quarter_end",
