      "meaning": "True iff the observation date is the last day of a Fiscal Quarter.",
      "source_quote": "as of the last day of each Fiscal Quarter"
    },
    {
      "name": "is_borrowing_date",
      "meaning": "True iff the observation date is the date of a Borrowing.",
      "source_quote": "as of the date of each Borrowing"
    },
    {
      "name": "in_period_1",
      "meaning": "True iff the observation date is within 3/31/00 through 12/30/00 (maximum 4.50:1.00).",
      "source_quote": "3/31/00 through 12/30/00 4.50 : 1.00"
    },
    {
      "name": "in_period_2",
      "meaning": "True iff the observation date is within 12/31/00 through 6/29/01 (maximum 4.00:1.00).",
      "source_quote": "12/31/00 through 6/29/01 4.00 : 1.00"
    },
    {
      "name": "in_period_3",
