{
  "status": "formalized",
  "smt2": "(set-logic QF_NRA)\n; ebit: EBIT of the Borrower for the measurement period (1, 2, 3 or 4 Fiscal Quarters) selected by the true period flag(s) at this observation.\n; adjusted_net_interest_expense: Adjusted Net Interest Expense of the Borrower for the same measurement period as ebit.\n; is_one_quarter_ending_1998_12_31: True iff this observation is the end of the Fiscal Quarter ending December 31, 1998, with the one-quarter period measured.\n; is_two_quarters_ending_1998_12_31: True iff this observation is for the two Fiscal Quarters ending December 31, 1998.\n; is_two_quarters_ending_1999_03_31: True iff this observation is for the two Fiscal Quarters ending March 31, 1999.\n; is_three_quarters_ending_1999_06_30: True iff this observation is for the three Fiscal Quarters ending June 30, 1999.\n; is_four_quarters_ending_1999_09_30: True iff this observation is for the four Fiscal Quarters ending September 30, 1999.\n; is_four_quarters_ending_1999_12_31_or_later: True iff this observation is the end of a Fiscal Quarter that is December 31, 1999 or later, with the trailing four Fiscal Quarter period measured.\n(define-fun covenant_holds ((ebit Real) (adjusted_net_interest_expense Real) (is_one_quarter_ending_1998_12_31 Bool) (is_two_quarters_ending_1998_12_31 Bool) (is_two_quarters_ending_1999_03_31 Bool) (is_three_quarters_ending_1999_06_30 Bool) (is_four_quarters_ending_1999_09_30 Bool) (is_four_quarters_ending_1999_12_31_or_later Bool)) Bool\n  (and\n    (=> is_one_quarter_ending_1998_12_31 (>= (/ ebit adjusted_net_interest_expense) 3.0))\n    (=> is_two_quarters_ending_1998_12_31 (>= (/ ebit adjusted_net_interest_expense) 3.0))\n    (=> is_two_quarters_ending_1999_03_31 (>= (/ ebit adjusted_net_interest_expense) 2.9))\n    (=> is_three_quarters_ending_1999_06_30 (>= (/ ebit adjusted_net_interest_expense) 2.9))\n    (=> is_four_quarters_ending_1999_09_30 (>= (/ ebit adjusted_net_interest_expense) 2.9))\n    (=> is_four_quarters_ending_1999_12_31_or_later (>= (/ ebit adjusted_net_interest_expense) 2.9))))",
  "symbols": [
    {
      "name": "ebit",
      "meaning": "EBIT of the Borrower for the measurement period (1, 2, 3 or 4 Fiscal Quarters) selected by the true period flag(s) at this observation.",
      "source_quote": "a ratio of (a) EBIT to (b) Adjusted Net Interest Expense"
    },
    {
      "name": "adjusted_net_interest_expense",
      "meaning": "Adjusted Net Interest Expense of the Borrower for the same measurement period as ebit.",
      "source_quote": "Adjusted Net Interest Expense of at least the amount set forth below for the applicable period"
    },
    {
      "name": "is_one_quarter_ending_1998_12_31",
      "meaning": "True iff this observation is the end of the Fiscal Quarter ending December 31, 1998, with the one-quarter period measured.",
      "source_quote": "3.00 to 1 for the Fiscal Quarter ending December 31, 1998"
    },
    {
      "name": "is_two_quarters_ending_1998_12_31",
      "meaning": "True iff this observation is for the two Fiscal Quarters ending December 31, 1998.",
      "source_quote": "3.00 to 1 for the two Fiscal Quarters ending December 31, 1998"
    },
    {
      "name": "is_two_quarters_ending_1999_03_31",
      "meaning": "True iff this observation is for the two Fiscal Quarters ending March 31, 1999.",
      "source_quote": "2.90 to 1 for the two Fiscal Quarters ending March 31, 1999"
    },
    {
      "name": "is_three_quarters_ending_1999_06_30",
      "meaning": "True iff this observation is for the three Fiscal Quarters ending June 30, 1999.",
      "source_quote": "2.90 to 1 for the three Fiscal Quarters ending June 30, 1999"
    },
    {
      "name": "is_four_quarters_ending_1999_09_30",
      "meaning": "True iff this observation is for the four Fiscal Quarters ending September 30, 1999.",
      "source_quote": "2.90 to 1 for the four Fiscal Quarters ending September 30, 1999"
