  "smt2": "(set-logic QF_LRA)\n; is_on_or_after_closing_date: true if the observation time is on or after the Closing Date.\n; all_obligations_discharged: true if the Commitments have expired or terminated, no Letter of Credit remains outstanding, and principal, interest, fees and other amounts payable are paid in full (other than contingent indemnification obligations as to which no claim has been asserted).\n; rjp_made_or_declared: true if the Company or any Subsidiary, directly or indirectly, declares, orders, pays, makes or sets apart a sum for a Restricted Junior Payment at this observation.\n; is_subsidiary_ratable_rjp: true if the Restricted Junior Payment is made or declared by a Subsidiary ratably with respect to any class of its Capital Stock.\n; is_employee_equity_repurchase_rjp: true if the Restricted Junior Payment is made by the Company to repurchase, redeem, retire, cancel or acquire for value Capital Stock or equity appreciation rights of the Company or any direct or indirect parent held by a future, present or former director, officer, member of management, employee or consultant of the Company or any Subsidiary (or the estate, heirs, family members, spouse or former spouse of any of them).\n; employee_repurchase_fy_aggregate_usd: aggregate USD amount of Restricted Junior Payments of the clause (b) type in the current Fiscal Year, including this payment.\n; default_exists_or_would_result: true if an Event of Default or Default has occurred and is continuing or would be caused by this Restricted Junior Payment.\n; other_rjp_fy_aggregate_usd: aggregate USD amount of other Restricted Junior Payments under clause (c)(i) in the current Fiscal Year, including this payment.\n; pro_forma_total_leverage_ratio: Total Leverage Ratio on a Pro Forma Basis after giving effect to this Restricted Junior Payment and any Indebtedness incurred in connection therewith.\n(define-fun covenant_holds (\n    (is_on_or_after_closing_date Bool)\n    (all_obligations_discharged Bool)\n    (rjp_made_or_declared Bool)\n    (is_subsidiary_ratable_rjp Bool)\n    (is_employee_equity_repurchase_rjp Bool)\n    (employee_repurchase_fy_aggregate_usd Real)\n    (default_exists_or_would_result Bool)\n    (other_rjp_fy_aggregate_usd Real)\n    (pro_forma_total_leverage_ratio Real)) Bool\n  (=> (and is_on_or_after_closing_date\n           (not all_obligations_discharged)\n           rjp_made_or_declared)\n      (or is_subsidiary_ratable_rjp\n          (and is_employee_equity_repurchase_rjp\n               (<= employee_repurchase_fy_aggregate_usd 5000000.0))\n          (and (not default_exists_or_would_result)\n               (or (<= other_rjp_fy_aggregate_usd 150000000.0)\n                   (<= pro_forma_total_leverage_ratio 3.5))))))",
